INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95795, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '610d24dd-dceb-4fc2-83b6-fe32f33b0c96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95795, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "交谈是两个人面对面说话。", "primary_collocate": null, "pronunciation": "jiāo tán", "ipa": "tɕjɑʊ̯˥ tʰan˧˥", "syllable_count": 2, "sentences": [{"text": "两个人坐在桌子两边，轻声交谈。", "target_word": "交谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师和家长在办公室里交谈了很久。", "target_word": "交谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在火车上和一位老人交谈过。", "target_word": "交谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们面对面坐着，亲切地交谈。", "target_word": "交谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆里请不要大声交谈。", "target_word": "交谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王经理正和客人交谈，请你等一下。", "target_word": "交谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友们一边喝茶，一边愉快地交谈着。", "target_word": "交谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想和你单独交谈几分钟。", "target_word": "交谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们交谈了十分钟，就成了好朋友。", "target_word": "交谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门外传来两个人交谈的声音。", "target_word": "交谈", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "交谈了", "label": "体标"}, {"form": "交谈过", "label": "体标"}, {"form": "交谈着", "label": "体标"}, {"form": "交談", "label": "繁体"}], "register": "中性", "sense_fingerprint": "两个人面对面说话", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6ff1bd0-a59b-4b61-b6ac-44883ef294ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95795, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "交谈", "is_correct": true, "explanation": "正确。交谈指彼此说话，符合“轻声”和“两个人坐在桌子两边”的语境。"}, {"text": "大笑", "is_correct": false, "explanation": "语义：大笑是高声地笑，与“轻声”矛盾。"}, {"text": "呼喊", "is_correct": false, "explanation": "语义：呼喊要大声叫人，与“轻声”矛盾。"}, {"text": "拥抱", "is_correct": false, "explanation": "搭配：拥抱需要身体靠近，与“坐在桌子两边”不搭配。"}], "explanations": {"交谈": "正确。交谈指彼此说话，符合“轻声”和“两个人坐在桌子两边”的语境。", "大笑": "语义：大笑是高声地笑，与“轻声”矛盾。", "呼喊": "语义：呼喊要大声叫人，与“轻声”矛盾。", "拥抱": "搭配：拥抱需要身体靠近，与“坐在桌子两边”不搭配。"}, "sentence_index": 0, "correct_answer": "交谈"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一个人待在房间里，交谈了两个小时。", "explanation": "这里不能用〈交谈〉。交谈指彼此谈话，至少需要两个人，一个人不能交谈，应该说“自言自语”或“说话”。"}, {"text": "两位作家一起交谈了三年的小说。", "explanation": "这里应该用〈写〉。交谈是不及物动词，不能带“小说”这样的宾语，应说“写小说”。"}, {"text": "老师在台上交谈了三个小时，台下的学生一句话也没说。", "explanation": "这里应该用〈讲课〉。交谈要求彼此都开口，学生一句话也没说就不是交谈，只是老师在讲。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '610d24dd-dceb-4fc2-83b6-fe32f33b0c96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95795, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "交谈", "is_correct": true, "explanation": "正确。交谈表示愉快地彼此说话，符合句意。"}, {"text": "哭泣", "is_correct": false, "explanation": "语义：哭泣表示悲伤，与“愉快地”矛盾。"}, {"text": "怒吼", "is_correct": false, "explanation": "语义：怒吼是愤怒地大声喊，与“愉快地”矛盾。"}, {"text": "反对", "is_correct": false, "explanation": "配价：“反对”需要带对象（反对什么），句中没有；而且与“愉快地”不协调。"}], "explanations": {"交谈": "正确。交谈表示愉快地彼此说话，符合句意。", "哭泣": "语义：哭泣表示悲伤，与“愉快地”矛盾。", "怒吼": "语义：怒吼是愤怒地大声喊，与“愉快地”矛盾。", "反对": "配价：“反对”需要带对象（反对什么），句中没有；而且与“愉快地”不协调。"}, "sentence_index": 6, "correct_answer": "交谈"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个问题他交谈了一遍。", "explanation": "这里应该用〈讨论〉。交谈是不及物动词，不能带“问题”作宾语，应说“讨论这个问题”。"}, {"text": "他们面对面坐着，却一句话也没说，一直在交谈。", "explanation": "这里不能用〈交谈〉。交谈要求双方都开口，一句话也没说就不是交谈，应说“沉默”。"}, {"text": "这只猫交谈了这些鱼一下，然后就走了。", "explanation": "这里应该用〈吃〉。交谈是不及物动词，不能带“鱼”这样的宾语，应改用“吃”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '610d24dd-dceb-4fc2-83b6-fe32f33b0c96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95795, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天老同学交谈了很久。", "corrected_sentence": "我昨天和老同学交谈了很久。", "error_description": "“交谈”后面要用“和”引出对象，漏掉“和”，应为“我昨天和老同学交谈了很久”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '610d24dd-dceb-4fc2-83b6-fe32f33b0c96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95795, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们俩在咖啡馆把交谈了一个多小时。", "corrected_sentence": "我们俩在咖啡馆交谈了一个多小时。", "error_description": "错误：“交谈”是不及物动词，不能放进“把”字句提宾语，“把交谈了”不成立。删去“把”即为正确句“我们俩在咖啡馆交谈了一个多小时。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '610d24dd-dceb-4fc2-83b6-fe32f33b0c96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
