INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95796, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '610d24dd-dceb-4fc2-83b6-fe32f33b0c96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95796, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "彼此谈话。", "primary_collocate": null, "pronunciation": "jiāo tán", "ipa": "tɕjɑʊ̯˥ tʰan˧˥", "syllable_count": 2, "sentences": [{"text": "会议开始前，大家互相交谈。", "target_word": "交谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们俩交谈得很开心。", "target_word": "交谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生耐心地和病人交谈。", "target_word": "交谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在电话里交谈了一个小时。", "target_word": "交谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者与市长交谈了二十分钟。", "target_word": "交谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚饭后，一家人坐在一起交谈。", "target_word": "交谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很害羞，不敢和陌生人交谈。", "target_word": "交谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国代表友好地交谈着。", "target_word": "交谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们用汉语交谈，没有问题。", "target_word": "交谈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们交谈过几次，彼此很了解。", "target_word": "交谈", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "交谈了", "label": "体标"}, {"form": "交谈过", "label": "体标"}, {"form": "交谈着", "label": "体标"}, {"form": "交談", "label": "繁体"}], "register": "中性", "sense_fingerprint": "彼此谈话", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6ff1bd0-a59b-4b61-b6ac-44883ef294ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95796, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "交谈", "is_correct": true, "explanation": "正确。交谈表示彼此说话，与“互相”相符。"}, {"text": "独处", "is_correct": false, "explanation": "语义：独处是一个人待着，与“互相”的双方关系矛盾。"}, {"text": "隔离", "is_correct": false, "explanation": "语义：隔离是使人分开，与“互相”的交流意味相反。"}, {"text": "散开", "is_correct": false, "explanation": "搭配：“散开”指各自离去、分散，不能与“互相”搭配。"}], "explanations": {"交谈": "正确。交谈表示彼此说话，与“互相”相符。", "独处": "语义：独处是一个人待着，与“互相”的双方关系矛盾。", "隔离": "语义：隔离是使人分开，与“互相”的交流意味相反。", "散开": "搭配：“散开”指各自离去、分散，不能与“互相”搭配。"}, "sentence_index": 0, "correct_answer": "交谈"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "校长在大会上交谈了一个小时。", "explanation": "这里应该用〈讲话〉。讲话是一方对听众说，交谈要求彼此都说话。"}, {"text": "他一个人对着镜子交谈了半天。", "explanation": "这里不能用〈交谈〉。交谈需要彼此对话，一个人对着镜子不能算交谈。"}, {"text": "两个人为这件事交谈了很久，却一句话也没说。", "explanation": "这里不能用〈交谈〉。交谈要求彼此都开口，谁也没说话就不是交谈，应说“沉默”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '610d24dd-dceb-4fc2-83b6-fe32f33b0c96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95796, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "交谈", "is_correct": true, "explanation": "正确。交谈指和陌生人说话，符合“不敢”的语境。"}, {"text": "投诉", "is_correct": false, "explanation": "配价：“投诉”需要带对象（投诉谁或什么），句中没有，且“和陌生人投诉”不成立。"}, {"text": "大笑", "is_correct": false, "explanation": "语义：大笑是放声地笑，与“害羞”矛盾。"}, {"text": "推销", "is_correct": false, "explanation": "配价：“推销”需要带对象（推销什么），句中没有；而且与“害羞”不协调。"}], "explanations": {"交谈": "正确。交谈指和陌生人说话，符合“不敢”的语境。", "投诉": "配价：“投诉”需要带对象（投诉谁或什么），句中没有，且“和陌生人投诉”不成立。", "大笑": "语义：大笑是放声地笑，与“害羞”矛盾。", "推销": "配价：“推销”需要带对象（推销什么），句中没有；而且与“害羞”不协调。"}, "sentence_index": 6, "correct_answer": "交谈"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这封信他交谈了很久。", "explanation": "这里应该用〈读〉。交谈是不及物动词，不能带“信”这样的宾语，应说“读信”。"}, {"text": "他们俩交谈了那扇门，结果门坏了。", "explanation": "这里应该用〈踢〉。交谈是不及物动词，不能带“门”作宾语，应说“踢门”。"}, {"text": "这只狗交谈了那根骨头，然后就走了。", "explanation": "这里应该用〈啃〉。交谈是不及物动词，不能带“骨头”作宾语，应说“啃骨头”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '610d24dd-dceb-4fc2-83b6-fe32f33b0c96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95796, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们俩在公园里和交谈得很开心。", "corrected_sentence": "他们俩在公园里交谈得很开心。", "error_description": "错误：介词“和”后面必须接名词性对象，不能直接接动词“交谈”。删去多余的“和”，即为“他们俩在公园里交谈得很开心。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '610d24dd-dceb-4fc2-83b6-fe32f33b0c96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95796, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们在饭店里被交谈了很久。", "corrected_sentence": "他们在饭店里交谈了很久。", "error_description": "“被”字句不能用于不及物动词“交谈”，应为“他们在饭店里交谈了很久”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '610d24dd-dceb-4fc2-83b6-fe32f33b0c96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95801, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "困难", "is_correct": true, "explanation": "正确答案。“便利”与“困难”相反：便利指做事方便、不费力，困难指做事不容易。"}, {"text": "漂亮", "is_correct": false, "explanation": "“漂亮”形容外貌好看，与“便利”没有反义关系。"}, {"text": "聪明", "is_correct": false, "explanation": "“聪明”形容人的智力，与“便利”没有反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "“安静”与“吵闹”相对，与“便利”没有反义关系。"}], "correct_answer": "困难", "explanations": {"困难": "正确答案。“便利”与“困难”相反：便利指做事方便、不费力，困难指做事不容易。", "漂亮": "“漂亮”形容外貌好看，与“便利”没有反义关系。", "聪明": "“聪明”形容人的智力，与“便利”没有反义关系。", "安静": "“安静”与“吵闹”相对，与“便利”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f28fec-a946-448c-81b5-b965873f593e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95801, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "困难", "is_correct": true, "explanation": "正确答案。“便利”与“困难”相反：便利指做事方便、不费力，困难指做事不容易。"}, {"text": "明亮", "is_correct": false, "explanation": "“明亮”形容光线或颜色，与“便利”没有反义关系。"}, {"text": "高大", "is_correct": false, "explanation": "“高大”形容身材或体积，与“便利”没有反义关系。"}, {"text": "勇敢", "is_correct": false, "explanation": "“勇敢”形容人的胆量，与“便利”没有反义关系。"}], "correct_answer": "困难", "explanations": {"困难": "正确答案。“便利”与“困难”相反：便利指做事方便、不费力，困难指做事不容易。", "明亮": "“明亮”形容光线或颜色，与“便利”没有反义关系。", "高大": "“高大”形容身材或体积，与“便利”没有反义关系。", "勇敢": "“勇敢”形容人的胆量，与“便利”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f28fec-a946-448c-81b5-b965873f593e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95801, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "便利是做事很方便，不费力。", "primary_collocate": null, "pronunciation": "biàn lì", "ipa": "pʰjɛn˥˩ li˥˩", "syllable_count": 2, "sentences": [{"text": "这里的交通很便利。", "target_word": "便利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上买东西非常便利。", "target_word": "便利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住在地铁站旁边，上班很便利。", "target_word": "便利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机让我们的生活更便利。", "target_word": "便利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家银行离我家很近，去办事很便利。", "target_word": "便利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新的机器用起来很便利。", "target_word": "便利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他家附近买菜很便利。", "target_word": "便利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网络让学习变得便利了。", "target_word": "便利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "楼下就有药店，买药很便利。", "target_word": "便利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有了车，去山上便利多了。", "target_word": "便利", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "便利店", "label": "复合"}, {"form": "便利贴", "label": "复合"}], "register": "中性", "sense_fingerprint": "做事方便、不费力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1881d9c-7008-468f-b42e-60222934a602') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95801, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "便利", "is_correct": true, "explanation": "正确答案。便利指做事很方便、不费力。"}, {"text": "电力", "is_correct": false, "explanation": "diàn（第四声）与 biàn（第四声）声母不同（d 与 b），意思是电力。"}, {"text": "建立", "is_correct": false, "explanation": "jiàn（第四声）与 biàn（第四声）声母不同（j 与 b），意思是建立。"}, {"text": "便秘", "is_correct": false, "explanation": "mì（第四声）与 lì（第四声）声母不同（m 与 l），意思是便秘。"}], "explanations": {"便利": "正确答案。便利指做事很方便、不费力。", "电力": "diàn（第四声）与 biàn（第四声）声母不同（d 与 b），意思是电力。", "建立": "jiàn（第四声）与 biàn（第四声）声母不同（j 与 b），意思是建立。", "便秘": "mì（第四声）与 lì（第四声）声母不同（m 与 l），意思是便秘。"}, "sentence_index": null, "correct_answer": "便利"}, "level_3": {"options": [{"text": "便利", "is_correct": true, "explanation": "正确答案。“这里的交通很便利”说明交通方便，与“很”搭配。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：“聪明”形容人的智力，不能用来形容交通。"}, {"text": "热情", "is_correct": false, "explanation": "语义：“热情”形容人的态度，交通不会热情，句子说不通。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容人或物体的外形，不能说“交通很高大”。"}], "explanations": {"便利": "正确答案。“这里的交通很便利”说明交通方便，与“很”搭配。", "聪明": "语义：“聪明”形容人的智力，不能用来形容交通。", "热情": "语义：“热情”形容人的态度，交通不会热情，句子说不通。", "高大": "体貌：“高大”形容人或物体的外形，不能说“交通很高大”。"}, "sentence_index": 0, "correct_answer": "便利"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服很便利，只要十块钱。", "explanation": "这里应该用〈便宜〉。便利说做事方便、不费力，说价格低要用“便宜”。"}, {"text": "今天的考试很便利。", "explanation": "这里应该用〈顺利〉。便利指办事方便、省力，说事情进展顺利要用“顺利”。"}, {"text": "他很便利，随时都能帮我。", "explanation": "这里应该用〈方便〉。便利用于事物或办事的条件，不用来形容人有空、可以找。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f28fec-a946-448c-81b5-b965873f593e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95801, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "便利", "is_correct": true, "explanation": "正确答案。“他家附近”买菜方便，“很便利”说明买菜方便。"}, {"text": "遥远", "is_correct": false, "explanation": "语义：“他家附近”说明距离近，“遥远”与“附近”矛盾。"}, {"text": "幽默", "is_correct": false, "explanation": "语义：“幽默”形容人的说话风格，买菜不能幽默，句子说不通。"}, {"text": "矮小", "is_correct": false, "explanation": "体貌：“矮小”形容人或物体的外形，不能说“买菜很矮小”。"}], "explanations": {"便利": "正确答案。“他家附近”买菜方便，“很便利”说明买菜方便。", "遥远": "语义：“他家附近”说明距离近，“遥远”与“附近”矛盾。", "幽默": "语义：“幽默”形容人的说话风格，买菜不能幽默，句子说不通。", "矮小": "体貌：“矮小”形容人或物体的外形，不能说“买菜很矮小”。"}, "sentence_index": 6, "correct_answer": "便利"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的汉语很便利，说得又快又好。", "explanation": "这里应该用〈流利〉。便利形容做事方便，说外语熟练要用“流利”。"}, {"text": "面试前我很便利。", "explanation": "这里应该用〈紧张〉。便利形容事情方便，不能用来形容人的心理状态。"}, {"text": "这场比赛很便利，选手们都很兴奋。", "explanation": "这里应该用〈精彩〉。便利说做事方便，比赛的好坏不用“便利”来评价。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f28fec-a946-448c-81b5-b965873f593e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95801, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "网上可以便利的查到资料。", "corrected_sentence": "网上可以便利地查到资料。", "error_description": "的地误用：“便利”修饰动词“查到”时要用“地”，不用“的”。正确的说法是“便利地查到”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f28fec-a946-448c-81b5-b965873f593e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95801, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "有了地铁，上班便利的多了。", "corrected_sentence": "有了地铁，上班便利得多了。", "error_description": "程度补语误用：“便利”后表示程度的补语要用“得”，不用“的”。正确的说法是“便利得多了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f28fec-a946-448c-81b5-b965873f593e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95805, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "正", "is_correct": true, "explanation": "“正”与“偏”是反义词，偏指不在中间，正指位于正中，二者在“不在正中间”这一义项上相对。"}, {"text": "厚", "is_correct": false, "explanation": "“厚”与“偏”没有反义关系，“厚”说物体的厚薄，与位置无关。"}, {"text": "深", "is_correct": false, "explanation": "“深”与“偏”没有反义关系，“深”说距离或颜色，与位置无关。"}, {"text": "快", "is_correct": false, "explanation": "“快”与“偏”没有反义关系，“快”说速度，与位置无关。"}], "correct_answer": "正", "explanations": {"正": "“正”与“偏”是反义词，偏指不在中间，正指位于正中，二者在“不在正中间”这一义项上相对。", "厚": "“厚”与“偏”没有反义关系，“厚”说物体的厚薄，与位置无关。", "深": "“深”与“偏”没有反义关系，“深”说距离或颜色，与位置无关。", "快": "“快”与“偏”没有反义关系，“快”说速度，与位置无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2d18282-f3a8-45ef-8bab-00c928f5525c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95805, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "正", "is_correct": true, "explanation": "“正”与“偏”是反义词，偏指不在中间，正指位于正中，二者在“不在正中间”这一义项上相对。"}, {"text": "重", "is_correct": false, "explanation": "“重”与“偏”没有反义关系，“重”说分量，与位置无关。"}, {"text": "慢", "is_correct": false, "explanation": "“慢”与“偏”没有反义关系，“慢”说速度，与位置无关。"}, {"text": "高", "is_correct": false, "explanation": "“高”与“偏”没有反义关系，“高”说高度，与是否居中无关。"}], "correct_answer": "正", "explanations": {"正": "“正”与“偏”是反义词，偏指不在中间，正指位于正中，二者在“不在正中间”这一义项上相对。", "重": "“重”与“偏”没有反义关系，“重”说分量，与位置无关。", "慢": "“慢”与“偏”没有反义关系，“慢”说速度，与位置无关。", "高": "“高”与“偏”没有反义关系，“高”说高度，与是否居中无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2d18282-f3a8-45ef-8bab-00c928f5525c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95805, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "偏是不在中间，歪向一边。", "primary_collocate": null, "pronunciation": "piān", "ipa": "pʰiɛn˥", "syllable_count": 1, "sentences": [{"text": "桌子上的花瓶放偏了。", "target_word": "偏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的头有点偏。", "target_word": "偏", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "那张地图贴得太偏了。", "target_word": "偏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个字写得偏了，不在格子中间。", "target_word": "偏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "椅子摆偏了，不在桌子正前面。", "target_word": "偏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把杯子放偏了，水洒了一桌子。", "target_word": "偏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灯挂得太偏，屋子中间很暗。", "target_word": "偏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把相机对准我，别拍偏了。", "target_word": "偏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球门在中间，这个球射得太偏了。", "target_word": "偏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把名字写偏了，一半写到了纸外面。", "target_word": "偏", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "偏了", "label": "体标"}], "register": "中性", "sense_fingerprint": "不在中间，歪向一边", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e597af4-afbc-46b9-b9ba-f215b10afa71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95805, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "偏", "is_correct": true, "explanation": "偏（piān）意思是不在中间、歪向一边，是正确答案。"}, {"text": "片", "is_correct": false, "explanation": "片（piàn）与偏（piān）声调不同，意思是薄片。"}, {"text": "骗", "is_correct": false, "explanation": "骗（piàn）与偏（piān）声调不同，意思是欺骗。"}, {"text": "边", "is_correct": false, "explanation": "边（biān）与偏（piān）声母不同（b 与 p），意思是边缘。"}, {"text": "天", "is_correct": false, "explanation": "天（tiān）与偏（piān）声母不同（t 与 p），意思是天空。"}, {"text": "煎", "is_correct": false, "explanation": "煎（jiān）与偏（piān）声母不同（j 与 p），意思是用油加热。"}], "explanations": {"偏": "偏（piān）意思是不在中间、歪向一边，是正确答案。", "片": "片（piàn）与偏（piān）声调不同，意思是薄片。", "骗": "骗（piàn）与偏（piān）声调不同，意思是欺骗。", "边": "边（biān）与偏（piān）声母不同（b 与 p），意思是边缘。", "天": "天（tiān）与偏（piān）声母不同（t 与 p），意思是天空。", "煎": "煎（jiān）与偏（piān）声母不同（j 与 p），意思是用油加热。"}, "sentence_index": null, "correct_answer": "偏"}, "level_3": {"options": [{"text": "偏", "is_correct": true, "explanation": "“偏”作形容词，说位置歪向一边，可以作补语说“放偏了”，符合句意。"}, {"text": "亮", "is_correct": false, "explanation": "语义：“亮”说光线明亮，与花瓶的摆放位置无关，“放亮了”讲不通。"}, {"text": "软", "is_correct": false, "explanation": "搭配：“软”说质地柔软，不能用来说放置的结果，“放软了”不成立。"}, {"text": "白", "is_correct": false, "explanation": "语义：“白”说颜色，与摆放的位置无关，“放白了”讲不通。"}], "explanations": {"偏": "“偏”作形容词，说位置歪向一边，可以作补语说“放偏了”，符合句意。", "亮": "语义：“亮”说光线明亮，与花瓶的摆放位置无关，“放亮了”讲不通。", "软": "搭配：“软”说质地柔软，不能用来说放置的结果，“放软了”不成立。", "白": "语义：“白”说颜色，与摆放的位置无关，“放白了”讲不通。"}, "sentence_index": 0, "correct_answer": "偏"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他偏了三本书，老师让他还回图书馆。", "explanation": "这里应该用〈借〉。“偏”是形容词，不能带宾语；“借书”要说“借”。"}, {"text": "她小时候眼睛偏视，后来做了手术。", "explanation": "这里应该用〈斜〉。“斜视”是固定说法，“偏视”不成词。"}, {"text": "他偏了一个大学，全家都很高兴。", "explanation": "这里应该用〈考上〉。“偏”不能带宾语；“考上大学”要说“考上”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2d18282-f3a8-45ef-8bab-00c928f5525c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95805, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "偏", "is_correct": true, "explanation": "偏（piān）意思是不在中间、歪向一边，是正确答案。"}, {"text": "千", "is_correct": false, "explanation": "千（qiān）与偏（piān）声母不同（q 与 p），意思是一千。"}, {"text": "先", "is_correct": false, "explanation": "先（xiān）与偏（piān）声母不同（x 与 p），意思是先后的先。"}, {"text": "尖", "is_correct": false, "explanation": "尖（jiān）与偏（piān）声母不同（j 与 p），意思是尖端。"}, {"text": "飘", "is_correct": false, "explanation": "飘（piāo）与偏（piān）韵母不同（ao 与 an），意思是在空中漂浮。"}], "explanations": {"偏": "偏（piān）意思是不在中间、歪向一边，是正确答案。", "千": "千（qiān）与偏（piān）声母不同（q 与 p），意思是一千。", "先": "先（xiān）与偏（piān）声母不同（x 与 p），意思是先后的先。", "尖": "尖（jiān）与偏（piān）声母不同（j 与 p），意思是尖端。", "飘": "飘（piāo）与偏（piān）韵母不同（ao 与 an），意思是在空中漂浮。"}, "sentence_index": null, "correct_answer": "偏"}, "level_3": {"options": [{"text": "偏", "is_correct": true, "explanation": "“偏”作形容词，说位置不在中间，可以作补语说“挂得太偏”，符合句意。"}, {"text": "脏", "is_correct": false, "explanation": "搭配：“脏”说物体不干净，不描述悬挂的位置，“挂得太脏”不成立。"}, {"text": "硬", "is_correct": false, "explanation": "搭配：“硬”说质地坚硬，不能用来说灯挂的状态，“挂得太硬”不成立。"}, {"text": "黑", "is_correct": false, "explanation": "语义：“黑”说颜色深暗，与灯挂的位置无关，“挂得太黑”讲不通。"}], "explanations": {"偏": "“偏”作形容词，说位置不在中间，可以作补语说“挂得太偏”，符合句意。", "脏": "搭配：“脏”说物体不干净，不描述悬挂的位置，“挂得太脏”不成立。", "硬": "搭配：“硬”说质地坚硬，不能用来说灯挂的状态，“挂得太硬”不成立。", "黑": "语义：“黑”说颜色深暗，与灯挂的位置无关，“挂得太黑”讲不通。"}, "sentence_index": 6, "correct_answer": "偏"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他偏了一本书，放在桌上，怕掉下去。", "explanation": "这里应该用〈拿〉。“偏”是形容词，不能带宾语；“拿书”要说“拿”。"}, {"text": "他偏了一个电话，很快就走了。", "explanation": "这里应该用〈打〉。“偏”不能带宾语；“打电话”要说“打”。"}, {"text": "他偏了一张桌子，放到了门口。", "explanation": "这里应该用〈搬〉。“偏”不能带宾语；“搬桌子”要说“搬”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2d18282-f3a8-45ef-8bab-00c928f5525c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95805, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这盆花放了偏，要挪到中间。", "corrected_sentence": "这盆花放偏了，要挪到中间。", "error_description": "“偏”作补语要紧跟动词，“了”应放在补语之后：应说“放偏了”。“放了偏”的语序错误，“了”不能插在动词与补语之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2d18282-f3a8-45ef-8bab-00c928f5525c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95805, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把杯子放很偏。", "corrected_sentence": "他把杯子放得很偏。", "error_description": "“偏”作补语时，动词与补语之间要用“得”连接，说“放得很偏”；省去“得”，说“放很偏”不成句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2d18282-f3a8-45ef-8bab-00c928f5525c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95806, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "正", "is_correct": true, "explanation": "“正”与“偏”是反义词，偏指不正，正指不偏不倚，二者在“不在正中间”这一义项上相对。"}, {"text": "厚", "is_correct": false, "explanation": "“厚”与“偏”没有反义关系，“厚”说物体的厚薄，与线条的位置无关。"}, {"text": "深", "is_correct": false, "explanation": "“深”与“偏”没有反义关系，“深”说距离或颜色，与线条是否正无关。"}, {"text": "快", "is_correct": false, "explanation": "“快”与“偏”没有反义关系，“快”说速度，与线条的位置无关。"}], "correct_answer": "正", "explanations": {"正": "“正”与“偏”是反义词，偏指不正，正指不偏不倚，二者在“不在正中间”这一义项上相对。", "厚": "“厚”与“偏”没有反义关系，“厚”说物体的厚薄，与线条的位置无关。", "深": "“深”与“偏”没有反义关系，“深”说距离或颜色，与线条是否正无关。", "快": "“快”与“偏”没有反义关系，“快”说速度，与线条的位置无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2d18282-f3a8-45ef-8bab-00c928f5525c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95806, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "正", "is_correct": true, "explanation": "“正”与“偏”是反义词，偏指不正，正指不偏不倚，二者在“不在正中间”这一义项上相对。"}, {"text": "重", "is_correct": false, "explanation": "“重”与“偏”没有反义关系，“重”说分量，与镜框的位置无关。"}, {"text": "硬", "is_correct": false, "explanation": "“硬”与“偏”没有反义关系，“硬”说质地，与镜框的位置无关。"}, {"text": "慢", "is_correct": false, "explanation": "“慢”与“偏”没有反义关系，“慢”说速度，与镜框的位置无关。"}], "correct_answer": "正", "explanations": {"正": "“正”与“偏”是反义词，偏指不正，正指不偏不倚，二者在“不在正中间”这一义项上相对。", "重": "“重”与“偏”没有反义关系，“重”说分量，与镜框的位置无关。", "硬": "“硬”与“偏”没有反义关系，“硬”说质地，与镜框的位置无关。", "慢": "“慢”与“偏”没有反义关系，“慢”说速度，与镜框的位置无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2d18282-f3a8-45ef-8bab-00c928f5525c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95806, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不正；倾向一边；不在正中间。", "primary_collocate": null, "pronunciation": "piān", "ipa": "pʰiɛn˥", "syllable_count": 1, "sentences": [{"text": "这幅画挂得有点偏。", "target_word": "偏", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你坐得太偏了，往中间坐一点。", "target_word": "偏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "照片里他的位置偏左。", "target_word": "偏", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这条线画偏了，要重新画。", "target_word": "偏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "帽子戴偏了，你照照镜子。", "target_word": "偏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的球踢偏了，没有进球门。", "target_word": "偏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张桌子放得偏了一点，门打不开。", "target_word": "偏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "图片中的小树偏右，看起来不太好看。", "target_word": "偏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "照相的时候，你站得太偏，只拍到一半。", "target_word": "偏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个镜框有点偏，请帮我把它扶正。", "target_word": "偏", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "偏了", "label": "体标"}], "register": "中性", "sense_fingerprint": "位置或方向不正，偏向一边", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e597af4-afbc-46b9-b9ba-f215b10afa71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95806, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "偏", "is_correct": true, "explanation": "偏（piān）意思是不正、偏向一边，是正确答案。"}, {"text": "片", "is_correct": false, "explanation": "片（piàn）与偏（piān）声调不同，意思是薄片。"}, {"text": "骗", "is_correct": false, "explanation": "骗（piàn）与偏（piān）声调不同，意思是欺骗。"}, {"text": "边", "is_correct": false, "explanation": "边（biān）与偏（piān）声母不同（b 与 p），意思是边缘。"}, {"text": "天", "is_correct": false, "explanation": "天（tiān）与偏（piān）声母不同（t 与 p），意思是天空。"}, {"text": "煎", "is_correct": false, "explanation": "煎（jiān）与偏（piān）声母不同（j 与 p），意思是用油加热。"}], "explanations": {"偏": "偏（piān）意思是不正、偏向一边，是正确答案。", "片": "片（piàn）与偏（piān）声调不同，意思是薄片。", "骗": "骗（piàn）与偏（piān）声调不同，意思是欺骗。", "边": "边（biān）与偏（piān）声母不同（b 与 p），意思是边缘。", "天": "天（tiān）与偏（piān）声母不同（t 与 p），意思是天空。", "煎": "煎（jiān）与偏（piān）声母不同（j 与 p），意思是用油加热。"}, "sentence_index": null, "correct_answer": "偏"}, "level_3": {"options": [{"text": "偏", "is_correct": true, "explanation": "“偏”作形容词，说位置不正，可以作补语说“挂得有点偏”，符合句意。"}, {"text": "亮", "is_correct": false, "explanation": "语义：“亮”说光线明亮，与画挂得正不正无关，“挂得有点亮”讲不通。"}, {"text": "软", "is_correct": false, "explanation": "搭配：“软”说质地柔软，不能用来描述画挂的状态，“挂得有点软”不成立。"}, {"text": "脏", "is_correct": false, "explanation": "搭配：“脏”说物体不干净，不描述悬挂的位置，“挂得有点脏”不成立。"}], "explanations": {"偏": "“偏”作形容词，说位置不正，可以作补语说“挂得有点偏”，符合句意。", "亮": "语义：“亮”说光线明亮，与画挂得正不正无关，“挂得有点亮”讲不通。", "软": "搭配：“软”说质地柔软，不能用来描述画挂的状态，“挂得有点软”不成立。", "脏": "搭配：“脏”说物体不干净，不描述悬挂的位置，“挂得有点脏”不成立。"}, "sentence_index": 0, "correct_answer": "偏"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他偏了一份报纸，很快就看完了。", "explanation": "这里应该用〈读〉。“偏”是形容词，不能带宾语；“读报纸”要说“读”。"}, {"text": "他小时候有偏视，后来做了手术。", "explanation": "这里应该用〈斜〉。“斜视”指眼球偏斜，是固定说法；“偏视”不成词，“偏”不能用于眼睛的视向。"}, {"text": "老板偏了一个会议，大家都很惊讶。", "explanation": "这里应该用〈开〉。“偏”不能带宾语；“开会”要说“开”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2d18282-f3a8-45ef-8bab-00c928f5525c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95806, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "偏", "is_correct": true, "explanation": "偏（piān）意思是不正、偏向一边，是正确答案。"}, {"text": "千", "is_correct": false, "explanation": "千（qiān）与偏（piān）声母不同（q 与 p），意思是一千。"}, {"text": "先", "is_correct": false, "explanation": "先（xiān）与偏（piān）声母不同（x 与 p），意思是先后的先。"}, {"text": "尖", "is_correct": false, "explanation": "尖（jiān）与偏（piān）声母不同（j 与 p），意思是尖端。"}, {"text": "飘", "is_correct": false, "explanation": "飘（piāo）与偏（piān）韵母不同（ao 与 an），意思是在空中漂浮。"}], "explanations": {"偏": "偏（piān）意思是不正、偏向一边，是正确答案。", "千": "千（qiān）与偏（piān）声母不同（q 与 p），意思是一千。", "先": "先（xiān）与偏（piān）声母不同（x 与 p），意思是先后的先。", "尖": "尖（jiān）与偏（piān）声母不同（j 与 p），意思是尖端。", "飘": "飘（piāo）与偏（piān）韵母不同（ao 与 an），意思是在空中漂浮。"}, "sentence_index": null, "correct_answer": "偏"}, "level_3": {"options": [{"text": "偏", "is_correct": true, "explanation": "“偏”作形容词，说位置不正，可以作补语说“放得偏了一点”，符合句意。"}, {"text": "黑", "is_correct": false, "explanation": "语义：“黑”说颜色深暗，与桌子的摆放位置无关，“放得黑了一点”讲不通。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：“瘦”描写人或动物的体形，不用来描述桌子的摆放。"}, {"text": "白", "is_correct": false, "explanation": "语义：“白”说颜色，不能表示摆放的结果，“放得白了一点”不成立。"}], "explanations": {"偏": "“偏”作形容词，说位置不正，可以作补语说“放得偏了一点”，符合句意。", "黑": "语义：“黑”说颜色深暗，与桌子的摆放位置无关，“放得黑了一点”讲不通。", "瘦": "体貌：“瘦”描写人或动物的体形，不用来描述桌子的摆放。", "白": "语义：“白”说颜色，不能表示摆放的结果，“放得白了一点”不成立。"}, "sentence_index": 6, "correct_answer": "偏"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他偏了一把伞，雨水都淋进了衣领。", "explanation": "这里应该用〈撑〉。“偏”是形容词，不能带宾语；“撑伞”要说“撑”。"}, {"text": "他偏了一句话，大家都没听清。", "explanation": "这里应该用〈说〉。“偏”不能带宾语；“说话”要说“说”。"}, {"text": "他偏了一个位置，显得很不显眼。", "explanation": "这里应该用〈占〉。“偏”不能带宾语；“占位置”要说“占”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2d18282-f3a8-45ef-8bab-00c928f5525c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95806, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这幅画挂了偏。", "corrected_sentence": "这幅画挂偏了。", "error_description": "“偏”作补语要紧跟动词，“了”应放在补语之后：应说“挂偏了”。“挂了偏”的语序错误，“了”不能插在动词与补语之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2d18282-f3a8-45ef-8bab-00c928f5525c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95806, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个镜框挂很偏，要扶正。", "corrected_sentence": "这个镜框挂得很偏，要扶正。", "error_description": "“偏”作补语时，动词与补语之间要用“得”连接，说“挂得很偏”；省去“得”，说“挂很偏”不成句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2d18282-f3a8-45ef-8bab-00c928f5525c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
