INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95808, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "商品的价格，买卖东西所需要的钱数。", "primary_collocate": null, "pronunciation": "jià qián", "ipa": "tɕja˥˩ tɕʰjɛn˧˥", "syllable_count": 2, "sentences": [{"text": "这件衣服的价钱太贵了，我不想买。", "target_word": "价钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你先问一下价钱，再决定买不买。", "target_word": "价钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的价钱比别家便宜很多。", "target_word": "价钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水果的价钱每天都不一样。", "target_word": "价钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板说这个价钱不能再低了。", "target_word": "价钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我觉得这个价钱很合理。", "target_word": "价钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买东西以前，我喜欢比较一下价钱。", "target_word": "价钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆自行车的价钱是多少？", "target_word": "价钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他和老板讲了半天价钱。", "target_word": "价钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "价钱写在盒子上，你自己看吧。", "target_word": "价钱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "價錢", "label": "繁体"}], "register": "中性", "sense_fingerprint": "商品的价格，买东西要付的钱数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6ff1bd0-a59b-4b61-b6ac-44883ef294ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95808, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "价钱", "is_correct": true, "explanation": "正确：价钱，读作 jià qián，指买东西要付的钱数。"}, {"text": "假钱", "is_correct": false, "explanation": "jiǎ qián（第三声）与 jià 声调不同，意思是假币。"}, {"text": "加钱", "is_correct": false, "explanation": "jiā qián（第一声）与 jià 声调不同，意思是额外付钱。"}, {"text": "价签", "is_correct": false, "explanation": "qiān（第一声）与 qián（第二声）声调不同，意思是标着价格的签子。"}], "explanations": {"价钱": "正确：价钱，读作 jià qián，指买东西要付的钱数。", "假钱": "jiǎ qián（第三声）与 jià 声调不同，意思是假币。", "加钱": "jiā qián（第一声）与 jià 声调不同，意思是额外付钱。", "价签": "qiān（第一声）与 qián（第二声）声调不同，意思是标着价格的签子。"}, "sentence_index": null, "correct_answer": "价钱"}, "level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "搭配：“太贵”说的是价格，不能用来形容颜色。"}, {"text": "价钱", "is_correct": true, "explanation": "正确：“价钱”指价格，“这件衣服的价钱太贵了”符合句意。"}, {"text": "尺寸", "is_correct": false, "explanation": "搭配：“太贵”形容价格，不能用来形容尺寸。"}, {"text": "时间", "is_correct": false, "explanation": "语义：“时间”不是可以标价的东西，与“太贵”的说法矛盾。"}], "explanations": {"颜色": "搭配：“太贵”说的是价格，不能用来形容颜色。", "价钱": "正确：“价钱”指价格，“这件衣服的价钱太贵了”符合句意。", "尺寸": "搭配：“太贵”形容价格，不能用来形容尺寸。", "时间": "语义：“时间”不是可以标价的东西，与“太贵”的说法矛盾。"}, "sentence_index": 0, "correct_answer": "价钱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他说的话有很深的价钱。", "explanation": "这里应该用〈道理〉。“价钱”是买东西要付的钱数，不能用“很深”来形容，应说“有很深的道理”。"}, {"text": "他已经吃光了那些价钱。", "explanation": "这里应该用〈食物〉。“价钱”是买东西要付的钱数，不能被吃，可以吃光的应是食物。"}, {"text": "他的价钱很好地解释了这个问题。", "explanation": "这里应该用〈说明书〉。“价钱”指买卖的钱数，不能作为解释问题的主体，能解释问题的应是说明书一类的文字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '610d24dd-dceb-4fc2-83b6-fe32f33b0c96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95808, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "心情", "is_correct": false, "explanation": "语义：“心情”不能拿来和其他东西比较价格，与买东西的语境不符。"}, {"text": "价钱", "is_correct": true, "explanation": "正确：“价钱”是买东西时可以比较的对象，符合“买东西以前……比较一下”的语境。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”是人的体态特征，不能作为买东西时比较的对象。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”指存在的年限，与买东西时比较的对象不相符。"}], "explanations": {"心情": "语义：“心情”不能拿来和其他东西比较价格，与买东西的语境不符。", "价钱": "正确：“价钱”是买东西时可以比较的对象，符合“买东西以前……比较一下”的语境。", "身高": "体貌：“身高”是人的体态特征，不能作为买东西时比较的对象。", "年龄": "语义：“年龄”指存在的年限，与买东西时比较的对象不相符。"}, "sentence_index": 6, "correct_answer": "价钱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次活动的价钱很精彩。", "explanation": "这里应该用〈表演〉。“价钱”指买卖的钱数，不能用来形容好坏，应说“表演很精彩”。"}, {"text": "他一下子赚了很多价钱。", "explanation": "这里应该用〈利润〉。“价钱”是商品的标价，不能被赚，赚到的应是利润这类收益。"}, {"text": "我们在价钱见面。", "explanation": "这里应该用〈集市〉。“价钱”指买卖的钱数，不能当作见面的地点，买卖的场所应用“集市”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '610d24dd-dceb-4fc2-83b6-fe32f33b0c96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95808, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们和摊主讲了一价钱。", "corrected_sentence": "我们和摊主讲了一个价钱。", "error_description": "错误：数词“一”后缺少量词，“价钱”前应加量词“个”。正确：“一个价钱”，写作“讲了一个价钱”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '610d24dd-dceb-4fc2-83b6-fe32f33b0c96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95808, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "出门以前，我喜欢先比较一下价钱一下。", "corrected_sentence": "出门以前，我喜欢先比较一下价钱。", "error_description": "错误：动量补语“一下”重复出现，多出的“一下”放在了“价钱”后面。正确：“一下”只紧跟动词“比较”，写作“比较一下价钱”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '610d24dd-dceb-4fc2-83b6-fe32f33b0c96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95817, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "责怪", "is_correct": true, "explanation": "正确。“原谅”与“责怪”相对，指对别人的错误不再怪罪。"}, {"text": "感谢", "is_correct": false, "explanation": "无反义关系：“感谢”是对别人的好意表示谢意，与“原谅”不构成反义。"}, {"text": "同意", "is_correct": false, "explanation": "无反义关系：“同意”是赞成某事，与“原谅”不构成反义。"}, {"text": "称赞", "is_correct": false, "explanation": "无反义关系：“称赞”是夸奖别人，与“原谅”不构成反义。"}], "correct_answer": "责怪", "explanations": {"责怪": "正确。“原谅”与“责怪”相对，指对别人的错误不再怪罪。", "感谢": "无反义关系：“感谢”是对别人的好意表示谢意，与“原谅”不构成反义。", "同意": "无反义关系：“同意”是赞成某事，与“原谅”不构成反义。", "称赞": "无反义关系：“称赞”是夸奖别人，与“原谅”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4486f04b-f2e3-49b9-a129-c8b8eb61b3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95817, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "责备", "is_correct": true, "explanation": "正确。“原谅”与“责备”相对，指对别人的过错不再批评。"}, {"text": "鼓励", "is_correct": false, "explanation": "无反义关系：“鼓励”是给人信心，与“原谅”不构成反义。"}, {"text": "答应", "is_correct": false, "explanation": "无反义关系：“答应”是同意做某事，与“原谅”不构成反义。"}, {"text": "批准", "is_correct": false, "explanation": "无反义关系：“批准”是正式同意，与“原谅”不构成反义。"}], "correct_answer": "责备", "explanations": {"责备": "正确。“原谅”与“责备”相对，指对别人的过错不再批评。", "鼓励": "无反义关系：“鼓励”是给人信心，与“原谅”不构成反义。", "答应": "无反义关系：“答应”是同意做某事，与“原谅”不构成反义。", "批准": "无反义关系：“批准”是正式同意，与“原谅”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4486f04b-f2e3-49b9-a129-c8b8eb61b3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95817, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "原谅是别人做错了事，你不生气了，不怪他了。", "primary_collocate": null, "pronunciation": "yuán liàng", "ipa": "ɥɛn˧˥ ljɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "你快去跟妈妈说对不起，她会原谅你的。", "target_word": "原谅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他打坏了我的杯子，可我很快就原谅他了。", "target_word": "原谅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友说了谎，我不想原谅他。", "target_word": "原谅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我原谅你了，你不要难过。", "target_word": "原谅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟道歉以后，姐姐原谅了他。", "target_word": "原谅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你做错了事，别人不一定会原谅你。", "target_word": "原谅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她没有原谅过那个骗她的人。", "target_word": "原谅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每次犯错，奶奶都原谅他。", "target_word": "原谅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我知道你是无心的，所以原谅你。", "target_word": "原谅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虽然他伤过我的心，但我已经原谅他了。", "target_word": "原谅", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "原谅了", "label": "完成体"}, {"form": "原谅过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "别人做错事后，不再生气、不再责怪", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5c48bcb-0943-4b4f-aaa1-4bc592e2985d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95817, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "原谅", "is_correct": true, "explanation": "正确。“原谅”指对别人的过错不再计较，与“说对不起”的语境相合。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：打扫是清理场所，与道歉的语境无关，“她会打扫你的”说不通。"}, {"text": "怀念", "is_correct": false, "explanation": "搭配：“怀念”多用于已经离开或过去的人，不能用于当下道歉的语境。"}, {"text": "拆开", "is_correct": false, "explanation": "语义：拆开是打开包裹或信件，与道歉的语境无关，句子说不通。"}], "explanations": {"原谅": "正确。“原谅”指对别人的过错不再计较，与“说对不起”的语境相合。", "打扫": "语义：打扫是清理场所，与道歉的语境无关，“她会打扫你的”说不通。", "怀念": "搭配：“怀念”多用于已经离开或过去的人，不能用于当下道歉的语境。", "拆开": "语义：拆开是打开包裹或信件，与道歉的语境无关，句子说不通。"}, "sentence_index": 0, "correct_answer": "原谅"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这顿饭很好吃，我原谅你了。", "explanation": "这里应该用〈夸奖〉。“原谅”针对别人做错的事，饭做得好吃应当夸奖，不能说“原谅”。"}, {"text": "我原谅你考上了大学。", "explanation": "这里应该用〈恭喜〉。“原谅”针对过错，考上大学是喜事，应说“恭喜”。"}, {"text": "我的朋友生病了，我原谅了他的病。", "explanation": "这里应该用〈关心〉。生病不是别人的过错，对病人应表示关心，不能说“原谅”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4486f04b-f2e3-49b9-a129-c8b8eb61b3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95817, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "原谅", "is_correct": true, "explanation": "正确。“原谅”用于骗人者所做的过错，与“没有……过”的说法相合。"}, {"text": "感激", "is_correct": false, "explanation": "语义：感激是对别人的好处表示谢意，不能用于骗她的人，句子说不通。"}, {"text": "请教", "is_correct": false, "explanation": "搭配：“请教”是向人讨教，与“骗她的人”搭配不通。"}, {"text": "表彰", "is_correct": false, "explanation": "语义：表彰是公开表扬，与骗人的人不相称，句子不通。"}], "explanations": {"原谅": "正确。“原谅”用于骗人者所做的过错，与“没有……过”的说法相合。", "感激": "语义：感激是对别人的好处表示谢意，不能用于骗她的人，句子说不通。", "请教": "搭配：“请教”是向人讨教，与“骗她的人”搭配不通。", "表彰": "语义：表彰是公开表扬，与骗人的人不相称，句子不通。"}, "sentence_index": 6, "correct_answer": "原谅"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "你帮了我很多，我原谅了你的帮助。", "explanation": "这里应该用〈感激〉。“原谅”针对别人的过错，别人的帮助不是过错，不能说“原谅”。"}, {"text": "他拿了冠军，我原谅了他的冠军。", "explanation": "这里应该用〈祝贺〉。“原谅”针对过错，对拿冠军应表示祝贺，不能用“原谅”。"}, {"text": "这件衣服很贵，我原谅了它的价格。", "explanation": "这里应该用〈接受〉。“原谅”针对人的过错，对价格这类情况应说“接受”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4486f04b-f2e3-49b9-a129-c8b8eb61b3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95817, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你做错事，我不原谅了你。", "corrected_sentence": "你做错事，我不原谅你。", "error_description": "体标错误：否定句中不能在“原谅”后加“了”。错误句是“不原谅了你”，正确句是“不原谅你”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4486f04b-f2e3-49b9-a129-c8b8eb61b3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95817, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我一直把他的错原谅。", "corrected_sentence": "我一直把他的错原谅了。", "error_description": "句式错误：“把”字句的动词后面要有其他成分（如“了”），“我一直把他的错原谅”不完整，应说“我一直把他的错原谅了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4486f04b-f2e3-49b9-a129-c8b8eb61b3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
