INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95824, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "地球的中心。", "primary_collocate": null, "pronunciation": "dì xīn", "ipa": "ti˥˩ ɕin˥", "syllable_count": 2, "sentences": [{"text": "地心就是地球的中心。", "target_word": "地心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地心在我们脚下很深的地方。", "target_word": "地心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影讲的是去地心旅行。", "target_word": "地心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地心的压力比地面大得多。", "target_word": "地心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家想知道地心里有什么。", "target_word": "地心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地心和地面之间有很多层。", "target_word": "地心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在图上指着地心。", "target_word": "地心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小说里的人坐机器去了地心。", "target_word": "地心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地心到地面的距离，大约六千公里。", "target_word": "地心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地心是一个很热的地方。", "target_word": "地心", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "地球的中心点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1881d9c-7008-468f-b42e-60222934a602') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95824, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "地心", "is_correct": true, "explanation": "地心（dì xīn）是地球的中心。"}, {"text": "地形", "is_correct": false, "explanation": "地形（dì xíng）与地心的韵母不同（-ing 与 -in），意思是地表的高低起伏。"}, {"text": "底薪", "is_correct": false, "explanation": "底（dǐ，第三声）与地（dì，第四声）声调不同，底薪指基本工资。"}, {"text": "低薪", "is_correct": false, "explanation": "低（dī，第一声）与地（dì，第四声）声调不同，低薪指工资低。"}], "explanations": {"地心": "地心（dì xīn）是地球的中心。", "地形": "地形（dì xíng）与地心的韵母不同（-ing 与 -in），意思是地表的高低起伏。", "底薪": "底（dǐ，第三声）与地（dì，第四声）声调不同，底薪指基本工资。", "低薪": "低（dī，第一声）与地（dì，第四声）声调不同，低薪指工资低。"}, "sentence_index": null, "correct_answer": "地心"}, "level_3": {"options": [{"text": "地心", "is_correct": true, "explanation": "正确：地心就是地球的中心。"}, {"text": "地表", "is_correct": false, "explanation": "语义：地表是地球的表面，不是地球的中心，句子与定义矛盾。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：海洋覆盖在地表上，不是地球的中心，句子与定义矛盾。"}, {"text": "地图", "is_correct": false, "explanation": "搭配：“就是”连接的两个成分应指同一事物，地图是画在纸上的东西，不能等同于地球的中心。"}], "explanations": {"地心": "正确：地心就是地球的中心。", "地表": "语义：地表是地球的表面，不是地球的中心，句子与定义矛盾。", "海洋": "语义：海洋覆盖在地表上，不是地球的中心，句子与定义矛盾。", "地图": "搭配：“就是”连接的两个成分应指同一事物，地图是画在纸上的东西，不能等同于地球的中心。"}, "sentence_index": 0, "correct_answer": "地心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们走在平坦的地心上。", "explanation": "这里应该用〈地面〉。地心在地球中心，人不能走在那里，走路的地方是地面。"}, {"text": "他每天都在地心里工作，上班很方便。", "explanation": "这里应该用〈地下〉。地下工作间指地面以下的房间；地心是地球的中心，不能用来指人工作的地方。"}, {"text": "地心很厚，有好几公里。", "explanation": "这里应该用〈地壳〉。地心没有厚度，说厚度要用〈地壳〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f28fec-a946-448c-81b5-b965873f593e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95824, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地心", "is_correct": true, "explanation": "正确：老师在图上指着的是地心。"}, {"text": "友谊", "is_correct": false, "explanation": "搭配：“在图上指着”的对象须是可以画出来的具体事物，友谊是抽象情感，句意不通。"}, {"text": "道理", "is_correct": false, "explanation": "搭配：道理是抽象的思想，不能在图上指出来，句意不通。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“指着”的对象应是具体可指的事物，声音不能被指着。"}], "explanations": {"地心": "正确：老师在图上指着的是地心。", "友谊": "搭配：“在图上指着”的对象须是可以画出来的具体事物，友谊是抽象情感，句意不通。", "道理": "搭配：道理是抽象的思想，不能在图上指出来，句意不通。", "声音": "搭配：“指着”的对象应是具体可指的事物，声音不能被指着。"}, "sentence_index": 6, "correct_answer": "地心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座山的地心有很多矿。", "explanation": "这里应该用〈地下〉。地下指地面以下，可以有矿；地心是地球最中间的地方，不能用来说一座山下面的矿藏。"}, {"text": "沙漠的地心白天非常热。", "explanation": "这里应该用〈地表〉。地表有白天黑夜的温度变化；地心在地球中心，不能用来说沙漠的温度。"}, {"text": "这所学校的地心有一座大操场。", "explanation": "这里应该用〈中心〉。地心专指地球的中心，不能用来指学校的中心。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f28fec-a946-448c-81b5-b965873f593e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95824, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "科学家还没有到了地心。", "corrected_sentence": "科学家还没有到过地心。", "error_description": "错误：“没有”后面不能用“了”，写成“没有到了”。正确：“没有到过”，“过”表示从来没有过这种经历。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f28fec-a946-448c-81b5-b965873f593e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95824, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个模型里有一只地心。", "corrected_sentence": "这个模型里有一个地心。", "error_description": "错误：量词“只”用于动物，地心不能用“只”来数，写成“一只地心”。正确：“一个地心”，“个”可以用于大多数事物。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f28fec-a946-448c-81b5-b965873f593e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
