INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95830, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "大拇指，手指中最粗最短的一个。", "primary_collocate": null, "pronunciation": "dà zhǐ", "ipa": "ta˥˩ ʈʂɨ˨˩˦", "syllable_count": 2, "sentences": [{"text": "大指是手上最粗的手指。", "target_word": "大指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他伸出大指，说我们做得好。", "target_word": "大指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的大指受伤了，不能写字。", "target_word": "大指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大指比别的手指短一些。", "target_word": "大指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用大指按住了纸。", "target_word": "大指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "戴手套时，大指要伸进单独的指套里。", "target_word": "大指", "complexity_tier": "T3", "furigana": "dài shǒu tào shí dà zhǐ yào shēn jìn dān dú de zhǐ tào lǐ", "sentence_source": "generated"}, {"text": "他的大指上贴着一块布。", "target_word": "大指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请用大指在这里按一下。", "target_word": "大指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生检查了孩子的大指。", "target_word": "大指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "五个手指中，大指最粗。", "target_word": "大指", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "大拇指，手指中最粗最短的一个", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1881d9c-7008-468f-b42e-60222934a602') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
