INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95830, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他竖起一只大指，夸我做得好。", "corrected_sentence": "他竖起一根大指，夸我做得好。", "error_description": "量词错误：手指应用“根”计量。“一只大指”应改为“一根大指”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f28fec-a946-448c-81b5-b965873f593e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95830, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的大指疼厉害。", "corrected_sentence": "他的大指疼得厉害。", "error_description": "补语错误：“疼”后应用“得”引出补语“厉害”，应说“疼得厉害”，不能说“疼厉害”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f28fec-a946-448c-81b5-b965873f593e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
