INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95839, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "审批是有人看过以后，说可以或者不可以。", "primary_collocate": null, "pronunciation": "shěn pī", "ipa": "ʂən˨˩˦ pʰi˥", "syllable_count": 2, "sentences": [{"text": "经理正在审批我的请假条。", "target_word": "审批", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买新电脑的申请，公司审批了吗？", "target_word": "审批", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每份文件都要老板审批。", "target_word": "审批", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "部门主任审批后，你才能出差。", "target_word": "审批", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个计划太大，上级不会轻易审批。", "target_word": "审批", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们审批得很慢，我等了一个星期。", "target_word": "审批", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长审批了这次旅行的申请。", "target_word": "审批", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想问问，我的申请审批了没有？", "target_word": "审批", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办这件事需要审批，你先填表。", "target_word": "审批", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院请求买新机器，政府已经审批了。", "target_word": "审批", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "审批了", "label": "体标"}, {"form": "审批过", "label": "体标"}, {"form": "審批", "label": "繁体"}], "register": "正式", "sense_fingerprint": "有人看过申请后决定可以或不可以", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6ff1bd0-a59b-4b61-b6ac-44883ef294ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95839, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "审批", "is_correct": true, "explanation": "审批：有人看过请假条后决定可以或不可以，与“经理”的身份相符。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”用于歌曲、戏曲，不能用于请假条。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”是进食，与请假条无关。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”是饮用，与请假条无关。"}], "explanations": {"审批": "审批：有人看过请假条后决定可以或不可以，与“经理”的身份相符。", "唱": "搭配：“唱”用于歌曲、戏曲，不能用于请假条。", "吃": "语义：“吃”是进食，与请假条无关。", "喝": "语义：“喝”是饮用，与请假条无关。"}, "sentence_index": 0, "correct_answer": "审批"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师正在审批这张试卷。", "explanation": "这里应该用〈批阅〉。老师批改试卷要用“批阅”，审批是上级对申请或文件作出批准，不用于试卷。"}, {"text": "他审批了我的笑话。", "explanation": "这里应该用〈评价〉。“审批”是有人看过以后说可以或不可以，用于申请或文件；评论笑话的好坏要用“评价”。"}, {"text": "这把椅子审批了我的请假条。", "explanation": "这里应该用〈看〉。“审批”要求有人看过请假条后作决定，椅子不能看，所以不能作主语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '610d24dd-dceb-4fc2-83b6-fe32f33b0c96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95839, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "审批", "is_correct": true, "explanation": "审批：上级看过申请后决定批准，与“校长”“这次旅行的申请”相符。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”用于损坏的器物，不能用于旅行的申请。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃”是不再坚持，与校长对申请作出的决定不相符。"}, {"text": "打听", "is_correct": false, "explanation": "语义：“打听”是询问消息，句中需要的是对申请作出决定的动作。"}], "explanations": {"审批": "审批：上级看过申请后决定批准，与“校长”“这次旅行的申请”相符。", "修理": "搭配：“修理”用于损坏的器物，不能用于旅行的申请。", "放弃": "语义：“放弃”是不再坚持，与校长对申请作出的决定不相符。", "打听": "语义：“打听”是询问消息，句中需要的是对申请作出决定的动作。"}, "sentence_index": 6, "correct_answer": "审批"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "师傅正在审批这辆自行车。", "explanation": "这里应该用〈修理〉。修车要用“修理”，审批不用于修理东西。"}, {"text": "我审批了这幅画的构图。", "explanation": "这里应该用〈欣赏〉。“审批”是有人看过以后说可以或不可以，用于申请或文件；评价画面的构图要用“欣赏”，不用“审批”。"}, {"text": "医生正在审批病人。", "explanation": "这里应该用〈检查〉。医生检查病人要用“检查”，审批只用于上级对申请或文件的批准。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '610d24dd-dceb-4fc2-83b6-fe32f33b0c96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95839, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "经理明天审批过我的请假条。", "corrected_sentence": "经理明天审批我的请假条。", "error_description": "错误：“明天”指将来，“过”表示已经完成的动作，二者不能搭配。正确：去掉“过”，写作“经理明天审批我的请假条”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '610d24dd-dceb-4fc2-83b6-fe32f33b0c96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95839, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "财务总监还没审批了这份报告。", "corrected_sentence": "财务总监还没审批这份报告。", "error_description": "“没”与“了”不能同用，否定尚未完成的动作时不加“了”。应说“还没审批这份报告”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '610d24dd-dceb-4fc2-83b6-fe32f33b0c96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
