INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95840, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "上级对下级提交的请求或文件进行审查并决定是否批准。", "primary_collocate": null, "pronunciation": "shěn pī", "ipa": "ʂən˨˩˦ pʰi˥", "syllable_count": 2, "sentences": [{"text": "这份申请要经理审批。", "target_word": "审批", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的请假申请已经审批了。", "target_word": "审批", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司正在审批这个新计划。", "target_word": "审批", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理还没有审批我的报告。", "target_word": "审批", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔钱要先审批，才能使用。", "target_word": "审批", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们审批文件的速度很快。", "target_word": "审批", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上级审批通过后，工程就可以开始了。", "target_word": "审批", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "申请交上去以后，三天内就会审批。", "target_word": "审批", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校审批了同学们的活动计划。", "target_word": "审批", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个项目由市政府审批。", "target_word": "审批", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "审批了", "label": "体标"}, {"form": "审批过", "label": "体标"}, {"form": "審批", "label": "繁体"}], "register": "正式", "sense_fingerprint": "上级审查下级的请求或文件并决定是否批准", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6ff1bd0-a59b-4b61-b6ac-44883ef294ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95840, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "审批", "is_correct": true, "explanation": "审批：上级看过申请后决定批准，与“经理”“申请”的语境相符。"}, {"text": "搬", "is_correct": false, "explanation": "搭配：“搬”用于搬动实物，不能用于申请这类文件。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”是饮用，与申请文件无关。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”用于擦拭物体表面，不能说擦申请。"}], "explanations": {"审批": "审批：上级看过申请后决定批准，与“经理”“申请”的语境相符。", "搬": "搭配：“搬”用于搬动实物，不能用于申请这类文件。", "喝": "语义：“喝”是饮用，与申请文件无关。", "擦": "搭配：“擦”用于擦拭物体表面，不能说擦申请。"}, "sentence_index": 0, "correct_answer": "审批"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "警察正在审批这个案子。", "explanation": "这里应该用〈审查〉。审批是上级对下级请求或文件作出批准的决定，警察侦办案件要用“审查”，不用“审批”。"}, {"text": "经理审批了我的错误。", "explanation": "这里应该用〈批评〉。“批评”是指出缺点或错误，“审批”是上级对申请或文件作出批准的决定，不能用于“错误”。"}, {"text": "我昨天审批了一杯咖啡。", "explanation": "这里应该用〈点〉。“点一杯咖啡”要用“点”，“审批”是上级对申请或文件作批准，不用于饮品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '610d24dd-dceb-4fc2-83b6-fe32f33b0c96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95840, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "审批", "is_correct": true, "explanation": "审批：上级审查后决定批准，与后文“通过”及“工程就可以开始”相符。"}, {"text": "驳回", "is_correct": false, "explanation": "语义：“驳回”是不予批准，与后文“通过”矛盾。"}, {"text": "完成", "is_correct": false, "explanation": "搭配：“完成”指做好某件事，不能与“通过”这种裁决搭配。"}, {"text": "停", "is_correct": false, "explanation": "语义：“停”是中止，与“通过”后工程开始的语境不符。"}], "explanations": {"审批": "审批：上级审查后决定批准，与后文“通过”及“工程就可以开始”相符。", "驳回": "语义：“驳回”是不予批准，与后文“通过”矛盾。", "完成": "搭配：“完成”指做好某件事，不能与“通过”这种裁决搭配。", "停": "语义：“停”是中止，与“通过”后工程开始的语境不符。"}, "sentence_index": 6, "correct_answer": "审批"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师正在审批这些作业。", "explanation": "这里应该用〈批改〉。老师给作业打分、写评语要用“批改”，审批是上级对请求或文件的批准，不用于作业。"}, {"text": "法官正在审批那个罪犯。", "explanation": "这里应该用〈审判〉。法院对罪犯定罪量刑要用“审判”，审批只用于上级对申请或文件作出批准。"}, {"text": "评委们正在审批这些参赛作品。", "explanation": "这里应该用〈评审〉。评委评选参赛作品要用“评审”，“审批”是上级对申请或文件作批准，不用于作品评比。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '610d24dd-dceb-4fc2-83b6-fe32f33b0c96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95840, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们审批得快很。", "corrected_sentence": "他们审批得很快。", "error_description": "错误：补语“很快”的语序颠倒，写成了“快很”。正确：应为“审批得很快”，程度词“很”须放在“快”之前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '610d24dd-dceb-4fc2-83b6-fe32f33b0c96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95840, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新项目的预算要董事会把审批。", "corrected_sentence": "新项目的预算要董事会审批。", "error_description": "“把”字句要求动词后带宾语或补语，“把审批”残缺。应直接说“要董事会审批”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '610d24dd-dceb-4fc2-83b6-fe32f33b0c96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
