INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95842, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "法院对案件进行审查和判断。", "primary_collocate": null, "pronunciation": "shěn lǐ", "ipa": "ʂən˨˩ li˨˩", "syllable_count": 2, "sentences": [{"text": "法院今天审理一起盗窃案。", "target_word": "审理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个案件由北京法院审理。", "target_word": "审理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院已经审理了这个案件。", "target_word": "审理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院公开审理了这起案件。", "target_word": "审理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这起案件审理了两个月。", "target_word": "审理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院将在下周审理这件案子。", "target_word": "审理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种案件，法院一般不公开审理。", "target_word": "审理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院审理过很多交通案件。", "target_word": "审理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "案件还在审理，还没有结果。", "target_word": "审理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个案件审理得很快，一天就结束了。", "target_word": "审理", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "审理了", "label": "完成体"}, {"form": "审理过", "label": "经历体"}, {"form": "正在审理", "label": "进行体"}], "register": "正式", "sense_fingerprint": "法院依法审查并判断案件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1881d9c-7008-468f-b42e-60222934a602') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95842, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "审理", "is_correct": true, "explanation": "语义：审理即法院对案件进行审查判断，“审理一起盗窃案”符合句意。"}, {"text": "修", "is_correct": false, "explanation": "语义：“修”的对象是器物，不能用来处理案件。"}, {"text": "煮", "is_correct": false, "explanation": "语义：案件不能煮，“煮一起盗窃案”说不通。"}, {"text": "缝", "is_correct": false, "explanation": "搭配：“缝”的对象通常是布料、衣物，不与“案件”搭配。"}], "explanations": {"审理": "语义：审理即法院对案件进行审查判断，“审理一起盗窃案”符合句意。", "修": "语义：“修”的对象是器物，不能用来处理案件。", "煮": "语义：案件不能煮，“煮一起盗窃案”说不通。", "缝": "搭配：“缝”的对象通常是布料、衣物，不与“案件”搭配。"}, "sentence_index": 0, "correct_answer": "审理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把椅子审理了这起案件。", "explanation": "这里误用了〈审理〉。它指法院依法查明案件并作出判断，只能由法院或法官进行；让椅子充当审理的主体，是把它用在了没有判断能力的物体上。"}, {"text": "老师审理了学生的作文。", "explanation": "这里应该用〈审阅〉。审理专用于案件，作文应说审阅或批改。"}, {"text": "我们审理了这个问题，结果很好。", "explanation": "这里应该用〈讨论〉。审理是法院对案件的处理，日常讨论问题不用审理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f28fec-a946-448c-81b5-b965873f593e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95842, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "审理", "is_correct": true, "explanation": "语义：审理即法院依法审查判断案件，“不公开审理”符合句意。"}, {"text": "出售", "is_correct": false, "explanation": "语义：案件不能出售，“不公开出售”与法院的工作不符。"}, {"text": "表演", "is_correct": false, "explanation": "语义：案件不能拿来表演，“不公开表演”说不通。"}, {"text": "煎", "is_correct": false, "explanation": "搭配：“煎”的对象是食物，不能用来与“案件”搭配。"}], "explanations": {"审理": "语义：审理即法院依法审查判断案件，“不公开审理”符合句意。", "出售": "语义：案件不能出售，“不公开出售”与法院的工作不符。", "表演": "语义：案件不能拿来表演，“不公开表演”说不通。", "煎": "搭配：“煎”的对象是食物，不能用来与“案件”搭配。"}, "sentence_index": 6, "correct_answer": "审理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "警察审理了这起交通事故，很快就找到了司机。", "explanation": "这里应该用〈侦查〉。审理由法院进行，警方查案只说侦查。"}, {"text": "同学们审理了这道数学题，很快得出了答案。", "explanation": "这里应该用〈解答〉。审理专用于司法案件，数学题应说解答。"}, {"text": "医生审理了这个病人，给他开了药。", "explanation": "这里应该用〈治疗〉。审理是司法活动，病人应说治疗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f28fec-a946-448c-81b5-b965873f593e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95842, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "法院已经正在审理完了这起案件。", "corrected_sentence": "法院已经审理完了这起案件。", "error_description": "体标冲突：“正在”表示动作进行，不能与表示完成的“完了”同用；应说“法院已经审理完了这起案件”，用“已经”表示完成，去掉“正在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f28fec-a946-448c-81b5-b965873f593e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95842, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这起案件审理了得很仔细。", "corrected_sentence": "这起案件审理得很仔细。", "error_description": "错误：“得”前面不能加“了”，“审理了得”不成立；应说“审理得很仔细”，“得”直接接在动词后引出补语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f28fec-a946-448c-81b5-b965873f593e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
