INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95853, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "成道是修行的人终于明白了大道理。", "primary_collocate": null, "pronunciation": "chéng dào", "ipa": "ʈʂʰɤŋ˧˥ tɑʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "传说佛祖在菩提树下成道。", "target_word": "成道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位和尚修行了三十年，终于成道了。", "target_word": "成道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一心修行，希望有一天能成道。", "target_word": "成道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人说，成道不是一件容易的事。", "target_word": "成道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的师父已经成道了。", "target_word": "成道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他坐在树下想了七天，终于成道。", "target_word": "成道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人想成道，却坚持不下去。", "target_word": "成道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师父成道以后，开始教学生。", "target_word": "成道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们相信，只有认真修行才能成道。", "target_word": "成道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "故事里的小和尚最后成道了。", "target_word": "成道", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "成道了", "label": "体标"}], "register": "书面", "sense_fingerprint": "修行的人终于明白大道理", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6ff1bd0-a59b-4b61-b6ac-44883ef294ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95853, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "成道", "is_correct": true, "explanation": "正确。成道指修行者领悟大道，符合“传说佛祖在菩提树下”的语境。"}, {"text": "上班", "is_correct": false, "explanation": "语义：上班指去单位工作，与佛祖修行的情境不符。"}, {"text": "考试", "is_correct": false, "explanation": "语义：考试是考核学业，与“传说”和修行的语境不符。"}, {"text": "游泳", "is_correct": false, "explanation": "搭配：游泳需要水，与“菩提树下”不搭配。"}], "explanations": {"成道": "正确。成道指修行者领悟大道，符合“传说佛祖在菩提树下”的语境。", "上班": "语义：上班指去单位工作，与佛祖修行的情境不符。", "考试": "语义：考试是考核学业，与“传说”和修行的语境不符。", "游泳": "搭配：游泳需要水，与“菩提树下”不搭配。"}, "sentence_index": 0, "correct_answer": "成道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他经营的公司终于成道了。", "explanation": "这里应该用〈成功〉。成道专指修行的人领悟大道，不能用于事业。"}, {"text": "孩子在父母的照顾下，终于成道了。", "explanation": "这里应该用〈长大〉。成道指修行者领悟真理，不能用于普通人的成长。"}, {"text": "这座小城经过二十年的建设，终于成道了。", "explanation": "这里应该用〈建成〉。成道的主体必须是修行的人，城市不能成道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '610d24dd-dceb-4fc2-83b6-fe32f33b0c96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95853, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "成道", "is_correct": true, "explanation": "正确。成道指修行者终于领悟真理，与“坚持”的语境相符。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：吃饭是日常小事，不需要“坚持不下去”的意思，句子不成立。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：“下雨”是天气现象，人不能“想”去下雨，句子不成立。"}, {"text": "送", "is_correct": false, "explanation": "配价：“送”需要带双宾语（送某人某物），句中没有，句子无法成立。"}], "explanations": {"成道": "正确。成道指修行者终于领悟真理，与“坚持”的语境相符。", "吃饭": "语义：吃饭是日常小事，不需要“坚持不下去”的意思，句子不成立。", "下雨": "语义：“下雨”是天气现象，人不能“想”去下雨，句子不成立。", "送": "配价：“送”需要带双宾语（送某人某物），句中没有，句子无法成立。"}, "sentence_index": 6, "correct_answer": "成道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在比赛中终于成道了。", "explanation": "这里应该用〈获胜〉。成道指修行者觉悟真理，不能用于比赛。"}, {"text": "他努力工作三年，终于成道了。", "explanation": "这里应该用〈升职〉。成道是修行者的领悟，不能用于职场晋升。"}, {"text": "他的病经过治疗，终于成道了。", "explanation": "这里应该用〈痊愈〉。成道指觉悟真理，不能用于疾病的康复。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '610d24dd-dceb-4fc2-83b6-fe32f33b0c96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95853, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位老和尚最终成道着。", "corrected_sentence": "这位老和尚最终成道了。", "error_description": "“着”表示动作正在进行，成道是一次性完成的变化，应用“了”，应为“成道了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '610d24dd-dceb-4fc2-83b6-fe32f33b0c96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95853, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在山里修行多年，终于被成道了。", "corrected_sentence": "他在山里修行多年，终于成道了。", "error_description": "“被”字句不能用于不及物动词“成道”，应为“他在山里修行多年，终于成道了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '610d24dd-dceb-4fc2-83b6-fe32f33b0c96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
