INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95855, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "战斗机是一种飞得很快的飞机，用来打仗。", "primary_collocate": null, "pronunciation": "zhàn dòu jī", "ipa": "tʂan˥˩ tou˥˩ tɕi˥", "syllable_count": 3, "sentences": [{"text": "那架战斗机飞得特别快。", "target_word": "战斗机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战斗机是用来打仗的飞机。", "target_word": "战斗机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里的战斗机又快又酷。", "target_word": "战斗机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们抬头看天上的战斗机。", "target_word": "战斗机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战斗机在天上留下一条白线。", "target_word": "战斗机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战斗机不能载很多乘客。", "target_word": "战斗机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国庆节那天，很多战斗机飞过广场。", "target_word": "战斗机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥喜欢玩战斗机模型。", "target_word": "战斗机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战斗机飞过，窗户都响了。", "target_word": "战斗机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他小时候想当战斗机飞行员。", "target_word": "战斗机", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "架", "label": "量词"}, {"form": "战斗机飞行员", "label": "复合"}, {"form": "舰载战斗机", "label": "复合"}, {"form": "戰鬥機", "label": "繁体"}], "register": "中性", "sense_fingerprint": "战斗机：飞得很快、用来打仗的飞机", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9cfefc2-36a9-4169-9dcb-038663488343') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95855, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "战斗机", "is_correct": true, "explanation": "“那架”配飞机，“飞得特别快”说的正是战斗机。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴不会飞，与“飞得特别快”矛盾。"}, {"text": "滑板", "is_correct": false, "explanation": "搭配：滑板的量词是“块”，不说“架”。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车在地面行驶，不会飞。"}], "explanations": {"战斗机": "“那架”配飞机，“飞得特别快”说的正是战斗机。", "钢琴": "语义：钢琴不会飞，与“飞得特别快”矛盾。", "滑板": "搭配：滑板的量词是“块”，不说“架”。", "汽车": "语义：汽车在地面行驶，不会飞。"}, "sentence_index": 0, "correct_answer": "战斗机"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的梦想是当战斗机。", "explanation": "这里应该用〈飞行员〉。战斗机是飞机，不能指人，想当的职业要说飞行员。"}, {"text": "孩子们抬头看天上的一只战斗机。", "explanation": "量词错误：战斗机应说“一架”，不说“一只”，“只”多用于动物。"}, {"text": "停机坪上停着一条战斗机。", "explanation": "量词错误：战斗机应说“一架”，“条”不用于飞机。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2743cbec-9a15-468a-9347-2eae987662b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95855, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "战斗机", "is_correct": true, "explanation": "“很多……飞过广场”说的是会飞的飞机，所以用战斗机。"}, {"text": "火车", "is_correct": false, "explanation": "搭配：火车沿铁路行驶，不能与“飞过”搭配。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不会飞。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是固定的，不会飞过广场。"}], "explanations": {"战斗机": "“很多……飞过广场”说的是会飞的飞机，所以用战斗机。", "火车": "搭配：火车沿铁路行驶，不能与“飞过”搭配。", "桌子": "语义：桌子不会飞。", "窗户": "语义：窗户是固定的，不会飞过广场。"}, "sentence_index": 6, "correct_answer": "战斗机"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "院子里停着一辆战斗机。", "explanation": "量词错误：战斗机应说“一架”，“辆”用于陆上的车，不用于飞机。"}, {"text": "妈妈的抽屉里有一把战斗机。", "explanation": "量词错误：战斗机应说“一架”，“把”用于有柄的器具，不用于飞机。"}, {"text": "公园的草地上有一条战斗机。", "explanation": "量词错误：战斗机应说“一架”，“条”用于细长的东西，不用于飞机。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2743cbec-9a15-468a-9347-2eae987662b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95855, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只战斗机起飞得特别快。", "corrected_sentence": "这架战斗机起飞得特别快。", "error_description": "量词错误：战斗机应用“架”，不用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2743cbec-9a15-468a-9347-2eae987662b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95855, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "姐姐喜欢玩战斗机地模型。", "corrected_sentence": "姐姐喜欢玩战斗机模型。", "error_description": "多余的“地”：“战斗机”修饰“模型”时直接相连，应说“玩战斗机模型”，中间不能加“地”（“地”用于修饰动词）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2743cbec-9a15-468a-9347-2eae987662b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
