INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95856, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用于空战的军用飞机，速度快、机动性强。", "primary_collocate": null, "pronunciation": "zhàn dòu jī", "ipa": "tʂan˥˩ tou˥˩ tɕi˥", "syllable_count": 3, "sentences": [{"text": "天上飞过去三架战斗机。", "target_word": "战斗机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战斗机的速度比客机快得多。", "target_word": "战斗机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这架战斗机能在空中打仗。", "target_word": "战斗机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的爸爸是战斗机飞行员。", "target_word": "战斗机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空军新买了一批战斗机。", "target_word": "战斗机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战斗机起飞时声音很大。", "target_word": "战斗机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆里有一架旧战斗机。", "target_word": "战斗机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战斗机在空中追上了敌机。", "target_word": "战斗机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞行员开着战斗机飞向蓝天。", "target_word": "战斗机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "航空母舰上停着很多战斗机。", "target_word": "战斗机", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "架", "label": "量词"}, {"form": "战斗机飞行员", "label": "复合"}, {"form": "舰载战斗机", "label": "复合"}, {"form": "戰鬥機", "label": "繁体"}], "register": "中性", "sense_fingerprint": "战斗机：空军用来空战、速度快的军用飞机", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9cfefc2-36a9-4169-9dcb-038663488343') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95856, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "战斗机", "is_correct": true, "explanation": "“三架”是飞机的量词，天上飞过去的正是战斗机。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车在地面上行驶，不会飞过天空。"}, {"text": "火车", "is_correct": false, "explanation": "搭配：火车的量词是“列”，不用“架”。"}, {"text": "气球", "is_correct": false, "explanation": "搭配：气球的量词是“个”，不用“架”。"}], "explanations": {"战斗机": "“三架”是飞机的量词，天上飞过去的正是战斗机。", "汽车": "语义：汽车在地面上行驶，不会飞过天空。", "火车": "搭配：火车的量词是“列”，不用“架”。", "气球": "搭配：气球的量词是“个”，不用“架”。"}, "sentence_index": 0, "correct_answer": "战斗机"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的爸爸是战斗机。", "explanation": "这里应该用〈飞行员〉。战斗机是飞机，不能指人，指职业要说飞行员。"}, {"text": "我昨天在商店买了一只战斗机。", "explanation": "量词错误：战斗机应说“一架”，不说“一只”，“只”多用于动物。"}, {"text": "我叔叔开着一辆战斗机去上班。", "explanation": "量词错误：战斗机是飞机，应说“一架”，不说“一辆”，“辆”用于陆上的车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2743cbec-9a15-468a-9347-2eae987662b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95856, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "战斗机", "is_correct": true, "explanation": "“一架”配飞机，博物馆里展出的旧飞机就是战斗机。"}, {"text": "花瓶", "is_correct": false, "explanation": "搭配：“架”不用于花瓶，花瓶的量词是“个”。"}, {"text": "鞋", "is_correct": false, "explanation": "搭配：“架”不用于鞋，鞋的量词是“双”。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：“架”不用于房子，房子的量词是“座”。"}], "explanations": {"战斗机": "“一架”配飞机，博物馆里展出的旧飞机就是战斗机。", "花瓶": "搭配：“架”不用于花瓶，花瓶的量词是“个”。", "鞋": "搭配：“架”不用于鞋，鞋的量词是“双”。", "房子": "搭配：“架”不用于房子，房子的量词是“座”。"}, "sentence_index": 6, "correct_answer": "战斗机"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的书包里有一把战斗机。", "explanation": "量词错误：战斗机应说“一架”，“把”用于有柄的器具，不用于飞机。"}, {"text": "妈妈给我买了一条战斗机。", "explanation": "量词错误：战斗机应说“一架”，“条”用于细长的东西，不用于飞机。"}, {"text": "停机坪上有一头战斗机。", "explanation": "量词错误：战斗机应说“一架”，“头”一般用于牲畜，不用于战斗机。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2743cbec-9a15-468a-9347-2eae987662b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95856, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "天上飞过去两只战斗机。", "corrected_sentence": "天上飞过去两架战斗机。", "error_description": "量词错误：战斗机应用“架”，不用“只”，“只”多用于动物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2743cbec-9a15-468a-9347-2eae987662b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95856, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "飞行员开着地战斗机飞向云层。", "corrected_sentence": "飞行员开着战斗机飞向云层。", "error_description": "多余的“地”：“地”用于修饰动词，不能放在名词“战斗机”前，应说“开着战斗机”，不说“开着地战斗机”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2743cbec-9a15-468a-9347-2eae987662b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
