INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95857, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "提倡是说一件事很好，请大家都这样做。", "primary_collocate": null, "pronunciation": "tí chàng", "ipa": "tʰi˧˥ ʈʂʰaŋ˥˩", "syllable_count": 2, "sentences": [{"text": "老师提倡大家每天早起读书。", "target_word": "提倡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小区提倡垃圾分类。", "target_word": "提倡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸提倡全家人一起吃晚饭。", "target_word": "提倡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院提倡病人多休息。", "target_word": "提倡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁站提倡大家排队上车。", "target_word": "提倡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆提倡安静看书。", "target_word": "提倡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里提倡不乱扔垃圾。", "target_word": "提倡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈提倡我们自己的事自己做。", "target_word": "提倡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厂里提倡工人注意安全。", "target_word": "提倡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师提倡我们用普通话交流。", "target_word": "提倡", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "提倡了", "label": "完成体"}, {"form": "提倡过", "label": "经验体"}, {"form": "大力提倡", "label": "复合"}], "register": "中性", "sense_fingerprint": "提倡：说某事很好，请大家都这样做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd34cd94a-28b4-4837-b0b6-593d7d226e00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95857, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "提倡", "is_correct": true, "explanation": "“提倡”表示说某事很好并请大家这样做，与“早起读书”的语境相符，是正确答案。"}, {"text": "禁止", "is_correct": false, "explanation": "语义：“禁止”表示不许做，与老师希望大家早起读书的意思相反。"}, {"text": "扔", "is_correct": false, "explanation": "搭配：“扔”不能带“大家每天早起读书”这样的小句作宾语。"}, {"text": "讨厌", "is_correct": false, "explanation": "语义：“讨厌”表示不喜欢，与老师认为早起读书是好事的语境不符。"}], "explanations": {"提倡": "“提倡”表示说某事很好并请大家这样做，与“早起读书”的语境相符，是正确答案。", "禁止": "语义：“禁止”表示不许做，与老师希望大家早起读书的意思相反。", "扔": "搭配：“扔”不能带“大家每天早起读书”这样的小句作宾语。", "讨厌": "语义：“讨厌”表示不喜欢，与老师认为早起读书是好事的语境不符。"}, "sentence_index": 0, "correct_answer": "提倡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家超市正在提倡一种新饮料。", "explanation": "这里应该用〈推广〉。提倡指说某事很好、请大家去做，不能用来指把具体商品铺开销售。"}, {"text": "老师提倡了这次考试。", "explanation": "这里应该用〈组织〉。提倡是鼓励大家去做某种做法，不能用来指安排举办一次考试；安排考试要用〈组织〉。"}, {"text": "学校提倡了三十名新生。", "explanation": "这里应该用〈录取〉。提倡的对象是某种做法或观念，不能指一批人；录取新生要用〈录取〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4126d464-5865-4126-bfc4-864583ec3dfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95857, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "提倡", "is_correct": true, "explanation": "“提倡”表示鼓励大家去做，与“不乱扔垃圾”这种好习惯相符，是正确答案。"}, {"text": "批评", "is_correct": false, "explanation": "语义：“批评”是指出错误，与公园鼓励文明行为的语境不符。"}, {"text": "收藏", "is_correct": false, "explanation": "搭配：“收藏”的对象多为具体物品，不能用于“不乱扔垃圾”这样的行为。"}, {"text": "反对", "is_correct": false, "explanation": "语义：“反对”表示不赞成，与公园倡导文明的意思相反。"}], "explanations": {"提倡": "“提倡”表示鼓励大家去做，与“不乱扔垃圾”这种好习惯相符，是正确答案。", "批评": "语义：“批评”是指出错误，与公园鼓励文明行为的语境不符。", "收藏": "搭配：“收藏”的对象多为具体物品，不能用于“不乱扔垃圾”这样的行为。", "反对": "语义：“反对”表示不赞成，与公园倡导文明的意思相反。"}, "sentence_index": 6, "correct_answer": "提倡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "居委会提倡了乱扔垃圾。", "explanation": "这里应该用〈制止〉。提倡是赞成并鼓励做某事，乱扔垃圾应当用〈制止〉。"}, {"text": "我们每天都提倡地板。", "explanation": "这里应该用〈打扫〉。提倡的对象是某种做法或观念，不能指具体的物体；打扫地板要用〈打扫〉。"}, {"text": "妈妈提倡了我的爱好。", "explanation": "这里应该用〈培养〉。提倡的对象是值得大家去做的事，爱好要靠培养，不能说提倡。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4126d464-5865-4126-bfc4-864583ec3dfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95857, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爸爸大量提倡全家人吃健康的早餐。", "corrected_sentence": "爸爸大力提倡全家人吃健康的早餐。", "error_description": "用词搭配错误：“提倡”通常由表示力度的“大力”修饰；“大量”强调数量多，与“提倡”搭配不自然，应说“大力提倡”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4126d464-5865-4126-bfc4-864583ec3dfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
