INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95861, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "担忧是心里害怕会出事，不放心。", "primary_collocate": null, "pronunciation": "dān yōu", "ipa": "tan˥ joʊ˥", "syllable_count": 2, "sentences": [{"text": "妈妈很担忧我一个人出远门。", "target_word": "担忧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下大雨了，大家都担忧河水会涨起来。", "target_word": "担忧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他担忧着女儿的安全，一夜没睡。", "target_word": "担忧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子还没回家，妈妈十分担忧。", "target_word": "担忧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说没事，你不用担忧。", "target_word": "担忧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我担忧飞机会晚点，早早去了机场。", "target_word": "担忧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人担忧地看着窗外的大雨。", "target_word": "担忧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从来没担忧过考试的结果。", "target_word": "担忧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸担忧孩子会在路上出事。", "target_word": "担忧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气越来越冷，我担忧家里的老人。", "target_word": "担忧", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "担忧了", "label": "了体标"}, {"form": "担忧着", "label": "着体标"}, {"form": "担忧过", "label": "过体标"}], "register": "中性", "sense_fingerprint": "害怕会出事而不放心", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d8db740-58a4-47c4-9227-9e17bdaf1786') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95861, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "担忧", "is_correct": true, "explanation": "担忧：为孩子出远门的安全而挂心，与“很”的修饰及句意相合。"}, {"text": "爱护", "is_correct": false, "explanation": "配价：“爱护”的对象是人或物，不能接“我一个人出远门”这类事件作宾语。"}, {"text": "尊敬", "is_correct": false, "explanation": "配价：“尊敬”要求以人为对象，不能接事件小句。"}, {"text": "嫉妒", "is_correct": false, "explanation": "语义：“嫉妒”指对他人的优势心生不满，与母亲为孩子安全挂心的语境不符。"}], "explanations": {"担忧": "担忧：为孩子出远门的安全而挂心，与“很”的修饰及句意相合。", "爱护": "配价：“爱护”的对象是人或物，不能接“我一个人出远门”这类事件作宾语。", "尊敬": "配价：“尊敬”要求以人为对象，不能接事件小句。", "嫉妒": "语义：“嫉妒”指对他人的优势心生不满，与母亲为孩子安全挂心的语境不符。"}, "sentence_index": 0, "correct_answer": "担忧"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "全家人都在担忧老师的帮助。", "explanation": "这里应该用〈感谢〉。担忧表示担心会出坏事，对别人的帮助表示谢意应说感谢。"}, {"text": "我担忧这次比赛能顺利进行。", "explanation": "这里应该用〈盼望〉。担忧指担心坏事发生，希望事情顺利应当用盼望。"}, {"text": "我们担忧新来的客人光临。", "explanation": "这里应该用〈欢迎〉。担忧表示担心，不能用来表达对客人光临的欢迎。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8600dcf-f52c-42c9-a04a-914f560f349c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95861, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "担忧", "is_correct": true, "explanation": "担忧：心里挂着事，与老人凝望窗外大雨的神情相合。"}, {"text": "崇拜", "is_correct": false, "explanation": "配价：“崇拜”的对象是人或权威，不能用来描述看雨的动作。"}, {"text": "拥抱", "is_correct": false, "explanation": "配价：“拥抱”的对象是人，不能用来描述老人看雨的动作。"}, {"text": "膜拜", "is_correct": false, "explanation": "语域：“膜拜”是宗教或仪式性用语，用来描述看雨显得很不自然。"}], "explanations": {"担忧": "担忧：心里挂着事，与老人凝望窗外大雨的神情相合。", "崇拜": "配价：“崇拜”的对象是人或权威，不能用来描述看雨的动作。", "拥抱": "配价：“拥抱”的对象是人，不能用来描述老人看雨的动作。", "膜拜": "语域：“膜拜”是宗教或仪式性用语，用来描述看雨显得很不自然。"}, "sentence_index": 6, "correct_answer": "担忧"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我担忧家里的老人身体健康，每天都很开心。", "explanation": "这里应该用〈希望〉。担忧指担心坏事会发生，对老人健康的美好祝愿要用希望。"}, {"text": "我担忧你一路平安。", "explanation": "这里应该用〈祝福〉。担忧是担心会出事，给出行的人送去平安的祝愿应用祝福。"}, {"text": "大家都担忧他的诚实。", "explanation": "这里应该用〈赞美〉。担忧用于令人担心的事，称赞他人的品质应用赞美。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8600dcf-f52c-42c9-a04a-914f560f349c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95861, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "奶奶担忧得看着天气预报，怕我感冒。", "corrected_sentence": "奶奶担忧地看着天气预报，怕我感冒。", "error_description": "“担忧”在此修饰后面的动词“看着”，作状语，应用“地”连接，写作“担忧地看着”；“得”用于动词之后引出补语，不能接在“担忧”之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8600dcf-f52c-42c9-a04a-914f560f349c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95861, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她正在担忧过孩子的成绩，常常失眠。", "corrected_sentence": "她正在担忧着孩子的成绩，常常失眠。", "error_description": "“正在”表示动作正在进行，应与“着”搭配，不能与表示经历过的“过”同用；应把“过”改为“着”，写作“正在担忧着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8600dcf-f52c-42c9-a04a-914f560f349c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95862, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "安心", "is_correct": true, "explanation": "安心：心里安定、不挂念，与“担忧”构成反义。"}, {"text": "参加", "is_correct": false, "explanation": "参加：指加入某项活动，与“担忧”没有对立关系。"}, {"text": "读书", "is_correct": false, "explanation": "无关：“读书”指阅读学习，与“担忧”没有对立关系。"}, {"text": "唱歌", "is_correct": false, "explanation": "唱歌：指演唱，与“担忧”没有对立关系。"}], "correct_answer": "安心", "explanations": {"安心": "安心：心里安定、不挂念，与“担忧”构成反义。", "参加": "参加：指加入某项活动，与“担忧”没有对立关系。", "读书": "无关：“读书”指阅读学习，与“担忧”没有对立关系。", "唱歌": "唱歌：指演唱，与“担忧”没有对立关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8600dcf-f52c-42c9-a04a-914f560f349c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95862, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "安心", "is_correct": true, "explanation": "安心：心里安定、不挂念，与“担忧”构成反义。"}, {"text": "同意", "is_correct": false, "explanation": "同意：表示赞成，与“担忧”不构成反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "散步：指悠闲地走路，与“担忧”没有对立关系。"}, {"text": "请教", "is_correct": false, "explanation": "请教：指向人求教，与“担忧”没有对立关系。"}], "correct_answer": "安心", "explanations": {"安心": "安心：心里安定、不挂念，与“担忧”构成反义。", "同意": "同意：表示赞成，与“担忧”不构成反义关系。", "散步": "散步：指悠闲地走路，与“担忧”没有对立关系。", "请教": "请教：指向人求教，与“担忧”没有对立关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8600dcf-f52c-42c9-a04a-914f560f349c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95862, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "发愁，忧虑，不放心。", "primary_collocate": null, "pronunciation": "dān yōu", "ipa": "tan˥ joʊ˥", "syllable_count": 2, "sentences": [{"text": "失业以后，他整天担忧生活怎么办。", "target_word": "担忧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都担忧公司明年会不会赚钱。", "target_word": "担忧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她为孩子的学习担忧了很久。", "target_word": "担忧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房价这么高，年轻人担忧买不起房。", "target_word": "担忧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不要为小事担忧，先吃饭吧。", "target_word": "担忧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他担忧着下个月的房租，睡不着觉。", "target_word": "担忧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父母最担忧的是孩子找不到工作。", "target_word": "担忧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作还没有着落，他十分担忧。", "target_word": "担忧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她总是担忧钱不够用。", "target_word": "担忧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们担忧过很多次，可是问题还在。", "target_word": "担忧", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "担忧了", "label": "了体标"}, {"form": "担忧着", "label": "着体标"}, {"form": "担忧过", "label": "过体标"}], "register": "中性", "sense_fingerprint": "为生活工作等事发愁忧虑", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d8db740-58a4-47c4-9227-9e17bdaf1786') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95862, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "担忧", "is_correct": true, "explanation": "担忧：对生活出路发愁、忧虑，与失业后整天发愁的语境相合。"}, {"text": "庆祝", "is_correct": false, "explanation": "语义：“庆祝”针对喜事，与失业后的忧虑正好相反。"}, {"text": "欢迎", "is_correct": false, "explanation": "配价：“欢迎”的对象是人或活动，不能接“生活怎么办”这样的问题。"}, {"text": "赞美", "is_correct": false, "explanation": "搭配：“赞美”用于人或作品，不说“赞美生活怎么办”。"}], "explanations": {"担忧": "担忧：对生活出路发愁、忧虑，与失业后整天发愁的语境相合。", "庆祝": "语义：“庆祝”针对喜事，与失业后的忧虑正好相反。", "欢迎": "配价：“欢迎”的对象是人或活动，不能接“生活怎么办”这样的问题。", "赞美": "搭配：“赞美”用于人或作品，不说“赞美生活怎么办”。"}, "sentence_index": 0, "correct_answer": "担忧"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大家都担忧明年的工资能涨一涨。", "explanation": "这里应该用〈期待〉。担忧表示担心不好的结果，工资上涨是值得期待的好事。"}, {"text": "他担忧朋友送的生日礼物。", "explanation": "这里应该用〈珍惜〉。担忧表示担心会出坏事，对朋友心意的重视应说珍惜。"}, {"text": "我们担忧你明年来公司实习。", "explanation": "这里应该用〈盼望〉。担忧表示担心，对对方来实习这件好事应用盼望。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8600dcf-f52c-42c9-a04a-914f560f349c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95862, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "担忧", "is_correct": true, "explanation": "担忧：为孩子找不到工作而发愁，与“最”和句中的担心语境相合。"}, {"text": "盼望", "is_correct": false, "explanation": "语义：“盼望”寄托的是好结果，与“找不到工作”这种坏情况相反。"}, {"text": "感谢", "is_correct": false, "explanation": "配价：“感谢”的对象是人或帮助，不接“找不到工作”这样的情况。"}, {"text": "欣赏", "is_correct": false, "explanation": "搭配：“欣赏”用于人、作品或优点，不用于“找不到工作”这类困境。"}], "explanations": {"担忧": "担忧：为孩子找不到工作而发愁，与“最”和句中的担心语境相合。", "盼望": "语义：“盼望”寄托的是好结果，与“找不到工作”这种坏情况相反。", "感谢": "配价：“感谢”的对象是人或帮助，不接“找不到工作”这样的情况。", "欣赏": "搭配：“欣赏”用于人、作品或优点，不用于“找不到工作”这类困境。"}, "sentence_index": 6, "correct_answer": "担忧"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我担忧孩子每天都健康快乐。", "explanation": "这里应该用〈希望〉。担忧指担心坏事会发生，对孩子健康快乐的美好期望应用希望。"}, {"text": "我们担忧新婚夫妇幸福美满。", "explanation": "这里应该用〈祝福〉。担忧是担心会出事，对新人幸福美满的良好祝愿应用祝福。"}, {"text": "老师担忧这次考试的进步。", "explanation": "这里应该用〈表扬〉。担忧用于令人担心的事，称赞学生的进步应用表扬。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8600dcf-f52c-42c9-a04a-914f560f349c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95862, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他为房租担忧地睡不着觉。", "corrected_sentence": "他为房租担忧得睡不着觉。", "error_description": "“睡不着觉”是“担忧”的结果补语，需要用“得”连接，应为“担忧得睡不着觉”；用“地”会把“担忧”当作修饰语，句意不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8600dcf-f52c-42c9-a04a-914f560f349c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95862, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们正在担忧了一个晚上，还是没想出办法。", "corrected_sentence": "他们担忧了一个晚上，还是没想出办法。", "error_description": "“正在”表示动作进行中，与表示完成的“了”矛盾；应去掉“正在”，写作“担忧了一个晚上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8600dcf-f52c-42c9-a04a-914f560f349c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
