INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95866, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "风景优美、供人游览观赏的地点。", "primary_collocate": null, "pronunciation": "jǐng diǎn", "ipa": "tɕiŋ˨˩˦ tjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "这座古城有十几个著名的景点。", "target_word": "景点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "来云南旅游，你一定要去这个景点。", "target_word": "景点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个景点既有山，又有水。", "target_word": "景点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游客们在景点门口排队买票。", "target_word": "景点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的景点很多，一天走不完。", "target_word": "景点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把照片发给朋友，介绍这个景点。", "target_word": "景点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个新景点去年才对外开放。", "target_word": "景点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先看了湖边的景点，再去山顶。", "target_word": "景点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天的景点里，海边最热闹。", "target_word": "景点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些景点都离市中心不远。", "target_word": "景点", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "处", "label": "量词"}, {"form": "景點", "label": "繁体"}], "register": "中性", "sense_fingerprint": "风景优美、供人游览观赏的地点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6ff1bd0-a59b-4b61-b6ac-44883ef294ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95866, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "景点", "is_correct": true, "explanation": "景点：风景优美、供人游览的地方，正是这个词的意思。"}, {"text": "经典", "is_correct": false, "explanation": "声调不同：jīng（第一声）与 jǐng（第三声）声调不同，“经典”指有代表性、被推崇的作品或事物，不是游览地。"}, {"text": "顶点", "is_correct": false, "explanation": "声母不同：dǐng 与 jǐng 的声母 d 与 j 不同，“顶点”指最高处或发展的最高阶段。"}, {"text": "检点", "is_correct": false, "explanation": "韵尾不同：jiǎn 收 -n，jǐng 收 -ng，韵母 ian 与 ing 不同；“检点”指注意自己的言行，不是游览地。"}], "explanations": {"景点": "景点：风景优美、供人游览的地方，正是这个词的意思。", "经典": "声调不同：jīng（第一声）与 jǐng（第三声）声调不同，“经典”指有代表性、被推崇的作品或事物，不是游览地。", "顶点": "声母不同：dǐng 与 jǐng 的声母 d 与 j 不同，“顶点”指最高处或发展的最高阶段。", "检点": "韵尾不同：jiǎn 收 -n，jǐng 收 -ng，韵母 ian 与 ing 不同；“检点”指注意自己的言行，不是游览地。"}, "sentence_index": null, "correct_answer": "景点"}, "level_3": {"options": [{"text": "景点", "is_correct": true, "explanation": "景点：风景优美、供人游览的地方，与“古城”“著名”相符。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：“雨伞”是遮雨用具，不是可以游览观赏的地方。"}, {"text": "病历", "is_correct": false, "explanation": "搭配：“著名的”只修饰景点、人物等，不能修饰病历。"}, {"text": "绳子", "is_correct": false, "explanation": "语义：“绳子”是捆扎用的物件，与古城的游览无关。"}], "explanations": {"景点": "景点：风景优美、供人游览的地方，与“古城”“著名”相符。", "雨伞": "语义：“雨伞”是遮雨用具，不是可以游览观赏的地方。", "病历": "搭配：“著名的”只修饰景点、人物等，不能修饰病历。", "绳子": "语义：“绳子”是捆扎用的物件，与古城的游览无关。"}, "sentence_index": 0, "correct_answer": "景点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们去了一朵景点。", "explanation": "这里应该用〈个〉。“朵”用于花朵，景点不能用“朵”来计量。"}, {"text": "他用景点切西瓜。", "explanation": "这里应该用〈刀〉。切西瓜要用刀，景点是供人游览的地方，不能当作切东西的工具。"}, {"text": "这台景点很大。", "explanation": "这里应该用〈个〉。“台”用于机器，景点不能用“台”来计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '610d24dd-dceb-4fc2-83b6-fe32f33b0c96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_ver