INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95866, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "景点", "is_correct": true, "explanation": "景点：风景优美、供人游览的地方，才能对外开放。"}, {"text": "电线", "is_correct": false, "explanation": "搭配：“对外开放”用于场所，不能说电线对外开放。"}, {"text": "面包", "is_correct": false, "explanation": "语义：“面包”是食品，与对外开放的场所无关。"}, {"text": "瓶子", "is_correct": false, "explanation": "语义：“瓶子”是容器，不是供人游览的地方。"}], "explanations": {"景点": "景点：风景优美、供人游览的地方，才能对外开放。", "电线": "搭配：“对外开放”用于场所，不能说电线对外开放。", "面包": "语义：“面包”是食品，与对外开放的场所无关。", "瓶子": "语义：“瓶子”是容器，不是供人游览的地方。"}, "sentence_index": 6, "correct_answer": "景点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场演出的景点定在礼堂。", "explanation": "这里应该用〈地点〉。景点专指风景优美、供人游览的地方，不用于演出场所。"}, {"text": "妈妈做了一盘景点。", "explanation": "这里应该用〈菜〉。“做一盘”要用菜肴之类的食物，景点是供人游览的地方，不能做成食物。"}, {"text": "这些景点都会唱歌。", "explanation": "这里应该用〈歌手〉。会唱歌的是人，景点是地方，不能作“会唱歌”的主语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '610d24dd-dceb-4fc2-83b6-fe32f33b0c96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95866, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座城市有很多条景点。", "corrected_sentence": "这座城市有很多景点。", "error_description": "量词错误：“景点”前不能加“条”（“条”用于细长的物件），这里直接说“很多景点”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '610d24dd-dceb-4fc2-83b6-fe32f33b0c96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95866, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "游客都喜欢这辆景点。", "corrected_sentence": "游客都喜欢这个景点。", "error_description": "量词错误：“景点”应用“个”，“辆”用于车辆，不能修饰景点。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '610d24dd-dceb-4fc2-83b6-fe32f33b0c96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
