INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95873, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "演唱会是歌手在台上唱歌给很多人听的活动。", "primary_collocate": null, "pronunciation": "yǎn chàng huì", "ipa": "jɛn˨˩˦ ʈʂʰaŋ˥˩ xweɪ˥˩", "syllable_count": 3, "sentences": [{"text": "他在演唱会上唱了十首歌。", "target_word": "演唱会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演唱会现场有一万多人。", "target_word": "演唱会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我妹妹最喜欢的歌手要来开演唱会了。", "target_word": "演唱会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天的演唱会，我在家看了直播。", "target_word": "演唱会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演唱会的灯光很漂亮，歌声也很好听。", "target_word": "演唱会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下个月城里有一场演唱会，你去吗？", "target_word": "演唱会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想带妈妈去看她的第一场演唱会。", "target_word": "演唱会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演唱会中间，歌手给大家讲了个小故事。", "target_word": "演唱会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为下雨，演唱会改到了下周。", "target_word": "演唱会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听完演唱会，我们一路唱着歌回家。", "target_word": "演唱会", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "场", "label": "量词"}, {"form": "个人演唱会", "label": "复合"}, {"form": "演唱會", "label": "繁体"}], "register": "中性", "sense_fingerprint": "演唱会:歌手在台上唱歌给很多人听的活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3b264aa-b95b-40a2-9864-e252a279c2f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95873, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "演唱会", "is_correct": true, "explanation": "正确：演唱会是歌手在台上唱歌的活动，“在演唱会上”表示地点。"}, {"text": "课本", "is_correct": false, "explanation": "语义：“课本”是书，不能作唱歌的场所，与“唱了十首歌”不相容。"}, {"text": "厨房", "is_correct": false, "explanation": "搭配：“厨房”后面一般用“里”，不说“在厨房上”。"}, {"text": "图书馆", "is_correct": false, "explanation": "搭配：“图书馆”后面应用“里”，不能与“上”搭配。"}], "explanations": {"演唱会": "正确：演唱会是歌手在台上唱歌的活动，“在演唱会上”表示地点。", "课本": "语义：“课本”是书，不能作唱歌的场所，与“唱了十首歌”不相容。", "厨房": "搭配：“厨房”后面一般用“里”，不说“在厨房上”。", "图书馆": "搭配：“图书馆”后面应用“里”，不能与“上”搭配。"}, "sentence_index": 0, "correct_answer": "演唱会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场演唱会的裁判很公正。", "explanation": "这里应该用〈比赛〉。演唱会是歌手的演出，没有裁判，裁判是比赛的角色。"}, {"text": "这场演唱会的展品很多，大家慢慢看。", "explanation": "这里应该用〈展览〉。演唱会是歌手的演出，没有展品，展品属于展览。"}, {"text": "我们昨天开了一场演唱会，讨论了工作。", "explanation": "这里应该用〈会议〉。演唱会是歌手在台上唱歌的活动，不能用来讨论工作，应说会议。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e9d3a1d-3f50-474f-99e2-3628cc50ae16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95873, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "演唱会", "is_correct": true, "explanation": "正确：“第一场演唱会”指第一次举办的演出，可以去看。"}, {"text": "饭", "is_correct": false, "explanation": "搭配：“场”用于活动，饭不以“场”计，也不能说“去看第一场饭”。"}, {"text": "论文", "is_correct": false, "explanation": "语义：论文是写出来的文章，不是可以“去看”的活动。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业不是可以“去看”的活动，与“第一场”不相配。"}], "explanations": {"演唱会": "正确：“第一场演唱会”指第一次举办的演出，可以去看。", "饭": "搭配：“场”用于活动，饭不以“场”计，也不能说“去看第一场饭”。", "论文": "语义：论文是写出来的文章，不是可以“去看”的活动。", "作业": "语义：作业不是可以“去看”的活动，与“第一场”不相配。"}, "sentence_index": 6, "correct_answer": "演唱会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们班这次演唱会的及格率是百分之九十。", "explanation": "这里应该用〈考试〉。演唱会是歌手的演出，没有“及格率”，及格率属于考试。"}, {"text": "这场演唱会由著名教授主讲。", "explanation": "这里应该用〈讲座〉。演唱会是歌手的演出，不能由人“主讲”，主讲是讲座的说法。"}, {"text": "这场演唱会只有钢琴曲，没有人唱歌。", "explanation": "这里应该用〈音乐会〉。演唱会要有人唱歌，只有器乐演奏的应说“音乐会”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e9d3a1d-3f50-474f-99e2-3628cc50ae16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95873, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我买了一首演唱会的票。", "corrected_sentence": "我买了一场演唱会的票。", "error_description": "错误形式：“一首演唱会”；正确形式：“一场演唱会”。“首”用于歌曲、诗词，演唱会的量词是“场”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e9d3a1d-3f50-474f-99e2-3628cc50ae16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95873, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我以前看着演唱会。", "corrected_sentence": "我以前看过演唱会。", "error_description": "错误形式：“看着演唱会”；正确形式：“看过演唱会”。表示曾经有过的经历要用经历体“过”，“着”表示动作的持续，不能表示以前看过。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e9d3a1d-3f50-474f-99e2-3628cc50ae16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
