INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95875, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "无干是和这件事没有关系。", "primary_collocate": null, "pronunciation": "wú gān", "ipa": "u˧˥ kan˥", "syllable_count": 2, "sentences": [{"text": "这个问题与天气无干。", "target_word": "无干", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此事与旁人无干，请大家不要议论。", "target_word": "无干", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的错和别人无干，不用怪大家。", "target_word": "无干", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她离开公司，与你无干。", "target_word": "无干", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些旧书与考试无干，你可以不看。", "target_word": "无干", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我只想说，这件事跟孩子无干。", "target_word": "无干", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁来当队长与我无干，我只管做好自己的事。", "target_word": "无干", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们吵架，和我们无干，我们走吧。", "target_word": "无干", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事与学校无干，是家里的问题。", "target_word": "无干", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请放心，这次失败与你无干。", "target_word": "无干", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "和这件事没有关系，用来撇清责任", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afcd0b75-9fed-4b31-9fb8-4f73e2bd4177') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95875, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "无干", "is_correct": true, "explanation": "无干：与某人某事没有关联，是本题的正确答案。"}, {"text": "鱼干", "is_correct": false, "explanation": "yú（第二声）与 wú（第二声）只有韵母不同（ü 与 u），意思是“鱼干”（晒干或晾干的鱼），不是“无干”。"}, {"text": "无根", "is_correct": false, "explanation": "gēn（第一声）与 gān（第一声）只有韵母不同（en 与 an），意思是“无根”（没有根基），与“无干”意思不同。"}, {"text": "五感", "is_correct": false, "explanation": "wǔ（第三声）与 wú（第二声）、gǎn（第三声）与 gān（第一声）声调不同，意思是“五感”（视、听、嗅、味、触五种感觉）。"}], "explanations": {"无干": "无干：与某人某事没有关联，是本题的正确答案。", "鱼干": "yú（第二声）与 wú（第二声）只有韵母不同（ü 与 u），意思是“鱼干”（晒干或晾干的鱼），不是“无干”。", "无根": "gēn（第一声）与 gān（第一声）只有韵母不同（en 与 an），意思是“无根”（没有根基），与“无干”意思不同。", "五感": "wǔ（第三声）与 wú（第二声）、gǎn（第三声）与 gān（第一声）声调不同，意思是“五感”（视、听、嗅、味、触五种感觉）。"}, "sentence_index": null, "correct_answer": "无干"}, "level_3": {"options": [{"text": "无干", "is_correct": true, "explanation": "无干：与某事没有关系，符合“这个问题与天气没有关系”的句意。"}, {"text": "见面", "is_correct": false, "explanation": "配价：“见面”要求双方都是人，“这个问题”不能与“天气”见面。"}, {"text": "分手", "is_correct": false, "explanation": "语义：“分手”说关系断开，用在“这个问题”和“天气”之间说不通。"}, {"text": "相识", "is_correct": false, "explanation": "语义：“相识”说人与人互相认识，“这个问题”与“天气”不能相识。"}], "explanations": {"无干": "无干：与某事没有关系，符合“这个问题与天气没有关系”的句意。", "见面": "配价：“见面”要求双方都是人，“这个问题”不能与“天气”见面。", "分手": "语义：“分手”说关系断开，用在“这个问题”和“天气”之间说不通。", "相识": "语义：“相识”说人与人互相认识，“这个问题”与“天气”不能相识。"}, "sentence_index": 0, "correct_answer": "无干"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "湿毛巾还无干，先别拿走。", "explanation": "这里应该用〈没干〉。无干表示“与…没有关联”，不能用来说毛巾没有干。"}, {"text": "今天放假，我无干，只能在家躺着。", "explanation": "这里应该用〈没事干〉。无干表示与某事没有关联，不表示没有事情做。"}, {"text": "他一整天都无干，什么也不想做。", "explanation": "这里应该用〈没精神〉。无干表示“与…没有关联”，不能用来形容一个人没有精神。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda09645-f95d-4b38-abea-00657f3ba78a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95875, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "无干", "is_correct": true, "explanation": "无干：与某人某事没有关联，是本题的正确答案。"}, {"text": "鱼竿", "is_correct": false, "explanation": "yú（第二声）与 wú（第二声）只有韵母不同（ü 与 u），gān 相同，意思是“鱼竿”（钓鱼用的竿子）。"}, {"text": "无根", "is_correct": false, "explanation": "gēn（第一声）与 gān（第一声）只有韵母不同（en 与 an），意思是“无根”（没有根基），与“无干”意思不同。"}, {"text": "无感", "is_correct": false, "explanation": "gǎn（第三声）与 gān（第一声）声调不同，意思是“无感”（没有感觉、不在意）。"}], "explanations": {"无干": "无干：与某人某事没有关联，是本题的正确答案。", "鱼竿": "yú（第二声）与 wú（第二声）只有韵母不同（ü 与 u），gān 相同，意思是“鱼竿”（钓鱼用的竿子）。", "无根": "gēn（第一声）与 gān（第一声）只有韵母不同（en 与 an），意思是“无根”（没有根基），与“无干”意思不同。", "无感": "gǎn（第三声）与 gān（第一声）声调不同，意思是“无感”（没有感觉、不在意）。"}, "sentence_index": null, "correct_answer": "无干"}, "level_3": {"options": [{"text": "无干", "is_correct": true, "explanation": "无干：与某人某事没有关联，符合“谁来当队长和我没有关系”的句意。"}, {"text": "相连", "is_correct": false, "explanation": "语义：“相连”说事物在空间或结构上连在一起，用来说“谁当队长”与“我”不合。"}, {"text": "结婚", "is_correct": false, "explanation": "配价：“结婚”要求双方都是人，且要成为配偶，“谁来当队长”与“我”之间说不通。"}, {"text": "同居", "is_correct": false, "explanation": "语义：“同居”说共同生活，与“谁来当队长”的语境完全不合。"}], "explanations": {"无干": "无干：与某人某事没有关联，符合“谁来当队长和我没有关系”的句意。", "相连": "语义：“相连”说事物在空间或结构上连在一起，用来说“谁当队长”与“我”不合。", "结婚": "配价：“结婚”要求双方都是人，且要成为配偶，“谁来当队长”与“我”之间说不通。", "同居": "语义：“同居”说共同生活，与“谁来当队长”的语境完全不合。"}, "sentence_index": 6, "correct_answer": "无干"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "路上堵车，让你久等了。——无干，我刚到。", "explanation": "这里应该用〈没关系〉。表示不介意、不要紧时要说没关系，无干不能用来回应对方的道歉。"}, {"text": "这件湿衬衫还无干，先别穿。", "explanation": "这里应该用〈没干〉。无干表示“与…没有关联”，不能用来说衣服没有干。"}, {"text": "这件事已经交给无干部门跟进了。", "explanation": "这里应该用〈有关〉。有关部门指与事情相关的机构，无干不能修饰“部门”，只能表示没有关系。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda09645-f95d-4b38-abea-00657f3ba78a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95875, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那件事无干，你别再来问了。", "corrected_sentence": "那件事与我无干，你别再来问了。", "error_description": "错误：省略了“与我”。正确：“与我无干”。“无干”前面要用“与…”引出关联的对象，不能单独说“无干”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda09645-f95d-4b38-abea-00657f3ba78a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95875, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这笔钱无干，你别替他着急。", "corrected_sentence": "这笔钱与你无干，你别替他着急。", "error_description": "错误：省略了“与你”。正确：“与你无干”。“无干”后面要用“与…”引出关联的对象，不能单独说“无干”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda09645-f95d-4b38-abea-00657f3ba78a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
