INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95879, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "珍贵是很少见，很值钱，要好好保护。", "primary_collocate": null, "pronunciation": "zhēn guì", "ipa": "ʈʂən˥ kweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "这块石头很珍贵，要放在玻璃柜里。", "target_word": "珍贵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些珍贵的书需要好好保护。", "target_word": "珍贵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那种鸟非常珍贵，全国只剩几十只。", "target_word": "珍贵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我看了一张珍贵的地图。", "target_word": "珍贵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把爷爷的珍贵手表放在盒子里。", "target_word": "珍贵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆不让游客碰这件珍贵的瓷器。", "target_word": "珍贵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这棵树很珍贵，不能随便砍。", "target_word": "珍贵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个花瓶太珍贵了，千万别摔坏。", "target_word": "珍贵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里保存着很多珍贵的照片。", "target_word": "珍贵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸有一枚很珍贵的旧邮票。", "target_word": "珍贵", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "很少见、很值钱、要好好保护", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d8db740-58a4-47c4-9227-9e17bdaf1786') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95879, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "珍贵", "is_correct": true, "explanation": "珍贵修饰“石头”，表示很少见、很值钱，要放在柜子里，符合句意。"}, {"text": "狭窄", "is_correct": false, "explanation": "搭配：“狭窄”说空间、道路，不说石头。"}, {"text": "响亮", "is_correct": false, "explanation": "语义：“响亮”形容声音，与石头无关。"}, {"text": "吵闹", "is_correct": false, "explanation": "语义：“吵闹”形容环境或人声，不能用来形容石头。"}], "explanations": {"珍贵": "珍贵修饰“石头”，表示很少见、很值钱，要放在柜子里，符合句意。", "狭窄": "搭配：“狭窄”说空间、道路，不说石头。", "响亮": "语义：“响亮”形容声音，与石头无关。", "吵闹": "语义：“吵闹”形容环境或人声，不能用来形容石头。"}, "sentence_index": 0, "correct_answer": "珍贵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张地图很珍贵，教室里每人发一张。", "explanation": "这里应该用〈普通〉。珍贵指稀少、值钱，人人可得的地图只能说普通。"}, {"text": "这盒饼干很珍贵，我们一天吃三盒。", "explanation": "这里应该用〈日常〉。珍贵指稀少、值钱，一天吃三盒的饼干属于日常食品，不能用珍贵形容。"}, {"text": "这支铅笔很珍贵，考试时发给每个人。", "explanation": "这里应该用〈廉价〉。珍贵指稀少、值钱，人人都能拿到的铅笔应说廉价。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8600dcf-f52c-42c9-a04a-914f560f349c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95879, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "珍贵", "is_correct": true, "explanation": "珍贵修饰“树”，表示很少见、很值钱，不能随便砍，符合句意。"}, {"text": "锋利", "is_correct": false, "explanation": "搭配：“锋利”说刀具、刀口，不说树。"}, {"text": "清脆", "is_correct": false, "explanation": "语义：“清脆”形容声音或食物口感，不能修饰树。"}, {"text": "嘹亮", "is_correct": false, "explanation": "语义：“嘹亮”形容声音，与树无关。"}], "explanations": {"珍贵": "珍贵修饰“树”，表示很少见、很值钱，不能随便砍，符合句意。", "锋利": "搭配：“锋利”说刀具、刀口，不说树。", "清脆": "语义：“清脆”形容声音或食物口感，不能修饰树。", "嘹亮": "语义：“嘹亮”形容声音，与树无关。"}, "sentence_index": 6, "correct_answer": "珍贵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这些旧报纸很珍贵，我们每周都当废品卖掉。", "explanation": "这里应该用〈普通〉。珍贵指很少见、很值钱，随便当废品卖掉的旧报纸只能说普通，不能用珍贵形容。"}, {"text": "这块石子很珍贵，满地都是。", "explanation": "这里应该用〈常见〉。珍贵指很少见，满地都是的石子只能说常见，不能用珍贵形容。"}, {"text": "这把旧扫帚很珍贵，超市里有很多。", "explanation": "这里应该用〈廉价〉。珍贵指很少见、很值钱，超市里很多的扫帚只能说廉价，不能用珍贵形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8600dcf-f52c-42c9-a04a-914f560f349c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95879, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他很珍贵这块玉，不肯随便送人。", "corrected_sentence": "他很珍惜这块玉，不肯随便送人。", "error_description": "“珍贵”是形容词，不能带宾语；表示爱惜的动作要用动词“珍惜”，应说“很珍惜这块玉”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8600dcf-f52c-42c9-a04a-914f560f349c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95879, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些珍贵地照片要好好保存。", "corrected_sentence": "这些珍贵的照片要好好保存。", "error_description": "“珍贵”修饰名词“照片”时要用“的”，不能用“地”。应为“珍贵的照片”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8600dcf-f52c-42c9-a04a-914f560f349c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
