INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95880, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "价值高、稀少而宝贵。", "primary_collocate": null, "pronunciation": "zhēn guì", "ipa": "ʈʂən˥ kweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "这件古画非常珍贵。", "target_word": "珍贵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆里有很多珍贵的文物。", "target_word": "珍贵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大熊猫是珍贵的动物。", "target_word": "珍贵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张老照片对我来说很珍贵。", "target_word": "珍贵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶留下了一对珍贵的玉镯。", "target_word": "珍贵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书很珍贵，全世界只有三本。", "target_word": "珍贵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那里的森林里有很多珍贵的树。", "target_word": "珍贵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一份珍贵的礼物，我会好好收着。", "target_word": "珍贵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些资料非常珍贵，请不要弄丢。", "target_word": "珍贵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "珍贵的药材很难在市场上买到。", "target_word": "珍贵", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "价值高、稀少而宝贵", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d8db740-58a4-47c4-9227-9e17bdaf1786') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95880, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "珍贵", "is_correct": true, "explanation": "珍贵修饰古画，表示价值高、稀少，符合句意。"}, {"text": "透明", "is_correct": false, "explanation": "语义：“透明”说能透光的东西，不能用来评价古画的价值。"}, {"text": "狭窄", "is_correct": false, "explanation": "搭配：“狭窄”说空间、道路，不用来形容古画。"}, {"text": "响亮", "is_correct": false, "explanation": "搭配：“响亮”说声音，不说画。"}], "explanations": {"珍贵": "珍贵修饰古画，表示价值高、稀少，符合句意。", "透明": "语义：“透明”说能透光的东西，不能用来评价古画的价值。", "狭窄": "搭配：“狭窄”说空间、道路，不用来形容古画。", "响亮": "搭配：“响亮”说声音，不说画。"}, "sentence_index": 0, "correct_answer": "珍贵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种白菜很珍贵，菜市场随处都有。", "explanation": "这里应该用〈便宜〉。珍贵说稀少、价值高，普通蔬菜不能用珍贵形容。"}, {"text": "这种鸟很珍贵，公园里到处都是。", "explanation": "这里应该用〈常见〉。珍贵指稀少，常见的鸟不能用珍贵形容。"}, {"text": "这把寻常的塑料尺很珍贵，文具店里摆满了。", "explanation": "这里应该用〈寻常〉。珍贵指稀少、值钱，文具店里摆满的塑料尺不能用珍贵形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8600dcf-f52c-42c9-a04a-914f560f349c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95880, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "珍贵", "is_correct": true, "explanation": "珍贵修饰“树”，表示稀少、值钱，符合句意。"}, {"text": "锋利", "is_correct": false, "explanation": "搭配：“锋利”说刀具、刀口，不说树林里的树。"}, {"text": "清脆", "is_correct": false, "explanation": "语义：“清脆”形容声音或食物口感，不能修饰树。"}, {"text": "嘹亮", "is_correct": false, "explanation": "语义：“嘹亮”形容声音，与树无关。"}], "explanations": {"珍贵": "珍贵修饰“树”，表示稀少、值钱，符合句意。", "锋利": "搭配：“锋利”说刀具、刀口，不说树林里的树。", "清脆": "语义：“清脆”形容声音或食物口感，不能修饰树。", "嘹亮": "语义：“嘹亮”形容声音，与树无关。"}, "sentence_index": 6, "correct_answer": "珍贵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这些废纸很珍贵，我们每天都扔进垃圾桶。", "explanation": "这里应该用〈常见〉。珍贵指稀少、值钱；每天随手扔进垃圾桶的废纸只能说常见，不能用珍贵形容。"}, {"text": "这把雨伞很珍贵，他每次下雨都把它丢在公园。", "explanation": "这里应该用〈普通〉。珍贵指稀少、值钱，常丢在公园的雨伞只能说普通。"}, {"text": "这盒火柴很珍贵，我们一天要用掉十盒。", "explanation": "这里应该用〈常用〉。珍贵指稀少，一天用掉十盒的火柴属于常用之物，不能用珍贵形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8600dcf-f52c-42c9-a04a-914f560f349c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95880, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我很珍贵这幅古画，不肯随便借人。", "corrected_sentence": "我很珍惜这幅古画，不肯随便借人。", "error_description": "“珍贵”是形容词，不能带宾语；表示爱惜的动作要用动词“珍惜”，应说“很珍惜这幅古画”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8600dcf-f52c-42c9-a04a-914f560f349c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95880, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那对玉镯很珍贵地，我们要好好收着。", "corrected_sentence": "那对玉镯很珍贵，我们要好好收着。", "error_description": "“珍贵”作谓语，后面的“地”多余。应说“很珍贵，我们要好好收着”，不能加“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8600dcf-f52c-42c9-a04a-914f560f349c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95885, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda09645-f95d-4b38-abea-00657f3ba78a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95885, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda09645-f95d-4b38-abea-00657f3ba78a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95885, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "真人是真的人，不是画出来的，也不是假的。", "primary_collocate": null, "pronunciation": "zhēn rén", "ipa": "ʈʂən˥ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "这部电影里有真人，也有动画。", "target_word": "真人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "照片里的小孩是真人，不是画的。", "target_word": "真人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏里的人物看起来很像真人。", "target_word": "真人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想看真人演的电影，不想看动画片。", "target_word": "真人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个机器人做得太逼真了，我差点以为它是真人。", "target_word": "真人", "complexity_tier": "T3", "furigana": "zhè ge jī qì rén zuò de tài bī zhēn le, wǒ chà diǎn yǐ wéi tā shì zhēn rén.", "sentence_source": "generated"}, {"text": "这个玩偶做得太像了，像真人一样。", "target_word": "真人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墙上的那个人很逼真，我走近才发现不是真人。", "target_word": "真人", "complexity_tier": "T3", "furigana": "qiáng shàng de nà ge rén hěn bī zhēn, wǒ zǒu jìn cái fā xiàn bú shì zhēn rén.", "sentence_source": "generated"}, {"text": "比起动画，我更喜欢看真人演的戏。", "target_word": "真人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小孩站在那里不动，我以为他不是真人。", "target_word": "真人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说，网上聊天的人不一定是真人。", "target_word": "真人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "真人秀", "label": "复合"}], "register": "中性", "sense_fingerprint": "真实存在的人，不是画的也不是假的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afcd0b75-9fed-4b31-9fb8-4f73e2bd4177') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95885, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "真人", "is_correct": true, "explanation": "真人：真实存在的人，不是画出来的，也不是假的，是本题的正确答案。"}, {"text": "整人", "is_correct": false, "explanation": "zhěng（第三声）与 zhēn（第一声）韵母不同（eng 与 en）且声调不同，意思是“整人”（捉弄、折磨别人）。"}, {"text": "神人", "is_correct": false, "explanation": "shén（第二声）与 zhēn（第一声）声母不同（sh 与 zh）且声调不同，意思是“神人”（超乎常人的人）。"}, {"text": "正人", "is_correct": false, "explanation": "zhèng（第四声）与 zhēn（第一声）韵母不同（eng 与 en）且声调不同，意思是“正人”（正直的人）。"}], "explanations": {"真人": "真人：真实存在的人，不是画出来的，也不是假的，是本题的正确答案。", "整人": "zhěng（第三声）与 zhēn（第一声）韵母不同（eng 与 en）且声调不同，意思是“整人”（捉弄、折磨别人）。", "神人": "shén（第二声）与 zhēn（第一声）声母不同（sh 与 zh）且声调不同，意思是“神人”（超乎常人的人）。", "正人": "zhèng（第四声）与 zhēn（第一声）韵母不同（eng 与 en）且声调不同，意思是“正人”（正直的人）。"}, "sentence_index": null, "correct_answer": "真人"}, "level_3": {"options": [{"text": "真人", "is_correct": true, "explanation": "真人：真实存在的人，与“动画”相对，符合“这部电影里有真人，也有动画”的句意。"}, {"text": "白菜", "is_correct": false, "explanation": "语义：“白菜”不是电影中可以与“动画”并列的一类内容，句意说不通。"}, {"text": "手表", "is_correct": false, "explanation": "语义：“手表”不是电影的组成类别，与“也有动画”并列说不通。"}, {"text": "棋子", "is_correct": false, "explanation": "搭配：“有…也有动画”要求并列的是影像类别，“棋子”不能与“动画”并列。"}], "explanations": {"真人": "真人：真实存在的人，与“动画”相对，符合“这部电影里有真人，也有动画”的句意。", "白菜": "语义：“白菜”不是电影中可以与“动画”并列的一类内容，句意说不通。", "手表": "语义：“手表”不是电影的组成类别，与“也有动画”并列说不通。", "棋子": "搭配：“有…也有动画”要求并列的是影像类别，“棋子”不能与“动画”并列。"}, "sentence_index": 0, "correct_answer": "真人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "剧组请来了一部真人，专门演那个老爷爷。", "explanation": "这里应该用〈位〉或〈个〉。真人指人，量词“部”用于电影、书等，不能用于真人。"}, {"text": "他对她的感情是真人的，不是装的。", "explanation": "这里应该用〈真实〉。真人指真实存在的人，不能用来修饰感情。"}, {"text": "这只小狗是真人，很聪明。", "explanation": "这里应该用〈动物〉。真人只指真实存在的人，不能指动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda09645-f95d-4b38-abea-00657f3ba78a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95885, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "真人", "is_correct": true, "explanation": "真人：真实存在的人，符合“我走近才发现不是真人”的句意。"}, {"text": "猫", "is_correct": false, "explanation": "语义：“墙上的那个人”不可能是猫，“我走近才发现不是猫”说不通。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：“墙上的那个人”和窗户不是同类事物，“不是窗户”与句子的语境不合。"}, {"text": "数字", "is_correct": false, "explanation": "搭配：“不是数字”一般不用来描述一个人，“数字”与“那个人”搭配不当。"}], "explanations": {"真人": "真人：真实存在的人，符合“我走近才发现不是真人”的句意。", "猫": "语义：“墙上的那个人”不可能是猫，“我走近才发现不是猫”说不通。", "窗户": "语义：“墙上的那个人”和窗户不是同类事物，“不是窗户”与句子的语境不合。", "数字": "搭配：“不是数字”一般不用来描述一个人，“数字”与“那个人”搭配不当。"}, "sentence_index": 6, "correct_answer": "真人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这幅画是真人，线条很细。", "explanation": "这里应该用〈作品〉。真人指真实存在的人，不能用来指一幅画。"}, {"text": "这部动画的角色都是真人，很可爱。", "explanation": "这里应该用〈人物〉。动画里的人物是画出来的，不是真人。"}, {"text": "我家的鹦鹉是真人，很会说话。", "explanation": "这里应该用〈动物〉。真人只指真实存在的人，不能指动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda09645-f95d-4b38-abea-00657f3ba78a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95885, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "剧组请来一只真人，演那个老爷爷。", "corrected_sentence": "剧组请来一位真人，演那个老爷爷。", "error_description": "错误：量词“只”。正确：“位”。“只”用于动物，“真人”指人，要用“位”或“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda09645-f95d-4b38-abea-00657f3ba78a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95885, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个站在门口的人真人，不是模特。", "corrected_sentence": "那个站在门口的人是真人，不是模特。", "error_description": "错误：漏了“是”。正确：“是真人”。真人作谓语时要用“是”连接。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda09645-f95d-4b38-abea-00657f3ba78a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
