INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95889, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "眼光是一个人看事情、看东西的想法。", "primary_collocate": null, "pronunciation": "yǎn guāng", "ipa": "jɛn˨˩ kwɑŋ˥", "syllable_count": 2, "sentences": [{"text": "每个人看世界的眼光都不一样。", "target_word": "眼光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用自己的眼光看这件事。", "target_word": "眼光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的眼光很简单，常看到大人忽略的地方。", "target_word": "眼光", "complexity_tier": "T3", "furigana": "yǎn guāng", "sentence_source": "generated"}, {"text": "换个眼光看问题，你会有新的想法。", "target_word": "眼光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的眼光和我们不同，所以意见也不同。", "target_word": "眼光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不要用小孩的眼光看大人的事。", "target_word": "眼光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在老人的眼光里，年轻人总是太着急。", "target_word": "眼光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "读了很多书以后，她的眼光变宽了。", "target_word": "眼光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈的眼光和我不一样，她喜欢旧东西。", "target_word": "眼光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从游客的眼光看，这个小城很美。", "target_word": "眼光", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "老眼光", "label": "复合"}, {"form": "新眼光", "label": "复合"}], "register": "中性", "sense_fingerprint": "一个人看事情、看问题时的想法和角度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a2dbba0-d718-455c-a394-e29e30cffffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95889, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "眼光", "is_correct": true, "explanation": "眼光（yǎn guāng）指看事情、看问题时的想法和角度，是正确答案。"}, {"text": "阳光", "is_correct": false, "explanation": "yáng guāng 与 yǎn guāng 的第一音节韵母和声调都不同（áng 与 ǎn），意思是太阳发出的光。"}, {"text": "验光", "is_correct": false, "explanation": "yàn（第四声）与 yǎn（第三声）声调不同，意思是检查视力、配眼镜。"}, {"text": "眼观", "is_correct": false, "explanation": "guān 与 guāng 韵尾不同（an 与 ang），意思是用眼睛看。"}, {"text": "眼眶", "is_correct": false, "explanation": "kuàng（第四声）与 guāng（第一声）声母和声调不同，意思是眼睛周围的框。"}, {"text": "远光", "is_correct": false, "explanation": "yuǎn 与 yǎn 多一个 u，意思是远处的光，也指汽车的远光灯。"}], "explanations": {"眼光": "眼光（yǎn guāng）指看事情、看问题时的想法和角度，是正确答案。", "阳光": "yáng guāng 与 yǎn guāng 的第一音节韵母和声调都不同（áng 与 ǎn），意思是太阳发出的光。", "验光": "yàn（第四声）与 yǎn（第三声）声调不同，意思是检查视力、配眼镜。", "眼观": "guān 与 guāng 韵尾不同（an 与 ang），意思是用眼睛看。", "眼眶": "kuàng（第四声）与 guāng（第一声）声母和声调不同，意思是眼睛周围的框。", "远光": "yuǎn 与 yǎn 多一个 u，意思是远处的光，也指汽车的远光灯。"}, "sentence_index": null, "correct_answer": "眼光"}, "level_3": {"options": [{"text": "眼光", "is_correct": true, "explanation": "眼光指看事情的想法和角度，与“每个人看世界的眼光都不一样”相符。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高指人的高矮，与“看世界的想法”无关。"}, {"text": "相貌", "is_correct": false, "explanation": "体貌：相貌指外表长相，与“看世界的想法”无关。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格指物品的货币价值，与“看世界的想法”无关。"}], "explanations": {"眼光": "眼光指看事情的想法和角度，与“每个人看世界的眼光都不一样”相符。", "身高": "语义：身高指人的高矮，与“看世界的想法”无关。", "相貌": "体貌：相貌指外表长相，与“看世界的想法”无关。", "价格": "语义：价格指物品的货币价值，与“看世界的想法”无关。"}, "sentence_index": 0, "correct_answer": "眼光"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "换个眼光看书，字就清楚多了。", "explanation": "这里应该用〈眼镜〉。眼光指看事情的想法，不指戴在眼睛上的镜片。"}, {"text": "他的眼光不好，要戴眼镜才能看清黑板。", "explanation": "这里应该用〈视力〉。眼光指看事情的想法，不指眼睛看清东西的能力，说视力好坏要用“视力”。"}, {"text": "换一颗眼光看问题，你会有新的想法。", "explanation": "量词错误：这里应该用〈种〉。“颗”用于圆粒状的东西，眼光是抽象的看法，应说“一种眼光”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98a057f9-f62d-4002-b351-272510835135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95889, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "眼光", "is_correct": true, "explanation": "眼光指看事情的想法和角度，“在老人的眼光里”指老人看待事情的角度。"}, {"text": "钱包", "is_correct": false, "explanation": "语义：钱包是装钱的东西，“年轻人太着急”不会出现在钱包里。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“在……里”后面要接地点或范围，“脚步”不能这样表示范围。"}, {"text": "行李", "is_correct": false, "explanation": "语义：行李是出门时装东西的箱包，不能用来表示看法或角度。"}], "explanations": {"眼光": "眼光指看事情的想法和角度，“在老人的眼光里”指老人看待事情的角度。", "钱包": "语义：钱包是装钱的东西，“年轻人太着急”不会出现在钱包里。", "脚步": "搭配：“在……里”后面要接地点或范围，“脚步”不能这样表示范围。", "行李": "语义：行李是出门时装东西的箱包，不能用来表示看法或角度。"}, "sentence_index": 6, "correct_answer": "眼光"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的眼光被风吹红了，揉了好久。", "explanation": "这里的“眼光”被当作眼睛来用，但它只指看事情的想法或角度，不指身体部位。"}, {"text": "奶奶把眼光包进了饺子里。", "explanation": "这里的“眼光”被当作食材来用，但它是抽象的想法或角度，不是可以包的东西。"}, {"text": "这张桌子是用眼光做的。", "explanation": "这里的“眼光”被当作材料来用，但它只指看事情的想法或角度，不能用来做东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98a057f9-f62d-4002-b351-272510835135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95889, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们应该试着用一把新的眼光看待这个问题。", "corrected_sentence": "我们应该试着用一种新的眼光看待这个问题。", "error_description": "量词错误：“眼光”是抽象的看法，应说“一种新的眼光”；“把”用于有柄的器具，不能用于“眼光”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98a057f9-f62d-4002-b351-272510835135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95889, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她很眼光，常常想到别人想不到的办法。", "corrected_sentence": "她很有眼光，常常想到别人想不到的办法。", "error_description": "“眼光”是名词，“很”后面要接“有”，应说“很有眼光”；漏掉“有”，句子不通顺。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98a057f9-f62d-4002-b351-272510835135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
