INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95890, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "观察判断事物的能力或看法。", "primary_collocate": null, "pronunciation": "yǎn guāng", "ipa": "jɛn˨˩ kwɑŋ˥", "syllable_count": 2, "sentences": [{"text": "他很有眼光，早就看出这家店会赚钱。", "target_word": "眼光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买房子要有长远的眼光。", "target_word": "眼光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她选衣服的眼光一直很好。", "target_word": "眼光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师用温和的眼光看待我的作品。", "target_word": "眼光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都佩服他的眼光，他推荐的车都很受欢迎。", "target_word": "眼光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位投资人的眼光很准，选的公司都成功了。", "target_word": "眼光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不能用老眼光看现在的年轻人。", "target_word": "眼光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是班里最有眼光的人，看问题总比别人深。", "target_word": "眼光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸的眼光比我好，这双鞋他一眼就选中了。", "target_word": "眼光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做生意不但要努力，还要有好眼光。", "target_word": "眼光", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "老眼光", "label": "复合"}, {"form": "新眼光", "label": "复合"}], "register": "中性", "sense_fingerprint": "观察判断事物的能力或看法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a2dbba0-d718-455c-a394-e29e30cffffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95890, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "眼光", "is_correct": true, "explanation": "眼光（yǎn guāng）指观察判断事物的能力或看法，是正确答案。"}, {"text": "阳光", "is_correct": false, "explanation": "yáng guāng 与 yǎn guāng 的第一音节韵母和声调都不同（áng 与 ǎn），意思是太阳发出的光。"}, {"text": "验光", "is_correct": false, "explanation": "yàn（第四声）与 yǎn（第三声）声调不同，意思是检查视力、配眼镜。"}, {"text": "眼观", "is_correct": false, "explanation": "guān 与 guāng 韵尾不同（an 与 ang），意思是用眼睛看。"}, {"text": "眼眶", "is_correct": false, "explanation": "kuàng（第四声）与 guāng（第一声）声母和声调不同，意思是眼睛周围的框。"}, {"text": "远光", "is_correct": false, "explanation": "yuǎn 与 yǎn 多一个 u，意思是远处的光，也指汽车的远光灯。"}], "explanations": {"眼光": "眼光（yǎn guāng）指观察判断事物的能力或看法，是正确答案。", "阳光": "yáng guāng 与 yǎn guāng 的第一音节韵母和声调都不同（áng 与 ǎn），意思是太阳发出的光。", "验光": "yàn（第四声）与 yǎn（第三声）声调不同，意思是检查视力、配眼镜。", "眼观": "guān 与 guāng 韵尾不同（an 与 ang），意思是用眼睛看。", "眼眶": "kuàng（第四声）与 guāng（第一声）声母和声调不同，意思是眼睛周围的框。", "远光": "yuǎn 与 yǎn 多一个 u，意思是远处的光，也指汽车的远光灯。"}, "sentence_index": null, "correct_answer": "眼光"}, "level_3": {"options": [{"text": "眼光", "is_correct": true, "explanation": "眼光指观察判断事物的能力，与“早就看出这家店会赚钱”相符。"}, {"text": "体力", "is_correct": false, "explanation": "语义：体力指身体的力气，与“看出店会赚钱”的判断无关。"}, {"text": "相貌", "is_correct": false, "explanation": "体貌：相貌指人的长相，不能用来表示判断能力。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：脾气指性情，与判断能力无关，“很有脾气”说不通。"}], "explanations": {"眼光": "眼光指观察判断事物的能力，与“早就看出这家店会赚钱”相符。", "体力": "语义：体力指身体的力气，与“看出店会赚钱”的判断无关。", "相貌": "体貌：相貌指人的长相，不能用来表示判断能力。", "脾气": "语义：脾气指性情，与判断能力无关，“很有脾气”说不通。"}, "sentence_index": 0, "correct_answer": "眼光"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的眼光很好，三米外的字都能看清。", "explanation": "这里应该用〈视力〉。眼光指判断事物的能力或看法，眼睛看清东西的能力要用视力。"}, {"text": "站在山顶，他的眼光被云雾挡住了，看不见城市。", "explanation": "这里应该用〈视线〉。眼光指判断事物的能力或看法，被云雾挡住的是视线，不是眼光。"}, {"text": "他有一条很准的眼光，买的股票都涨了。", "explanation": "量词错误：这里应该用〈种〉。“条”用于细长的东西，眼光是抽象的判断力，不能用“条”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98a057f9-f62d-4002-b351-272510835135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95890, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "眼光", "is_correct": true, "explanation": "眼光指判断事物的能力或看法，“用老眼光看年轻人”即用过时的看法看待人。"}, {"text": "耳朵", "is_correct": false, "explanation": "语义：“看”要用眼睛，耳朵是用来听的，不能“用耳朵看”。"}, {"text": "脚步", "is_correct": false, "explanation": "语义：脚步是走路时的动作，不能用来“看”年轻人。"}, {"text": "面容", "is_correct": false, "explanation": "体貌：面容指人的脸，是外貌，不能作为看人的方式。"}], "explanations": {"眼光": "眼光指判断事物的能力或看法，“用老眼光看年轻人”即用过时的看法看待人。", "耳朵": "语义：“看”要用眼睛，耳朵是用来听的，不能“用耳朵看”。", "脚步": "语义：脚步是走路时的动作，不能用来“看”年轻人。", "面容": "体貌：面容指人的脸，是外貌，不能作为看人的方式。"}, "sentence_index": 6, "correct_answer": "眼光"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的眼光被灰尘刺痛了，只好去医院。", "explanation": "这里的“眼光”被当作眼睛器官来用，但它指观察判断事物的能力或看法，不指眼球或其他身体部位。"}, {"text": "这盏台灯的眼光很亮，照得桌面一片白。", "explanation": "这里的“眼光”被当作光源来用，但它指观察判断事物的能力或看法，不指灯光。"}, {"text": "妈妈把眼光放进冰箱里保存了。", "explanation": "这里的“眼光”被当作可以保存的东西来用，但它是抽象的判断力或看法，不能放进冰箱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98a057f9-f62d-4002-b351-272510835135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95890, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她有一把很独特的眼光，总能挑出别人忽略的好东西。", "corrected_sentence": "她有一种很独特的眼光，总能挑出别人忽略的好东西。", "error_description": "量词错误：“眼光”是抽象的判断力，应说“一种眼光”；“把”用于有柄的器具，不能用于“眼光”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98a057f9-f62d-4002-b351-272510835135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95890, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她做事很眼光，总能抓住机会。", "corrected_sentence": "她做事很有眼光，总能抓住机会。", "error_description": "“眼光”是名词，“很”后面要接“有”，应说“很有眼光”；漏掉“有”，句子不通顺。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98a057f9-f62d-4002-b351-272510835135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
