INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95895, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98a057f9-f62d-4002-b351-272510835135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95895, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "管理站是负责看管一个地方的小站。", "primary_collocate": null, "pronunciation": "guǎn lǐ zhàn", "ipa": "kwan˨˩ li˨˩ ʈʂan˥˩", "syllable_count": 3, "sentences": [{"text": "山脚下有一个小小的管理站。", "target_word": "管理站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园的管理站就在大门旁边。", "target_word": "管理站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先去管理站问一下路。", "target_word": "管理站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "管理站的师傅每天都要上山看看。", "target_word": "管理站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湖边的管理站里住着一位老人。", "target_word": "管理站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游客在管理站买了票才能进山。", "target_word": "管理站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，我们躲进了森林管理站。", "target_word": "管理站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "管理站的门口挂着一个红灯笼。", "target_word": "管理站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在海边的管理站工作了十年。", "target_word": "管理站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把垃圾送到管理站去。", "target_word": "管理站", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "森林管理站", "label": "复合"}], "register": "中性", "sense_fingerprint": "设在山林、公园、湖边等地、负责看管的小站", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a2dbba0-d718-455c-a394-e29e30cffffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95895, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "管理站", "is_correct": true, "explanation": "管理站是设在山脚下、负责看管的小站，与“山脚下有一个小小的”相符。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机是通讯工具，“山脚下有一个小小的手机”说的不是一处地方。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲不是地点或建筑，不能放在山脚下。"}, {"text": "相貌", "is_correct": false, "explanation": "体貌：相貌指人的长相，不是可以放在山脚下的东西。"}], "explanations": {"管理站": "管理站是设在山脚下、负责看管的小站，与“山脚下有一个小小的”相符。", "手机": "语义：手机是通讯工具，“山脚下有一个小小的手机”说的不是一处地方。", "歌曲": "语义：歌曲不是地点或建筑，不能放在山脚下。", "相貌": "体貌：相貌指人的长相，不是可以放在山脚下的东西。"}, "sentence_index": 0, "correct_answer": "管理站"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在管理站等车，车还没来。", "explanation": "这里应该用〈车站〉。管理站是看管山林、公园的小站，不是等车的地方。"}, {"text": "他去管理站理了发，剪得很短。", "explanation": "这里应该用〈理发店〉。管理站是看管某处的小站，不提供理发，理发要去理发店。"}, {"text": "山上新装了一台管理站，游客可以在那里买票。", "explanation": "量词错误：这里应该用〈座〉。“台”用于机器、设备，管理站是建筑，应说“一座管理站”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98a057f9-f62d-4002-b351-272510835135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95895, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "管理站", "is_correct": true, "explanation": "管理站是躲雨的地方，“躲进了森林管理站”合乎句意。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字是称呼，不能躲进森林里。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是可以躲进去的地方，“躲进了森林颜色”说不通。"}, {"text": "面容", "is_correct": false, "explanation": "体貌：面容指人的脸，不是可以躲进去的地方。"}], "explanations": {"管理站": "管理站是躲雨的地方，“躲进了森林管理站”合乎句意。", "名字": "语义：名字是称呼，不能躲进森林里。", "颜色": "语义：颜色不是可以躲进去的地方，“躲进了森林颜色”说不通。", "面容": "体貌：面容指人的脸，不是可以躲进去的地方。"}, "sentence_index": 6, "correct_answer": "管理站"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们每天早上在管理站上课。", "explanation": "这里应该用〈学校〉。管理站是看管某处的小站，不是上课的地方，上课要去学校。"}, {"text": "我每天去管理站买菜。", "explanation": "这里应该用〈超市〉。管理站是看管某处的小站，不卖菜，买菜要去超市。"}, {"text": "每个月我都去管理站存钱。", "explanation": "这里应该用〈银行〉。管理站是看管某处的小站，不办理存取款，存钱要去银行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98a057f9-f62d-4002-b351-272510835135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95895, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "山谷里新建了一把管理站，游客可以在那里买票。", "corrected_sentence": "山谷里新建了一座管理站，游客可以在那里买票。", "error_description": "量词错误：“管理站”是建筑，应说“一座”；“把”用于有柄的器具，不能用于建筑。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98a057f9-f62d-4002-b351-272510835135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95895, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们每天都在一把管理站的门口集合。", "corrected_sentence": "我们每天都在一座管理站的门口集合。", "error_description": "量词错误：“管理站”是建筑，应说“一座”；“把”用于有柄的器具，不能用于建筑。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98a057f9-f62d-4002-b351-272510835135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
