INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95896, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "负责某项事务管理工作的基层机构。", "primary_collocate": null, "pronunciation": "guǎn lǐ zhàn", "ipa": "kwan˨˩ li˨˩ ʈʂan˥˩", "syllable_count": 3, "sentences": [{"text": "村里新建了水利管理站。", "target_word": "管理站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在街道的卫生管理站工作。", "target_word": "管理站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民到农业管理站学习新技术。", "target_word": "管理站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个管理站负责全镇的垃圾处理。", "target_word": "管理站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市场管理站每天检查食品安全。", "target_word": "管理站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我去社区管理站办了居住证。", "target_word": "管理站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "管理站的工作人员都很热情。", "target_word": "管理站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "县里有三个水电管理站。", "target_word": "管理站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把材料交给管理站。", "target_word": "管理站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "镇上的管理站每个月开一次会。", "target_word": "管理站", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "水利管理站", "label": "复合"}], "register": "中性", "sense_fingerprint": "负责某项事务管理工作的基层机构", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a2dbba0-d718-455c-a394-e29e30cffffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95896, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "管理站", "is_correct": true, "explanation": "管理站是负责某项事务管理的基层机构，“村里新建了水利管理站”合乎句意。"}, {"text": "花朵", "is_correct": false, "explanation": "语义：“水利”后面要接机构或设施，“花朵”与水利无关。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“水利颜色”不是可以新建的东西，与句意不符。"}, {"text": "相貌", "is_correct": false, "explanation": "体貌：相貌指人的长相，不能说“新建了水利相貌”。"}], "explanations": {"管理站": "管理站是负责某项事务管理的基层机构，“村里新建了水利管理站”合乎句意。", "花朵": "语义：“水利”后面要接机构或设施，“花朵”与水利无关。", "颜色": "语义：“水利颜色”不是可以新建的东西，与句意不符。", "相貌": "体貌：相貌指人的长相，不能说“新建了水利相貌”。"}, "sentence_index": 0, "correct_answer": "管理站"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在管理站等车，车还没来。", "explanation": "这里应该用〈车站〉。管理站是负责事务管理的机构，不是等车的地方。"}, {"text": "我每个星期六都去管理站打篮球。", "explanation": "这里应该用〈体育馆〉。管理站是负责事务管理的机构，不是运动场所，打篮球要去体育馆。"}, {"text": "妈妈昨天在管理站做了手术。", "explanation": "这里应该用〈医院〉。管理站是负责事务管理的机构，不做手术，做手术要去医院。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98a057f9-f62d-4002-b351-272510835135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95896, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "管理站", "is_correct": true, "explanation": "管理站是负责事务管理的基层机构，“管理站的工作人员”合乎句意。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：“歌曲的工作人员”说不通，歌曲不是机构。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是建筑的一部分，不能有“工作人员”。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高指人的高矮，不能说“身高的工作人员”。"}], "explanations": {"管理站": "管理站是负责事务管理的基层机构，“管理站的工作人员”合乎句意。", "歌曲": "语义：“歌曲的工作人员”说不通，歌曲不是机构。", "窗户": "语义：窗户是建筑的一部分，不能有“工作人员”。", "身高": "体貌：身高指人的高矮，不能说“身高的工作人员”。"}, "sentence_index": 6, "correct_answer": "管理站"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台管理站每个月开一次会，讨论全镇的事务。", "explanation": "量词错误：这里应该用〈个〉。“台”用于机器、设备，管理站是机构，不能用“台”。"}, {"text": "这把管理站每个月开一次会，讨论全镇的事务。", "explanation": "量词错误：这里应该用〈个〉。“把”用于有柄的器具，管理站是机构，不能用“把”。"}, {"text": "这颗管理站每个月开一次会，讨论全镇的事务。", "explanation": "量词错误：这里应该用〈个〉。“颗”用于圆粒状的东西，管理站是机构，不能用“颗”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98a057f9-f62d-4002-b351-272510835135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95896, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "县里新设了一把管理站，负责全县的垃圾回收。", "corrected_sentence": "县里新设了一个管理站，负责全县的垃圾回收。", "error_description": "量词错误：“管理站”是负责事务的机构，应说“一个”；“把”用于有柄的器具，不能用于机构。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98a057f9-f62d-4002-b351-272510835135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95896, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "镇上有两台水利管理站，分管不同的河段。", "corrected_sentence": "镇上有两个水利管理站，分管不同的河段。", "error_description": "量词错误：“管理站”是负责事务的机构，应说“两个”；“台”用于机器、设备，不能用于机构。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98a057f9-f62d-4002-b351-272510835135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
