INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95897, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "粮是人吃的米、面这些东西。", "primary_collocate": null, "pronunciation": "liáng", "ipa": "ljɑŋ˧˥", "syllable_count": 1, "sentences": [{"text": "家里的粮快吃完了。", "target_word": "粮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们买了很多粮回家。", "target_word": "粮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出门前，妈妈带够了粮。", "target_word": "粮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天到了，农民把粮放进仓库。", "target_word": "粮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里路远，大家背着粮走了三天。", "target_word": "粮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几年雨水好，村里多收了粮。", "target_word": "粮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥每个月都给老家寄钱和粮。", "target_word": "粮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们存点儿粮吧，下个月可能涨价。", "target_word": "粮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有粮，我们就没法过冬。", "target_word": "粮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把最后一点粮分给了邻居。", "target_word": "粮", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "粮食", "label": "复合"}, {"form": "粮仓", "label": "复合"}], "register": "中性", "sense_fingerprint": "人吃的米、面等主食原料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a2dbba0-d718-455c-a394-e29e30cffffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95897, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "粮", "is_correct": true, "explanation": "粮（liáng）指人吃的米、面等主食，是正确答案。"}, {"text": "量", "is_correct": false, "explanation": "liàng（第四声）与 liáng（第二声）声调不同，意思是数量。"}, {"text": "两", "is_correct": false, "explanation": "liǎng（第三声）与 liáng（第二声）声调不同，意思是二。"}, {"text": "连", "is_correct": false, "explanation": "lián 与 liáng 韵母不同（an/ang），意思是连接。"}, {"text": "娘", "is_correct": false, "explanation": "niáng 与 liáng 声母不同（n/l），意思是母亲。"}], "explanations": {"粮": "粮（liáng）指人吃的米、面等主食，是正确答案。", "量": "liàng（第四声）与 liáng（第二声）声调不同，意思是数量。", "两": "liǎng（第三声）与 liáng（第二声）声调不同，意思是二。", "连": "lián 与 liáng 韵母不同（an/ang），意思是连接。", "娘": "niáng 与 liáng 声母不同（n/l），意思是母亲。"}, "sentence_index": null, "correct_answer": "粮"}, "level_3": {"options": [{"text": "煤", "is_correct": false, "explanation": "语义：煤不是吃的东西，“家里的煤快吃完了”说不通。"}, {"text": "粮", "is_correct": true, "explanation": "粮是人吃的主食，与“快吃完了”搭配自然。"}, {"text": "纸", "is_correct": false, "explanation": "语义：纸不能吃，这里应说“用完”。"}, {"text": "钱", "is_correct": false, "explanation": "搭配：“吃完”不用于钱，应说“花完”。"}], "explanations": {"煤": "语义：煤不是吃的东西，“家里的煤快吃完了”说不通。", "粮": "粮是人吃的主食，与“快吃完了”搭配自然。", "纸": "语义：纸不能吃，这里应说“用完”。", "钱": "搭配：“吃完”不用于钱，应说“花完”。"}, "sentence_index": 0, "correct_answer": "粮"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一只粮。", "explanation": "这里应该用〈袋〉或〈斤〉。〈只〉用于动物或成对物品中的一个，不用于粮食。"}, {"text": "妈妈把粮擀成了皮。", "explanation": "这里应该用〈面〉。〈面〉是磨好的粉，可以擀成皮；粮是还没磨的谷物，不能擀。"}, {"text": "他每天早上都喝粮。", "explanation": "这里应该用〈牛奶〉。粮是固体谷物，不能喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98a057f9-f62d-4002-b351-272510835135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95897, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "粮", "is_correct": true, "explanation": "粮（liáng）指人吃的米、面等主食，是正确答案。"}, {"text": "亮", "is_correct": false, "explanation": "liàng（第四声）与 liáng（第二声）声调不同，意思是明亮。"}, {"text": "辆", "is_correct": false, "explanation": "liàng（第四声）与 liáng（第二声）声调不同，意思是车的量词。"}, {"text": "晾", "is_correct": false, "explanation": "liàng（第四声）与 liáng（第二声）声调不同，意思是晾晒。"}, {"text": "谅", "is_correct": false, "explanation": "liàng（第四声）与 liáng（第二声）声调不同，意思是原谅。"}], "explanations": {"粮": "粮（liáng）指人吃的米、面等主食，是正确答案。", "亮": "liàng（第四声）与 liáng（第二声）声调不同，意思是明亮。", "辆": "liàng（第四声）与 liáng（第二声）声调不同，意思是车的量词。", "晾": "liàng（第四声）与 liáng（第二声）声调不同，意思是晾晒。", "谅": "liàng（第四声）与 liáng（第二声）声调不同，意思是原谅。"}, "sentence_index": null, "correct_answer": "粮"}, "level_3": {"options": [{"text": "空气", "is_correct": false, "explanation": "语义：空气看不见、摸不着，无法寄送，“寄钱和空气”说不通。"}, {"text": "粮", "is_correct": true, "explanation": "粮是可以寄送的主食，与“寄钱和”搭配自然。"}, {"text": "掌声", "is_correct": false, "explanation": "语义：掌声听得见，但不能寄送，“寄钱和掌声”说不通。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：垃圾不是可以寄送的东西。"}], "explanations": {"空气": "语义：空气看不见、摸不着，无法寄送，“寄钱和空气”说不通。", "粮": "粮是可以寄送的主食，与“寄钱和”搭配自然。", "掌声": "语义：掌声听得见，但不能寄送，“寄钱和掌声”说不通。", "垃圾": "语义：垃圾不是可以寄送的东西。"}, "sentence_index": 6, "correct_answer": "粮"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈每个周末都做粮。", "explanation": "这里应该用〈蛋糕〉。〈做〉的对象是能做成的食品，粮是谷物，不能说“做粮”。"}, {"text": "工人正在修粮。", "explanation": "这里应该用〈机器〉。〈修〉的对象是机器、器具，粮是谷物，不能修。"}, {"text": "他每天晚上都穿粮。", "explanation": "这里应该用〈衣服〉。〈穿〉的对象是衣物，粮不能穿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98a057f9-f62d-4002-b351-272510835135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95897, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们买了一个粮。", "corrected_sentence": "我们买了一袋粮。", "error_description": "量词错误：粮要用〈袋〉或〈斤〉计量，不能用〈个〉。正确说法是“我们买了一袋粮”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98a057f9-f62d-4002-b351-272510835135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95897, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "农民用车拉了好几只粮去城里。", "corrected_sentence": "农民用车拉了好几袋粮去城里。", "error_description": "量词错误：粮要用〈袋〉计量，不能用〈只〉。正确说法是“好几袋粮”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98a057f9-f62d-4002-b351-272510835135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
