INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95899, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "纠正是别人做错了，你帮他改成对的。", "primary_collocate": null, "pronunciation": "jiū zhèng", "ipa": "tɕjou˥ ʈʂɤŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他读错了字，我马上纠正他。", "target_word": "纠正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学写错了名字，我帮他纠正。", "target_word": "纠正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈常纠正弟弟吃饭的习惯。", "target_word": "纠正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友的说法不对，我礼貌地纠正了他。", "target_word": "纠正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师没有批评他，只是纠正了他的错误。", "target_word": "纠正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把“的”写成了“地”，我帮他纠正。", "target_word": "纠正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子画错了颜色，爸爸耐心地纠正他。", "target_word": "纠正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你说错了，我得纠正你一下。", "target_word": "纠正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁说错了，别人都可以纠正。", "target_word": "纠正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外国朋友说错了汉语，我们轻轻地纠正他。", "target_word": "纠正", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "纠正了", "label": "体标"}, {"form": "纠正过", "label": "体标"}], "register": "中性", "sense_fingerprint": "别人做错或说错，你帮他改成对的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afcd0b75-9fed-4b31-9fb8-4f73e2bd4177') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95899, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "表扬", "is_correct": false, "explanation": "语义：读错字是应当改正的错误，“表扬”与语境相反"}, {"text": "纠正", "is_correct": true, "explanation": "纠正：别人读错字，我马上帮他改正，符合语境"}, {"text": "祝贺", "is_correct": false, "explanation": "语义：祝贺指值得庆贺的事，与读错字的语境不符"}, {"text": "点燃", "is_correct": false, "explanation": "搭配：“点燃”的对象是火、灯等，不能用于人"}], "explanations": {"表扬": "语义：读错字是应当改正的错误，“表扬”与语境相反", "纠正": "纠正：别人读错字，我马上帮他改正，符合语境", "祝贺": "语义：祝贺指值得庆贺的事，与读错字的语境不符", "点燃": "搭配：“点燃”的对象是火、灯等，不能用于人"}, "sentence_index": 0, "correct_answer": "纠正"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我纠正了他的勇气。", "explanation": "这里应该用〈夸奖〉。纠正用于改正错误，肯定别人的勇气要用夸奖"}, {"text": "老师纠正他一顿。", "explanation": "这里应该用〈批评〉。纠正指帮人改正错误，责备一顿要用批评"}, {"text": "妈妈纠正了我的生日。", "explanation": "这里应该用〈庆祝〉。生日没有错误，纠正不能用于生日，庆祝生日要用庆祝"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda09645-f95d-4b38-abea-00657f3ba78a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95899, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "训斥", "is_correct": false, "explanation": "语义：“耐心地”与“训斥”的态度相反，不符合语境"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：嘲笑是取笑，与耐心指导的语境相反"}, {"text": "驳斥", "is_correct": false, "explanation": "搭配：“驳斥”的对象是观点或言论，不能直接用于指导孩子的语境"}, {"text": "纠正", "is_correct": true, "explanation": "纠正：孩子画错颜色，爸爸耐心地帮他改正，符合语境"}], "explanations": {"训斥": "语义：“耐心地”与“训斥”的态度相反，不符合语境", "嘲笑": "语义：嘲笑是取笑，与耐心指导的语境相反", "驳斥": "搭配：“驳斥”的对象是观点或言论，不能直接用于指导孩子的语境", "纠正": "纠正：孩子画错颜色，爸爸耐心地帮他改正，符合语境"}, "sentence_index": 6, "correct_answer": "纠正"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "朋友考试失败了，我纠正了他。", "explanation": "这里应该用〈安慰〉。纠正用于改正错误，对失败的人表示关心要用安慰"}, {"text": "他帮了我，我纠正了他。", "explanation": "这里应该用〈感谢〉。纠正用于改正错误，对别人的帮助要用感谢"}, {"text": "他考上了大学，我纠正了他。", "explanation": "这里应该用〈祝贺〉。考上大学是好事，不是错误，应当用祝贺"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda09645-f95d-4b38-abea-00657f3ba78a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95899, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们要尽快纠正了这个错误。", "corrected_sentence": "我们要尽快纠正这个错误。", "error_description": "体标错误。动词后的“了”表示动作已完成，与表示打算的“要”不能直接搭配；去掉“了”，正确为“我们要尽快纠正这个错误”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda09645-f95d-4b38-abea-00657f3ba78a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95899, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "同学们要互相纠正了错误。", "corrected_sentence": "同学们要互相纠正错误。", "error_description": "体标错误。动词后的“了”表示动作已完成，与表示打算的“要”不能直接搭配；去掉“了”，正确为“同学们要互相纠正错误”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda09645-f95d-4b38-abea-00657f3ba78a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
