INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95904, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "味道鲜美的食品。", "primary_collocate": null, "pronunciation": "měi wèi", "ipa": "meɪ˨˩˦ weɪ˥˩", "syllable_count": 2, "sentences": [{"text": "这道山里的美味，只有春天才吃得到。", "target_word": "美味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边的小店里有很多新鲜的美味。", "target_word": "美味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们先别客气，尽情享受美味吧。", "target_word": "美味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他为客人准备了几样美味。", "target_word": "美味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种美味是用鱼和豆腐做成的。", "target_word": "美味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在北京，你可以吃到各地的美味。", "target_word": "美味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我最想念家乡的美味。", "target_word": "美味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她拿出自己做的美味给大家吃。", "target_word": "美味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一边看书，一边想着晚饭的美味。", "target_word": "美味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一生都在寻找世界上的美味。", "target_word": "美味", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一道美味", "label": "量词"}], "register": "中性", "sense_fingerprint": "味道鲜美的食品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5c48bcb-0943-4b4f-aaa1-4bc592e2985d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95904, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "美味", "is_correct": true, "explanation": "美味是味道鲜美的食品，才能“吃得到”。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能吃，与“吃得到”冲突。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能吃，与“只有春天才吃得到”冲突。"}, {"text": "河水", "is_correct": false, "explanation": "搭配：“吃”一般搭配食物，不说“吃河水”。"}], "explanations": {"美味": "美味是味道鲜美的食品，才能“吃得到”。", "石头": "语义：石头不能吃，与“吃得到”冲突。", "天气": "语义：天气不能吃，与“只有春天才吃得到”冲突。", "河水": "搭配：“吃”一般搭配食物，不说“吃河水”。"}, "sentence_index": 0, "correct_answer": "美味"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这片风景很美味。", "explanation": "这里应该用〈美丽〉。美味只指食物，形容风景要用美丽。"}, {"text": "他买了一张美味。", "explanation": "这里应该用〈道〉。美味是食品，“张”用于纸、票等平面的东西。"}, {"text": "这首歌很美味。", "explanation": "这里应该用〈动听〉。美味指食物好吃，歌曲要用动听。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4486f04b-f2e3-49b9-a129-c8b8eb61b3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95904, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "美味", "is_correct": true, "explanation": "美味指家乡的食物，是人会想念的东西。"}, {"text": "地震", "is_correct": false, "explanation": "语义：“想念”的对象应是人、物或味道，地震不是可以想念的东西。"}, {"text": "税收", "is_correct": false, "explanation": "语义：税收是一种制度，不是可以想念的东西。"}, {"text": "考试", "is_correct": false, "explanation": "搭配：“想念”一般不用于“考试”，这里说不通。"}], "explanations": {"美味": "美味指家乡的食物，是人会想念的东西。", "地震": "语义：“想念”的对象应是人、物或味道，地震不是可以想念的东西。", "税收": "语义：税收是一种制度，不是可以想念的东西。", "考试": "搭配：“想念”一般不用于“考试”，这里说不通。"}, "sentence_index": 6, "correct_answer": "美味"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把椅子很美味。", "explanation": "这里应该用〈舒服〉。美味只指食物好吃，椅子要用舒服。"}, {"text": "那位姑娘很美味。", "explanation": "这里应该用〈漂亮〉。美味不能用来形容人的外貌。"}, {"text": "今天的天气很美味。", "explanation": "这里应该用〈晴朗〉。美味只指食物，不能形容天气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4486f04b-f2e3-49b9-a129-c8b8eb61b3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95904, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只美味要用新鲜的鱼来做。", "corrected_sentence": "这道美味要用新鲜的鱼来做。", "error_description": "“美味”指食品，计量用“道”，“这只美味”应改为“这道美味”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4486f04b-f2e3-49b9-a129-c8b8eb61b3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95904, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她给我端来一只美味，我很感动。", "corrected_sentence": "她给我端来一道美味，我很感动。", "error_description": "“美味”指菜肴，计量用“道”；“只”用于动物等，不能用于菜肴，应为“一道美味”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4486f04b-f2e3-49b9-a129-c8b8eb61b3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
