INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95911, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "舒适是身体觉得很舒服，很轻松。", "primary_collocate": null, "pronunciation": "shū shì", "ipa": "ʂu˥ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "泡了热水澡，我全身都很舒适。", "target_word": "舒适", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡了一个好觉，他觉得身体很舒适。", "target_word": "舒适", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "按摩以后，我整个人都很舒适。", "target_word": "舒适", "complexity_tier": "T3", "furigana": "àn mó yǐ hòu, wǒ zhěng gè rén dōu hěn shū shì.", "sentence_source": "generated"}, {"text": "躺在草地上，我觉得非常舒适。", "target_word": "舒适", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃了药，她躺下后觉得很舒适。", "target_word": "舒适", "complexity_tier": "T3", "furigana": "chī le yào, tā tǎng xià hòu jué de hěn shū shì.", "sentence_source": "generated"}, {"text": "这个枕头让我的脖子很舒适。", "target_word": "舒适", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "走了很远的路，坐下来休息真舒适。", "target_word": "舒适", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗完澡，我感到身体轻松舒适。", "target_word": "舒适", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "喝了一杯热茶，身体暖和了，很舒适。", "target_word": "舒适", "complexity_tier": "T3", "furigana": "hē le yì bēi rè chá, shēn tǐ nuǎn huo le, hěn shū shì.", "sentence_source": "generated"}, {"text": "风很轻，我觉得身上很舒适。", "target_word": "舒适", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "舒适度", "label": "复合"}], "register": "中性", "sense_fingerprint": "人的身体感到舒服轻松", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a2dbba0-d718-455c-a394-e29e30cffffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95911, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "舒适", "is_correct": true, "explanation": "舒适（shū shì）是正确答案。"}, {"text": "失事", "is_correct": false, "explanation": "shī 与 shū 韵母不同（i/u），意思是出事故。"}, {"text": "疏失", "is_correct": false, "explanation": "第二个音节 shī（第一声）与 shì（第四声）声调不同，意思是疏忽失误。"}, {"text": "蔬食", "is_correct": false, "explanation": "第二个音节 shí（第二声）与 shì（第四声）声调不同，意思是素食。"}], "explanations": {"舒适": "舒适（shū shì）是正确答案。", "失事": "shī 与 shū 韵母不同（i/u），意思是出事故。", "疏失": "第二个音节 shī（第一声）与 shì（第四声）声调不同，意思是疏忽失误。", "蔬食": "第二个音节 shí（第二声）与 shì（第四声）声调不同，意思是素食。"}, "sentence_index": null, "correct_answer": "舒适"}, "level_3": {"options": [{"text": "舒适", "is_correct": true, "explanation": "舒适说身体的轻松感，与“全身都很”搭配自然。"}, {"text": "冷静", "is_correct": false, "explanation": "语义：“冷静”说人的情绪，不用来说身体的感受。"}, {"text": "美丽", "is_correct": false, "explanation": "体貌：“美丽”说外貌，不说身体的感受。"}, {"text": "严格", "is_correct": false, "explanation": "语义：“严格”说对事情的要求，不说身体的感受。"}], "explanations": {"舒适": "舒适说身体的轻松感，与“全身都很”搭配自然。", "冷静": "语义：“冷静”说人的情绪，不用来说身体的感受。", "美丽": "体貌：“美丽”说外貌，不说身体的感受。", "严格": "语义：“严格”说对事情的要求，不说身体的感受。"}, "sentence_index": 0, "correct_answer": "舒适"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的头很疼，觉得很舒适。", "explanation": "这里应该用〈难受〉。〈舒适〉表示身体轻松，不用于疼痛。"}, {"text": "我走了一天路，脚很酸，觉得很舒适。", "explanation": "这里应该用〈累〉。〈舒适〉不用于脚酸的感受。"}, {"text": "吃了大餐，肚子很胀，我觉得很舒适。", "explanation": "这里应该用〈难受〉。胀的感觉不是舒适，〈舒适〉不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98a057f9-f62d-4002-b351-272510835135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95911, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "饿", "is_correct": false, "explanation": "语义：“饿”是饥饿的感觉，不说休息真饿。"}, {"text": "舒适", "is_correct": true, "explanation": "舒适说身体的轻松感，与“坐下来休息真”搭配自然。"}, {"text": "紧张", "is_correct": false, "explanation": "语义：“紧张”是心理状态，不说休息紧张。"}, {"text": "清楚", "is_correct": false, "explanation": "搭配：“清楚”说看、听或想得明白，不说休息清楚。"}], "explanations": {"饿": "语义：“饿”是饥饿的感觉，不说休息真饿。", "舒适": "舒适说身体的轻松感，与“坐下来休息真”搭配自然。", "紧张": "语义：“紧张”是心理状态，不说休息紧张。", "清楚": "搭配：“清楚”说看、听或想得明白，不说休息清楚。"}, "sentence_index": 6, "correct_answer": "舒适"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的手指冻得发麻，觉得很舒适。", "explanation": "这里应该用〈难受〉。发麻、冻得不舒服，不能说舒适。"}, {"text": "他的嗓子发炎了，觉得很舒适。", "explanation": "这里应该用〈难受〉。嗓子发炎时要说难受，不说舒适。"}, {"text": "这个伤口流血了，我觉得很舒适。", "explanation": "这里应该用〈疼〉。受伤时身体的感觉是疼，不是舒适。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98a057f9-f62d-4002-b351-272510835135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95911, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我躺在床上，觉得身体很最舒适。", "corrected_sentence": "我躺在床上，觉得身体最舒适。", "error_description": "程度副词重复：“很”和“最”不能同时修饰同一个形容词，应说“最舒适”，不说“很最舒适”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98a057f9-f62d-4002-b351-272510835135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95911, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我找了一个舒适地姿势躺下。", "corrected_sentence": "我找了一个舒适的姿势躺下。", "error_description": "“地”用错：修饰名词要用“的”，应说“舒适的姿势”，不说“舒适地姿势”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98a057f9-f62d-4002-b351-272510835135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
