INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95912, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "安适，舒服。", "primary_collocate": null, "pronunciation": "shū shì", "ipa": "ʂu˥ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "这个房间很大，住起来很舒适。", "target_word": "舒适", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张沙发又大又软，坐着很舒适。", "target_word": "舒适", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酒店的床很舒适，我睡得很好。", "target_word": "舒适", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这双鞋不贵，但是穿着很舒适。", "target_word": "舒适", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在乡下过着舒适的生活。", "target_word": "舒适", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想买一把舒适的椅子。", "target_word": "舒适", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆车的座位非常舒适，坐一天也不累。", "target_word": "舒适", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家酒店环境舒适，价格也不高。", "target_word": "舒适", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天开了空调，教室里很舒适。", "target_word": "舒适", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们住的房子不大，但是很干净舒适。", "target_word": "舒适", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "舒适度", "label": "复合"}, {"form": "舒适区", "label": "复合"}], "register": "中性", "sense_fingerprint": "环境、物品或生活条件让人安适舒服", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a2dbba0-d718-455c-a394-e29e30cffffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95912, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "舒适", "is_correct": true, "explanation": "舒适（shū shì）是正确答案。"}, {"text": "失事", "is_correct": false, "explanation": "shī 与 shū 韵母不同（i/u），意思是出事故。"}, {"text": "疏失", "is_correct": false, "explanation": "第二个音节 shī（第一声）与 shì（第四声）声调不同，意思是疏忽失误。"}, {"text": "蔬食", "is_correct": false, "explanation": "第二个音节 shí（第二声）与 shì（第四声）声调不同，意思是素食。"}], "explanations": {"舒适": "舒适（shū shì）是正确答案。", "失事": "shī 与 shū 韵母不同（i/u），意思是出事故。", "疏失": "第二个音节 shī（第一声）与 shì（第四声）声调不同，意思是疏忽失误。", "蔬食": "第二个音节 shí（第二声）与 shì（第四声）声调不同，意思是素食。"}, "sentence_index": null, "correct_answer": "舒适"}, "level_3": {"options": [{"text": "严肃", "is_correct": false, "explanation": "语义：“严肃”形容人的态度，不能说房间住起来严肃。"}, {"text": "舒适", "is_correct": true, "explanation": "舒适形容居住环境让人舒服，与“住起来”搭配自然。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：“聪明”形容人的智力，房间不能说聪明。"}, {"text": "漂亮", "is_correct": false, "explanation": "体貌：“漂亮”说外观，这里说的是居住的感受。"}], "explanations": {"严肃": "语义：“严肃”形容人的态度，不能说房间住起来严肃。", "舒适": "舒适形容居住环境让人舒服，与“住起来”搭配自然。", "聪明": "语义：“聪明”形容人的智力，房间不能说聪明。", "漂亮": "体貌：“漂亮”说外观，这里说的是居住的感受。"}, "sentence_index": 0, "correct_answer": "舒适"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家饭馆的菜很舒适，但是价格有点高。", "explanation": "这里应该用〈好吃〉。〈舒适〉说环境或物品的感受，不用来形容菜的味道。"}, {"text": "这个地方的交通很舒适，去哪儿都方便。", "explanation": "这里应该用〈便利〉。〈舒适〉形容环境、物品或座位让人身体舒服，不用来说交通；说交通方便要用〈便利〉。"}, {"text": "这幅画很舒适，挂在客厅里很好看。", "explanation": "这里应该用〈漂亮〉。〈舒适〉形容环境或座位等让人身体舒服，不用来形容画的外观；说画好看要用〈漂亮〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98a057f9-f62d-4002-b351-272510835135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95912, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "活泼", "is_correct": false, "explanation": "语义：座位不能说活泼，这里说的是座位的舒适感。"}, {"text": "舒适", "is_correct": true, "explanation": "舒适说座位让人舒服，与“非常……坐一天也不累”一致。"}, {"text": "生气", "is_correct": false, "explanation": "语义：座位不会生气。"}, {"text": "清晰", "is_correct": false, "explanation": "搭配：“清晰”说文字、声音，不说座位。"}], "explanations": {"活泼": "语义：座位不能说活泼，这里说的是座位的舒适感。", "舒适": "舒适说座位让人舒服，与“非常……坐一天也不累”一致。", "生气": "语义：座位不会生气。", "清晰": "搭配：“清晰”说文字、声音，不说座位。"}, "sentence_index": 6, "correct_answer": "舒适"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个车站人很多，十分舒适。", "explanation": "这里应该用〈拥挤〉。人多时不能说舒适，要说拥挤。"}, {"text": "这块布的颜色很舒适，做成衣服很好看。", "explanation": "这里应该用〈鲜艳〉。〈舒适〉形容身体或环境带来的舒服感，不用来形容布料颜色；说颜色醒目要用〈鲜艳〉。"}, {"text": "这间屋子很吵，住起来很舒适。", "explanation": "这里应该用〈安静〉。〈吵〉与〈舒适〉的意思矛盾，这里说房间吵却舒适，不合常理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98a057f9-f62d-4002-b351-272510835135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95912, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家酒店的房间很最舒适，价格也不高。", "corrected_sentence": "这家酒店的房间最舒适，价格也不高。", "error_description": "程度副词重复：“很”和“最”都表示程度，不能同时用，应说“最舒适”，不说“很最舒适”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98a057f9-f62d-4002-b351-272510835135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95912, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们在公园里找到了一把舒适地椅子。", "corrected_sentence": "我们在公园里找到了一把舒适的椅子。", "error_description": "“地”用错：修饰名词要用“的”，“地”只用于修饰动词，应说“舒适的椅子”，不说“舒适地椅子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98a057f9-f62d-4002-b351-272510835135') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
