INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95914, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "到处寻找并聚集起来。", "primary_collocate": null, "pronunciation": "sōu jí", "ipa": "sou˥ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "记者四处搜集新闻材料。", "target_word": "搜集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想搜集一些关于北京的资料。", "target_word": "搜集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们正在搜集大家的建议。", "target_word": "搜集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子喜欢在海边搜集漂亮的贝壳。", "target_word": "搜集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生先搜集病人的情况，再给他治病。", "target_word": "搜集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校搜集了不少学生的作品。", "target_word": "搜集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她搜集过很多中国民歌。", "target_word": "搜集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了写报告，他搜集了很多数据。", "target_word": "搜集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你帮我搜集一下这方面的消息。", "target_word": "搜集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥搜集着各种汽车模型。", "target_word": "搜集", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "搜集了", "label": "体标（了）"}, {"form": "搜集过", "label": "体标（过）"}, {"form": "搜集着", "label": "体标（着）"}, {"form": "搜集搜集", "label": "重叠"}], "register": "中性", "sense_fingerprint": "四处寻找并聚集在一起", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afcd0b75-9fed-4b31-9fb8-4f73e2bd4177') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_versio