INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95914, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "采访", "is_correct": false, "explanation": "搭配：“采访”的对象是人，不能以“新闻材料”为宾语"}, {"text": "烹饪", "is_correct": false, "explanation": "语义：烹饪是做饭，与新闻材料无关"}, {"text": "修建", "is_correct": false, "explanation": "搭配：“修建”的对象是建筑、道路等，不能用于新闻材料"}, {"text": "搜集", "is_correct": true, "explanation": "搜集：记者四处收集新闻材料，符合语境"}], "explanations": {"采访": "搭配：“采访”的对象是人，不能以“新闻材料”为宾语", "烹饪": "语义：烹饪是做饭，与新闻材料无关", "修建": "搭配：“修建”的对象是建筑、道路等，不能用于新闻材料", "搜集": "搜集：记者四处收集新闻材料，符合语境"}, "sentence_index": 0, "correct_answer": "搜集"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "消防员搜集了被困的人。", "explanation": "这里应该用〈抢救〉。搜集用于物品或资料，救援被困的人要用抢救"}, {"text": "老师搜集了全班同学。", "explanation": "这里应该用〈召集〉。搜集用于物品或资料，把人聚到一起要用召集"}, {"text": "他搜集了生病的母亲。", "explanation": "这里应该用〈照顾〉。搜集用于物品或资料，照料生病的亲人要用照顾"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda09645-f95d-4b38-abea-00657f3ba78a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95914, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能以民歌为宾语"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象是衣物、食物等，不能用于民歌"}, {"text": "拆除", "is_correct": false, "explanation": "语义：拆除指拆掉建筑，与民歌无关"}, {"text": "搜集", "is_correct": true, "explanation": "搜集：她收集过很多中国民歌，符合语境"}], "explanations": {"吃": "搭配：“吃”不能以民歌为宾语", "洗": "搭配：“洗”的对象是衣物、食物等，不能用于民歌", "拆除": "语义：拆除指拆掉建筑，与民歌无关", "搜集": "搜集：她收集过很多中国民歌，符合语境"}, "sentence_index": 6, "correct_answer": "搜集"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工程师搜集着一座大桥。", "explanation": "这里应该用〈设计〉。搜集用于物品或资料，设计大桥要用设计"}, {"text": "司机搜集着一条马路。", "explanation": "这里应该用〈修建〉。搜集用于物品或资料，修一条马路要用修建"}, {"text": "她搜集着房间。", "explanation": "这里应该用〈装饰〉。搜集不能用于房间，布置房间要用装饰"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda09645-f95d-4b38-abea-00657f3ba78a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95914, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她一直搜集着了优惠券。", "corrected_sentence": "她一直搜集着优惠券。", "error_description": "体标错误。“搜集着”表示持续，后面不能再加表示完成的“了”；去掉“了”，正确为“她一直搜集着优惠券”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda09645-f95d-4b38-abea-00657f3ba78a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95914, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把所有资料都搜集了齐。", "corrected_sentence": "他把所有资料都搜集齐了。", "error_description": "补语位置错误。结果补语“齐”应紧跟动词，放在“了”之前。正确为“搜集齐了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda09645-f95d-4b38-abea-00657f3ba78a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
