INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95915, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "制造业是用机器和工人把东西做出来的行业。", "primary_collocate": null, "pronunciation": "zhì zào yè", "ipa": "ʈʂɻ̩˥˩ tsɑʊ̯˥˩ jɛ˥˩", "syllable_count": 3, "sentences": [{"text": "这个城市的制造业很发达。", "target_word": "制造业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在制造业工作了十年。", "target_word": "制造业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "制造业需要很多工人和机器。", "target_word": "制造业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国的制造业发展得很快。", "target_word": "制造业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂属于制造业。", "target_word": "制造业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在制造业也用机器人干活。", "target_word": "制造业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "制造业的工人每天都很忙。", "target_word": "制造业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多年轻人不想进制造业。", "target_word": "制造业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们公司想把制造业转移到南方。", "target_word": "制造业", "complexity_tier": "T3", "furigana": "zhì zào yè", "sentence_source": "generated"}, {"text": "制造业让这个小镇有了工作。", "target_word": "制造业", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "製造業", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用机器和工人生产东西的行业", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd12015e2-7c16-4cde-a171-47414d24e165') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95915, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "制造业", "is_correct": true, "explanation": "正确。制造业是城市里的行业，可以说「很发达」。"}, {"text": "人口", "is_correct": false, "explanation": "搭配：「发达」形容经济或行业，不能用来形容人口。"}, {"text": "历史", "is_correct": false, "explanation": "语义：历史是过去的事情，不能说「很发达」。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气指气候状况，不是可以「发达」的事物。"}], "explanations": {"制造业": "正确。制造业是城市里的行业，可以说「很发达」。", "人口": "搭配：「发达」形容经济或行业，不能用来形容人口。", "历史": "语义：历史是过去的事情，不能说「很发达」。", "天气": "语义：天气指气候状况，不是可以「发达」的事物。"}, "sentence_index": 0, "correct_answer": "制造业"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家制造业规模很大，有三千名员工。", "explanation": "这里应该用〈企业〉。制造业指整个行业，不能用「这家」指某一家企业的规模和员工数。"}, {"text": "他下班后去制造业吃饭。", "explanation": "这里应该用〈餐厅〉。制造业是行业，不是地方，不能用「去」指向它。"}, {"text": "他爸爸是一名制造业，每天在车间干活。", "explanation": "这里应该用〈工人〉。制造业是行业，不指人，说人要用「工人」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4be6a56-6de3-4f2a-8abf-94e8205a5896') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95915, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "制造业", "is_correct": true, "explanation": "正确。工人是制造业的人，每天都很忙，句子成立。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮不是有工人的单位，「月亮的工人」说不通。"}, {"text": "春天", "is_correct": false, "explanation": "语义：春天是季节，不会有工人。"}, {"text": "笑话", "is_correct": false, "explanation": "搭配：「笑话」不能与「工人」构成「……的工人」这样的修饰关系。"}], "explanations": {"制造业": "正确。工人是制造业的人，每天都很忙，句子成立。", "月亮": "语义：月亮不是有工人的单位，「月亮的工人」说不通。", "春天": "语义：春天是季节，不会有工人。", "笑话": "搭配：「笑话」不能与「工人」构成「……的工人」这样的修饰关系。"}, "sentence_index": 6, "correct_answer": "制造业"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家制造业每天要给员工发工资。", "explanation": "这里应该用〈工厂〉。制造业指行业，不能指具体一家工厂，也不能直接给员工发工资。"}, {"text": "这家制造业每天接待很多病人。", "explanation": "这里应该用〈医院〉。制造业是行业，不能接待病人。"}, {"text": "他早上吃了制造业。", "explanation": "这里应该用〈食物〉。制造业是行业，不能被吃，「吃」要接食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4be6a56-6de3-4f2a-8abf-94e8205a5896') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95915, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我哥哥制造业工作，已经五年了。", "corrected_sentence": "我哥哥在制造业工作，已经五年了。", "error_description": "错误形式：「制造业工作」缺少介词「在」。正确形式：「在制造业工作」。说在某个行业里工作时，要用「在」引出行业。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4be6a56-6de3-4f2a-8abf-94e8205a5896') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95915, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工厂把制造业搬。", "corrected_sentence": "工厂把制造业搬到了南方。", "error_description": "错误形式：「把制造业搬」动词后缺少补语或「了」。正确形式：「把制造业搬到了南方」。「把」字句中的单音节动词后必须带补语或「了」等成分，动作才算说完整。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4be6a56-6de3-4f2a-8abf-94e8205a5896') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
