INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95924, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "宋元时期说书艺人讲故事所用的底本，后来也指白话短篇小说。", "primary_collocate": null, "pronunciation": "huà běn", "ipa": "xwa˥˩ pən˨˩˦", "syllable_count": 2, "sentences": [{"text": "话本是宋元时期的白话小说。", "target_word": "话本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宋元话本的语言很接近口语。", "target_word": "话本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了宋代的话本。", "target_word": "话本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多话本故事后来变成了戏曲。", "target_word": "话本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇话本写的是一个爱情故事。", "target_word": "话本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在课上读过一篇宋代话本。", "target_word": "话本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "话本的故事常常很短，也很生动。", "target_word": "话本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明代的作家也喜欢写话本。", "target_word": "话本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究古代小说，不能不看话本。", "target_word": "话本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "话本里的人物说话像平时聊天一样。", "target_word": "话本", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一篇话本", "label": "量词"}, {"form": "宋元话本", "label": "复合"}, {"form": "話本", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "话本：宋元说书底本，后指白话短篇小说", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd34cd94a-28b4-4837-b0b6-593d7d226e00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95924, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "话本", "is_correct": true, "explanation": "“话本”指宋元时期的白话小说，与句子的语境相符，是正确答案。"}, {"text": "诗词", "is_correct": false, "explanation": "语义：“诗词”是韵文，不是白话小说。"}, {"text": "戏曲", "is_correct": false, "explanation": "语义：“戏曲”是戏剧，不是小说。"}, {"text": "文言文", "is_correct": false, "explanation": "语域：“文言文”是古代书面语，与“白话”的语域相反。"}], "explanations": {"话本": "“话本”指宋元时期的白话小说，与句子的语境相符，是正确答案。", "诗词": "语义：“诗词”是韵文，不是白话小说。", "戏曲": "语义：“戏曲”是戏剧，不是小说。", "文言文": "语域：“文言文”是古代书面语，与“白话”的语域相反。"}, "sentence_index": 0, "correct_answer": "话本"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我读过一位宋代话本。", "explanation": "这里应该用〈篇〉。话本是篇章类作品，量词要用“篇”；“位”只用于人。"}, {"text": "演员每天背诵话本，记住台词。", "explanation": "这里应该用〈剧本〉。话本是说书底本或白话小说，演员记台词要用剧本。"}, {"text": "妈妈用话本擀饺子皮。", "explanation": "这里应该用〈擀面杖〉。话本是书，不能用来擀饺子皮；擀饺子皮要用〈擀面杖〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4126d464-5865-4126-bfc4-864583ec3dfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95924, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "话本", "is_correct": true, "explanation": "“话本”的故事常常很短，也很生动，与句子的语境相符，是正确答案。"}, {"text": "论文", "is_correct": false, "explanation": "语义：“论文”是学术写作，一般不以故事短和生动为特点。"}, {"text": "说明书", "is_correct": false, "explanation": "语义：“说明书”是说明用途的文字，没有生动的故事。"}, {"text": "公文", "is_correct": false, "explanation": "语域：“公文”是正式的行政文书，与“生动”的故事语域不符。"}], "explanations": {"话本": "“话本”的故事常常很短，也很生动，与句子的语境相符，是正确答案。", "论文": "语义：“论文”是学术写作，一般不以故事短和生动为特点。", "说明书": "语义：“说明书”是说明用途的文字，没有生动的故事。", "公文": "语域：“公文”是正式的行政文书，与“生动”的故事语域不符。"}, "sentence_index": 6, "correct_answer": "话本"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我看着话本找路。", "explanation": "这里应该用〈地图〉。话本是书面故事，不能用来找路。"}, {"text": "我用话本算账。", "explanation": "这里应该用〈计算器〉。话本是书，不能用来计算。"}, {"text": "我用话本做了一碗汤。", "explanation": "这里应该用〈食材〉。话本是书，不能当食材做汤；做汤要用〈食材〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4126d464-5865-4126-bfc4-864583ec3dfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95924, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我读过一首明代话本。", "corrected_sentence": "我读过一篇明代话本。", "error_description": "量词错误：话本是篇章类作品，应用量词“篇”，“首”多用于诗词和歌曲。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4126d464-5865-4126-bfc4-864583ec3dfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95924, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "宋代的书商也喜欢卖一只话本。", "corrected_sentence": "宋代的书商也喜欢卖一篇话本。", "error_description": "量词错误：话本是篇章类作品，应用量词“篇”；“只”多用于动物，不能用于书籍。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4126d464-5865-4126-bfc4-864583ec3dfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
