INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95926, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把已经发表过的文章从一处刊载到另一处。", "primary_collocate": null, "pronunciation": "zhuǎn zǎi", "ipa": "ʈʂwan˨˩ tsai˨˩", "syllable_count": 2, "sentences": [{"text": "这家杂志转载了报纸上的长篇文章。", "target_word": "转载", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇报道先在报纸发表，后来杂志转载了。", "target_word": "转载", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "编辑决定转载去年发表的那篇文章。", "target_word": "转载", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本杂志常常转载国外的好文章。", "target_word": "转载", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网站转载了新闻，还写上了出处。", "target_word": "转载", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那首诗发表后，几家报纸转载过。", "target_word": "转载", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的文章发表以后，很多报纸转载了。", "target_word": "转载", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "转载时要写清楚文章原来发表的地方。", "target_word": "转载", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末版转载着一篇旧文章。", "target_word": "转载", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "编辑把这篇报道转载到了第二版。", "target_word": "转载", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "转载了", "label": "了体标"}, {"form": "转载着", "label": "着体标"}, {"form": "转载过", "label": "过体标"}], "register": "中性", "sense_fingerprint": "把已发表的文章从一处刊载到另一处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d8db740-58a4-47c4-9227-9e17bdaf1786') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95926, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "转载", "is_correct": true, "explanation": "转载：把报纸上的长篇文章刊登到杂志上，与“杂志”和“报纸上的长篇文章”的语境相符。"}, {"text": "播放", "is_correct": false, "explanation": "语义：“播放”用于音像节目，报纸文章不能播放。"}, {"text": "收听", "is_correct": false, "explanation": "语义：“收听”用于广播等声音内容，文章不能收听。"}, {"text": "戴", "is_correct": false, "explanation": "搭配：“戴”只能接帽子、眼镜等饰物，不能接“长篇文章”。"}], "explanations": {"转载": "转载：把报纸上的长篇文章刊登到杂志上，与“杂志”和“报纸上的长篇文章”的语境相符。", "播放": "语义：“播放”用于音像节目，报纸文章不能播放。", "收听": "语义：“收听”用于广播等声音内容，文章不能收听。", "戴": "搭配：“戴”只能接帽子、眼镜等饰物，不能接“长篇文章”。"}, "sentence_index": 0, "correct_answer": "转载"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他刚写完小说，就把它转载到了杂志上。", "explanation": "这里应该用〈投稿〉。转载的内容必须是已经发表过的文章，刚写完、还没发表的稿子要用〈投稿〉。"}, {"text": "他把这本书转载成了中文。", "explanation": "这里应该用〈翻译〉。转载是把已发表的文章刊登到另一处，改变语言要用〈翻译〉。"}, {"text": "他把还没发表过的稿子转载到了杂志社。", "explanation": "这里应该用〈寄〉。转载的内容必须已经发表，还没发表的稿件寄给杂志社要用〈寄〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8600dcf-f52c-42c9-a04a-914f560f349c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95926, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "转载", "is_correct": true, "explanation": "转载：文章发表后，报纸把它刊载到自己的版面上，语境通顺。"}, {"text": "播放", "is_correct": false, "explanation": "搭配：“播放”用于音视频节目，报纸不能播放，与“文章发表”的语境冲突。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：报纸不会睡觉，句子语义不通。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：报纸不能结婚，与语境明显冲突。"}], "explanations": {"转载": "转载：文章发表后，报纸把它刊载到自己的版面上，语境通顺。", "播放": "搭配：“播放”用于音视频节目，报纸不能播放，与“文章发表”的语境冲突。", "睡觉": "语义：报纸不会睡觉，句子语义不通。", "结婚": "语义：报纸不能结婚，与语境明显冲突。"}, "sentence_index": 6, "correct_answer": "转载"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把这条消息转载给了同学。", "explanation": "这里应该用〈转发〉。转载指把整篇文章刊登到别处，把消息传给别人要用〈转发〉。"}, {"text": "我把生词转载在笔记本上。", "explanation": "这里应该用〈摘抄〉。转载指把文章刊登在媒体上，把生词抄进笔记本要用〈摘抄〉。"}, {"text": "电台转载了那场演唱会。", "explanation": "这里应该用〈转播〉。转载指文字作品刊登到别处，演唱会的现场传送要用〈转播〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8600dcf-f52c-42c9-a04a-914f560f349c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95926, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家网站把那篇文章转载。", "corrected_sentence": "这家网站把那篇文章转载了。", "error_description": "“把”字句中动词后面需要“了”或其他成分，应说“把那篇文章转载了”，不说“把那篇文章转载”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8600dcf-f52c-42c9-a04a-914f560f349c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95926, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "编辑把这篇稿子转载给了第三版上。", "corrected_sentence": "编辑把这篇稿子转载到了第三版上。", "error_description": "“转载”后接地点要用“到”，“给”引出的是接受人，不能接地点。应说“转载到了第三版上”，不说“转载给了第三版上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8600dcf-f52c-42c9-a04a-914f560f349c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
