INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95928, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "穿过；渗透；通过。", "primary_collocate": null, "pronunciation": "tòu", "ipa": "tʰou˥˩", "syllable_count": 1, "sentences": [{"text": "雨水透进了我的鞋子。", "target_word": "透", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汗从背上透出来了。", "target_word": "透", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张纸太薄，墨水透到后面去了。", "target_word": "透", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "被子很厚，冷风透不进来。", "target_word": "透", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这双鞋太旧了，地上的水很快就透进来了。", "target_word": "透", "complexity_tier": "T3", "furigana": "zhè shuāng xié tài jiù le, dì shang de shuǐ hěn kuài jiù tòu jìn lái le.", "sentence_source": "generated"}, {"text": "水慢慢透进了土里。", "target_word": "透", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "帐篷破了一个洞，雨水透进来了。", "target_word": "透", "complexity_tier": "T3", "furigana": "zhàng peng pò le yí gè dòng, yǔ shuǐ tòu jìn lái le.", "sentence_source": "generated"}, {"text": "窗户没关好，冷风透进屋里。", "target_word": "透", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块棉布很薄，水很容易透过去。", "target_word": "透", "complexity_tier": "T3", "furigana": "zhè kuài mián bù hěn báo, shuǐ hěn róngyì tòu guò qù.", "sentence_source": "generated"}, {"text": "茶香从门里透出来了。", "target_word": "透", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "透过", "label": "复合"}, {"form": "透气", "label": "复合"}, {"form": "透风", "label": "复合"}], "register": "中性", "sense_fingerprint": "透：液体、气体、气味等渗入或穿过某物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9cfefc2-36a9-4169-9dcb-038663488343') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95928, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "透", "is_correct": true, "explanation": "tòu（第四声）是透，意思是液体或气体渗入、穿过。"}, {"text": "头", "is_correct": false, "explanation": "tóu（第二声）与 tòu（第四声）声调不同，意思是头。"}, {"text": "豆", "is_correct": false, "explanation": "dòu 与 tòu 声母不同（d 与 t），意思是豆。"}, {"text": "偷", "is_correct": false, "explanation": "tōu（第一声）与 tòu（第四声）声调不同，意思是偷。"}, {"text": "扣", "is_correct": false, "explanation": "kòu 与 tòu 声母不同（k 与 t），意思是扣。"}], "explanations": {"透": "tòu（第四声）是透，意思是液体或气体渗入、穿过。", "头": "tóu（第二声）与 tòu（第四声）声调不同，意思是头。", "豆": "dòu 与 tòu 声母不同（d 与 t），意思是豆。", "偷": "tōu（第一声）与 tòu（第四声）声调不同，意思是偷。", "扣": "kòu 与 tòu 声母不同（k 与 t），意思是扣。"}, "sentence_index": null, "correct_answer": "透"}, "level_3": {"options": [{"text": "透", "is_correct": true, "explanation": "透：雨水渗入鞋子内部，与句意相符。"}, {"text": "放", "is_correct": false, "explanation": "配价：“放”需要有人作施事把物体放在某处，雨水不能作施事。"}, {"text": "扛", "is_correct": false, "explanation": "搭配：“扛”的对象须是可以扛起的物体，雨水不能被扛进鞋子。"}, {"text": "锁", "is_correct": false, "explanation": "语义：“锁”指用锁把门、箱子等关紧，与雨水渗入鞋子的意思不符。"}], "explanations": {"透": "透：雨水渗入鞋子内部，与句意相符。", "放": "配价：“放”需要有人作施事把物体放在某处，雨水不能作施事。", "扛": "搭配：“扛”的对象须是可以扛起的物体，雨水不能被扛进鞋子。", "锁": "语义：“锁”指用锁把门、箱子等关紧，与雨水渗入鞋子的意思不符。"}, "sentence_index": 0, "correct_answer": "透"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "石头透进了水里，很快就不见了。", "explanation": "这里应该用〈沉〉。透的主语只能是液体、气体、气味或光，固体沉入水中要用沉。"}, {"text": "小猫透进了屋子，躲到了床下。", "explanation": "这里应该用〈跑〉。透指液体、气体或气味渗入，动物跑进屋子要用跑。"}, {"text": "他把墨水透到了纸上。", "explanation": "这里应该用〈涂〉。透指液体自己渗入或穿过，不能带“把”字宾语；人把墨水涂到纸上要用涂。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2743cbec-9a15-468a-9347-2eae987662b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95928, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "透", "is_correct": true, "explanation": "tòu（第四声）是透，意思是液体或气体渗入、穿过。"}, {"text": "投", "is_correct": false, "explanation": "tóu（第二声）与 tòu（第四声）声调不同，意思是投。"}, {"text": "逗", "is_correct": false, "explanation": "dòu 与 tòu 声母不同（d 与 t），意思是逗。"}, {"text": "后", "is_correct": false, "explanation": "hòu 与 tòu 声母不同（h 与 t），意思是后。"}, {"text": "奏", "is_correct": false, "explanation": "zòu（第四声）与 tòu（第四声）仅声母不同（z 与 t），意思是奏（演奏）。"}], "explanations": {"透": "tòu（第四声）是透，意思是液体或气体渗入、穿过。", "投": "tóu（第二声）与 tòu（第四声）声调不同，意思是投。", "逗": "dòu 与 tòu 声母不同（d 与 t），意思是逗。", "后": "hòu 与 tòu 声母不同（h 与 t），意思是后。", "奏": "zòu（第四声）与 tòu（第四声）仅声母不同（z 与 t），意思是奏（演奏）。"}, "sentence_index": null, "correct_answer": "透"}, "level_3": {"options": [{"text": "透", "is_correct": true, "explanation": "透：雨水穿过破洞进入帐篷，与句意相符。"}, {"text": "拖", "is_correct": false, "explanation": "搭配：“拖”的对象是可以被拖动的物体，雨水不能被拖进来。"}, {"text": "踢", "is_correct": false, "explanation": "配价：“踢”需要施事和受事，雨水不能发出踢的动作。"}, {"text": "抬", "is_correct": false, "explanation": "语义：“抬”指用手托起重物，与雨水流入帐篷的意思不符。"}], "explanations": {"透": "透：雨水穿过破洞进入帐篷，与句意相符。", "拖": "搭配：“拖”的对象是可以被拖动的物体，雨水不能被拖进来。", "踢": "配价：“踢”需要施事和受事，雨水不能发出踢的动作。", "抬": "语义：“抬”指用手托起重物，与雨水流入帐篷的意思不符。"}, "sentence_index": 6, "correct_answer": "透"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "人群透进了商店，把货架都挤乱了。", "explanation": "这里应该用〈冲〉。人群快速进入某处要用冲，透用于液体、气体或气味渗入。"}, {"text": "蝴蝶透出了窗户，飞到了花园里。", "explanation": "这里应该用〈钻〉。透用于液体、气体或气味渗出，蝴蝶这类动物从窗口钻出去要用钻。"}, {"text": "他把汤透进了碗里。", "explanation": "这里应该用〈盛〉。透指液体自己渗入或穿过，不能带“把”字宾语；人把汤盛进碗里要用盛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2743cbec-9a15-468a-9347-2eae987662b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95928, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "汗水慢慢透了过衬衫。", "corrected_sentence": "汗水慢慢透过了衬衫。", "error_description": "错误形式：透了过衬衫；正确形式：透过了衬衫。“了”是动态助词，应紧跟复合动词“透过”之后，不能插在“透”和“过”之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2743cbec-9a15-468a-9347-2eae987662b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95928, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "冷气进透了房间，屋里很凉。", "corrected_sentence": "冷气透进了房间，屋里很凉。", "error_description": "错误形式：进透了；正确形式：透进了。“进透”不成词：“透”是动词，“进”是趋向补语，应说“透进了”，颠倒后不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2743cbec-9a15-468a-9347-2eae987662b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
