INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95929, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "通往是路可以走到某个地方。", "primary_collocate": null, "pronunciation": "tōng wǎng", "ipa": "tʰʊŋ˥ wɑŋ˨˩", "syllable_count": 2, "sentences": [{"text": "这条公路通往北京。", "target_word": "通往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河边的小路通往一座老桥。", "target_word": "通往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条隧道通往山的另一边。", "target_word": "通往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "通往海边的公路风景很美。", "target_word": "通往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道台阶通往一座古老的寺庙。", "target_word": "通往", "complexity_tier": "T3", "furigana": "zhè dào táijiē tōngwǎng yí zuò gǔlǎo de sìmiào", "sentence_source": "generated"}, {"text": "左边的路通往火车站，右边的路通往公园。", "target_word": "通往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条山路通往我的老家。", "target_word": "通往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那扇小门通往后院。", "target_word": "通往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路通往市中心，车很多。", "target_word": "通往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图上这条线通往哪里？", "target_word": "通往", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "路可以走到某个地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d8db740-58a4-47c4-9227-9e17bdaf1786') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95929, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "通往", "is_correct": true, "explanation": "正确答案：通往（tōng wǎng），指路可以走到某个地方。"}, {"text": "公网", "is_correct": false, "explanation": "gōng wǎng（公网）与 tōng wǎng 声母不同（g 与 t），意思是公共网络，不是路通到某地。"}, {"text": "铜网", "is_correct": false, "explanation": "tóng wǎng（铜网）与 tōng wǎng 声调不同（第二声与第一声），意思是铜丝网，不是路通到某地。"}, {"text": "冲往", "is_correct": false, "explanation": "chōng wǎng（冲往）与 tōng wǎng 声母不同（ch 与 t），意思是朝某个方向猛冲过去，不是路通到某地。"}, {"text": "同往", "is_correct": false, "explanation": "tóng wǎng（同往）与 tōng wǎng 声调不同，意思是一起前往，不是路通到某地。"}], "explanations": {"通往": "正确答案：通往（tōng wǎng），指路可以走到某个地方。", "公网": "gōng wǎng（公网）与 tōng wǎng 声母不同（g 与 t），意思是公共网络，不是路通到某地。", "铜网": "tóng wǎng（铜网）与 tōng wǎng 声调不同（第二声与第一声），意思是铜丝网，不是路通到某地。", "冲往": "chōng wǎng（冲往）与 tōng wǎng 声母不同（ch 与 t），意思是朝某个方向猛冲过去，不是路通到某地。", "同往": "tóng wǎng（同往）与 tōng wǎng 声调不同，意思是一起前往，不是路通到某地。"}, "sentence_index": null, "correct_answer": "通往"}, "level_3": {"options": [{"text": "通往", "is_correct": true, "explanation": "通往：公路可以走到北京，与“公路”和“北京”的语境相符。"}, {"text": "崇拜", "is_correct": false, "explanation": "语义：公路不能崇拜城市，语义不通。"}, {"text": "站", "is_correct": false, "explanation": "搭配：“站”后面接地点要用“站在”，直接说“站北京”不通。"}, {"text": "爱", "is_correct": false, "explanation": "语义：公路不能爱北京，语义不通。"}], "explanations": {"通往": "通往：公路可以走到北京，与“公路”和“北京”的语境相符。", "崇拜": "语义：公路不能崇拜城市，语义不通。", "站": "搭配：“站”后面接地点要用“站在”，直接说“站北京”不通。", "爱": "语义：公路不能爱北京，语义不通。"}, "sentence_index": 0, "correct_answer": "通往"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们终于通往了河边。", "explanation": "这里应该用〈走到〉。通往的主语应是道路，人走到某地要用〈走到〉。"}, {"text": "他通往了老家。", "explanation": "这里应该用〈回到〉。通往的主语应是道路，人回到某地要用〈回到〉。"}, {"text": "这条小路通往了王老师。", "explanation": "通往的宾语应是地点，“王老师”是人，不能作为通往的终点，这里应该说“去找王老师”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8600dcf-f52c-42c9-a04a-914f560f349c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95929, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "通往", "is_correct": true, "explanation": "通往：山路可以通到老家，与“山路”和“老家”的语境相符。"}, {"text": "拜访", "is_correct": false, "explanation": "语义：山路不能拜访人或地方，语义不通。"}, {"text": "写", "is_correct": false, "explanation": "语义：路不能写家，语义不通。"}, {"text": "走", "is_correct": false, "explanation": "搭配：“走”接地点要带“到”或“去”，直接说“走我的老家”不通。"}], "explanations": {"通往": "通往：山路可以通到老家，与“山路”和“老家”的语境相符。", "拜访": "语义：山路不能拜访人或地方，语义不通。", "写": "语义：路不能写家，语义不通。", "走": "搭配：“走”接地点要带“到”或“去”，直接说“走我的老家”不通。"}, "sentence_index": 6, "correct_answer": "通往"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小明通往了对岸。", "explanation": "这里应该用〈游到〉。通往的主语应是道路，人游到某地要用〈游到〉。"}, {"text": "他通往了房间。", "explanation": "这里应该用〈走进〉。通往的主语应是道路，人进入某处要用〈走进〉。"}, {"text": "这条路通往那只猫。", "explanation": "这里应该用〈找到〉。通往的宾语只能是地点，“那只猫”不是地点；要表示找到某只猫，应用〈找到〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8600dcf-f52c-42c9-a04a-914f560f349c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95929, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条新铁路通往到山下。", "corrected_sentence": "这条新铁路通往山下。", "error_description": "“通往”后面直接接地点，不能再加“到”；应说“通往山下”，不说“通往到山下”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8600dcf-f52c-42c9-a04a-914f560f349c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
