INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95931, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "连号是一个接着一个的号码。", "primary_collocate": null, "pronunciation": "lián hào", "ipa": "ljɛn˧˥ xɑʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "我买的两张票是连号。", "target_word": "连号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这三张电影票是连号，可以坐在一起。", "target_word": "连号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的房间号和我的是连号。", "target_word": "连号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请给我两个连号的座位。", "target_word": "连号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行给了我一组连号的新钱。", "target_word": "连号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她中奖的号码是连号。", "target_word": "连号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些发票是连号，很容易查。", "target_word": "连号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的学号是连号，所以坐得很近。", "target_word": "连号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个手机号码是连号，很好记。", "target_word": "连号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把这几个连号写在黑板上了。", "target_word": "连号", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "連號", "label": "繁体"}], "register": "中性", "sense_fingerprint": "一个接着一个的号码", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd12015e2-7c16-4cde-a171-47414d24e165') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95931, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "连号", "is_correct": true, "explanation": "正确。两张票是一个接着一个的号码，可以说是连号。"}, {"text": "价格", "is_correct": false, "explanation": "语义：票的号码不是价格，「两张票是价格」说不通。"}, {"text": "数量", "is_correct": false, "explanation": "语义：两张票不是数量，「数量」指多少，不能这样用。"}, {"text": "座位", "is_correct": false, "explanation": "搭配：「是」后面应接票所对应的号码类别，「座位」与「票」不能这样对应。"}], "explanations": {"连号": "正确。两张票是一个接着一个的号码，可以说是连号。", "价格": "语义：票的号码不是价格，「两张票是价格」说不通。", "数量": "语义：两张票不是数量，「数量」指多少，不能这样用。", "座位": "搭配：「是」后面应接票所对应的号码类别，「座位」与「票」不能这样对应。"}, "sentence_index": 0, "correct_answer": "连号"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们一起去连号看电影。", "explanation": "这里应该用〈电影院〉。连号是号码，不是地方，不能用「去」指向它。"}, {"text": "他是我的连号，住在隔壁。", "explanation": "这里应该用〈邻居〉。连号指号码，不指人。"}, {"text": "他每天坐连号去学校。", "explanation": "这里应该用〈公交车〉。连号是号码，不是交通工具，不能用「坐」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4be6a56-6de3-4f2a-8abf-94e8205a5896') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95931, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "连号", "is_correct": true, "explanation": "正确。发票是一组连续的号码，所以很容易查，句子成立。"}, {"text": "金额", "is_correct": false, "explanation": "语义：「金额」是钱的数目，不是发票号码的形式，「发票是金额」说不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：「颜色」不是号码的类别，「这些发票是颜色」说不通。"}, {"text": "地址", "is_correct": false, "explanation": "搭配：「是」后要接号码的类别，「地址」与「发票」不构成这样的对应。"}], "explanations": {"连号": "正确。发票是一组连续的号码，所以很容易查，句子成立。", "金额": "语义：「金额」是钱的数目，不是发票号码的形式，「发票是金额」说不通。", "颜色": "语义：「颜色」不是号码的类别，「这些发票是颜色」说不通。", "地址": "搭配：「是」后要接号码的类别，「地址」与「发票」不构成这样的对应。"}, "sentence_index": 6, "correct_answer": "连号"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他早上吃了连号。", "explanation": "这里应该用〈面包〉。连号是号码，不能吃，「吃」要接食物。"}, {"text": "她是我的连号，从小一起长大。", "explanation": "这里应该用〈朋友〉。连号指号码，不指人。"}, {"text": "他的连号比我的高。", "explanation": "这里应该用〈个子〉。连号是号码，不能用来比较身高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4be6a56-6de3-4f2a-8abf-94e8205a5896') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95931, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们给每位客人发了一个连号的号码牌。", "corrected_sentence": "他们给每位客人发了一组连号的号码牌。", "error_description": "错误形式：「一个连号的号码牌」用了量词「个」，但「连号」指一组相连的号码，应用「组」。正确形式：「一组连号的号码牌」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4be6a56-6de3-4f2a-8abf-94e8205a5896') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95931, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工作人员把号码排了连号。", "corrected_sentence": "工作人员把号码排成了连号。", "error_description": "错误形式：「排了连号」缺少「成」。正确形式：「排成了连号」。表示排列的结果要用「排成」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4be6a56-6de3-4f2a-8abf-94e8205a5896') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
