INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95938, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "最高级别的；最上等的。", "primary_collocate": null, "pronunciation": "dǐng jí", "ipa": "tiŋ˨˩ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "这是一所顶级大学，很难考进去。", "target_word": "顶级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "顶级的红酒要放在凉爽的地方。", "target_word": "顶级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在顶级比赛中拿到了第一名。", "target_word": "顶级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司请来了顶级专家。", "target_word": "顶级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她买了一块顶级的手表。", "target_word": "顶级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "顶级的服务让客人很满意。", "target_word": "顶级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家餐厅用的是顶级牛肉。", "target_word": "顶级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直想进入顶级球队。", "target_word": "顶级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是顶级的设计，每个地方都很漂亮。", "target_word": "顶级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "顶级的运动员每天都要训练很长时间。", "target_word": "顶级", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "级别最高的，最上等的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d8db740-58a4-47c4-9227-9e17bdaf1786') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95938, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "顶级", "is_correct": true, "explanation": "顶级：级别最高的，最上等的。"}, {"text": "定级", "is_correct": false, "explanation": "dìng（第四声）与 dǐng（第三声）声调不同，意思是确定等级，不是级别最高。"}, {"text": "等级", "is_correct": false, "explanation": "děng 与 dǐng 韵母不同（eng/ing），意思是等级、层次，并不表示最高。"}, {"text": "丙级", "is_correct": false, "explanation": "bǐng 与 dǐng 声母不同（b/d），意思是丙等，属于较低级别。"}, {"text": "丁级", "is_correct": false, "explanation": "dīng（第一声）与 dǐng（第三声）声调不同，意思是丁等，属于较低级别。"}], "explanations": {"顶级": "顶级：级别最高的，最上等的。", "定级": "dìng（第四声）与 dǐng（第三声）声调不同，意思是确定等级，不是级别最高。", "等级": "děng 与 dǐng 韵母不同（eng/ing），意思是等级、层次，并不表示最高。", "丙级": "bǐng 与 dǐng 声母不同（b/d），意思是丙等，属于较低级别。", "丁级": "dīng（第一声）与 dǐng（第三声）声调不同，意思是丁等，属于较低级别。"}, "sentence_index": null, "correct_answer": "顶级"}, "level_3": {"options": [{"text": "顶级", "is_correct": true, "explanation": "顶级修饰“大学”，指级别最高，符合“很难考进去”的语境。"}, {"text": "透明", "is_correct": false, "explanation": "语义：“透明”说能透光的物体，不能修饰学校。"}, {"text": "狭窄", "is_correct": false, "explanation": "搭配：“狭窄”说空间、道路，不说大学。"}, {"text": "易碎", "is_correct": false, "explanation": "搭配：“易碎”说玻璃、瓷器等物品，不说学校。"}], "explanations": {"顶级": "顶级修饰“大学”，指级别最高，符合“很难考进去”的语境。", "透明": "语义：“透明”说能透光的物体，不能修饰学校。", "狭窄": "搭配：“狭窄”说空间、道路，不说大学。", "易碎": "搭配：“易碎”说玻璃、瓷器等物品，不说学校。"}, "sentence_index": 0, "correct_answer": "顶级"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个房间的面积顶级。", "explanation": "这里应该用〈最大〉。顶级说级别或质量，不说面积等可量化的数值。"}, {"text": "这个人的身高顶级。", "explanation": "这里应该用〈最高〉。顶级用于级别、等级，不用来说身高等数值。"}, {"text": "他家离公司顶级。", "explanation": "这里应该用〈最近〉。顶级用于级别、等级，不用来说距离。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8600dcf-f52c-42c9-a04a-914f560f349c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95938, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "顶级", "is_correct": true, "explanation": "顶级修饰“牛肉”，指品质最好，符合句意。"}, {"text": "温柔", "is_correct": false, "explanation": "语义：“温柔”形容人的性情，不能用来说牛肉。"}, {"text": "潮湿", "is_correct": false, "explanation": "搭配：“潮湿”形容天气或空气，不用来修饰食材的品质。"}, {"text": "偏僻", "is_correct": false, "explanation": "搭配：“偏僻”说地方，不说食材。"}], "explanations": {"顶级": "顶级修饰“牛肉”，指品质最好，符合句意。", "温柔": "语义：“温柔”形容人的性情，不能用来说牛肉。", "潮湿": "搭配：“潮湿”形容天气或空气，不用来修饰食材的品质。", "偏僻": "搭配：“偏僻”说地方，不说食材。"}, "sentence_index": 6, "correct_answer": "顶级"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次考试的时间顶级。", "explanation": "这里应该用〈最晚〉。顶级说级别、质量，不用来说时间的先后。"}, {"text": "这个包的重量顶级。", "explanation": "这里应该用〈最重〉。顶级说级别、质量，不用来说重量等数值。"}, {"text": "这条河的水深顶级。", "explanation": "这里应该用〈最深〉。顶级形容级别、质量，不用来说水的深浅等数值。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8600dcf-f52c-42c9-a04a-914f560f349c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95938, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这所学校的师资是顶顶级的。", "corrected_sentence": "这所学校的师资是顶级的。", "error_description": "“顶顶级”不能这样叠说，“顶级”不作叠用；应说“是顶级的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8600dcf-f52c-42c9-a04a-914f560f349c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95938, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家餐厅的服务是顶级地。", "corrected_sentence": "这家餐厅的服务是顶级的。", "error_description": "“地”是状语的结构助词，不能附在形容词后作谓语。应为“是顶级的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8600dcf-f52c-42c9-a04a-914f560f349c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
