INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95945, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "一共是把所有的数合在一起，一共有多少。", "primary_collocate": null, "pronunciation": "yí gòng", "ipa": "i˧˥ kʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "你们一共有几个人？", "target_word": "一共", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些东西一共多少钱？", "target_word": "一共", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问，一共多少钱？", "target_word": "一共", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们班一共有多少学生？", "target_word": "一共", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你一共买了几本书？", "target_word": "一共", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个盒子里一共有十个苹果。", "target_word": "一共", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三加四加五，一共是十二。", "target_word": "一共", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上有三本，书架上有七本，一共十本。", "target_word": "一共", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你家一共有几口人？", "target_word": "一共", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个星期你一共学了多少个字？", "target_word": "一共", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "一共：副词，把各部分的数合在一起，用于问总数或算总和", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e75dae58-febb-4f3d-bd36-d38303f1557e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95945, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一共", "is_correct": true, "explanation": "正确：“一共”表示把各部分合起来，符合问总人数的语境。"}, {"text": "共同", "is_correct": false, "explanation": "语义：“共同”表示一起、共有，不是问总数，这里不通。"}, {"text": "特别", "is_correct": false, "explanation": "语义：“特别”表示程度，不能用来问人数的总和。"}, {"text": "颇", "is_correct": false, "explanation": "语域：“颇”是书面语，口语里不用于问人数，且表示“相当”。"}], "explanations": {"一共": "正确：“一共”表示把各部分合起来，符合问总人数的语境。", "共同": "语义：“共同”表示一起、共有，不是问总数，这里不通。", "特别": "语义：“特别”表示程度，不能用来问人数的总和。", "颇": "语域：“颇”是书面语，口语里不用于问人数，且表示“相当”。"}, "sentence_index": 0, "correct_answer": "一共"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "你们一共去图书馆吗？", "explanation": "这里应该用〈一起〉。一共表示数量的合计，不能表示共同行动；“你们一起去图书馆吗？”才对。"}, {"text": "你一共几岁？", "explanation": "这里应该用〈今年〉。一共表示合计，不能用来问年龄；应说“你今年几岁？”。"}, {"text": "我们一共吃饭。", "explanation": "这里应该用〈一起〉。一共表示数量的合计，不表示共同行动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37292fc7-7b2f-4166-bcac-e327dc3400ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95945, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一共", "is_correct": true, "explanation": "正确：“一共”表示合起来的总和，符合“三加四加五”的算式语境。"}, {"text": "一起", "is_correct": false, "explanation": "搭配：“一起”表示共同做某事，不能用来说算式的总和。"}, {"text": "仅", "is_correct": false, "explanation": "语域：“仅”是书面语，表示只有，与算式的总和不符。"}, {"text": "都", "is_correct": false, "explanation": "语义：“都”表示全部如此，不能表示相加后的总数，这里说不通。"}], "explanations": {"一共": "正确：“一共”表示合起来的总和，符合“三加四加五”的算式语境。", "一起": "搭配：“一起”表示共同做某事，不能用来说算式的总和。", "仅": "语域：“仅”是书面语，表示只有，与算式的总和不符。", "都": "语义：“都”表示全部如此，不能表示相加后的总数，这里说不通。"}, "sentence_index": 6, "correct_answer": "一共"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一共在吃饭。", "explanation": "这里应该用〈正在〉。一共表示数量合计，不能表示动作正在进行。"}, {"text": "我们一共出发。", "explanation": "这里应该用〈一起〉。一共表示数量的合计，不表示共同行动；“我们一起出发”才对。"}, {"text": "明天一共会下雨。", "explanation": "这里应该用〈将会〉。一共表示合计，不能表示将要发生的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37292fc7-7b2f-4166-bcac-e327dc3400ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95945, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个班一共有有几个同学？", "corrected_sentence": "这个班一共有几个同学？", "error_description": "错误在“有”字重复了两次。“有”只用一次，应说“这个班一共有几个同学”，多出的“有”要删去。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37292fc7-7b2f-4166-bcac-e327dc3400ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95945, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一共一共背了多少个单词？", "corrected_sentence": "他一共背了多少个单词？", "error_description": "错误在于“一共”重复出现。一个句子中“一共”只用一次，应说“他一共背了多少个单词？”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37292fc7-7b2f-4166-bcac-e327dc3400ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
