INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95950, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "好像；似乎。", "primary_collocate": null, "pronunciation": "fǎng fú", "ipa": "faŋ˨˩ fu˧˥", "syllable_count": 2, "sentences": [{"text": "他仿佛没听见我说的话。", "target_word": "仿佛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屋里仿佛有人在说话。", "target_word": "仿佛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她仿佛有点儿不高兴。", "target_word": "仿佛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天仿佛要下雨了。", "target_word": "仿佛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我仿佛在哪儿见过他。", "target_word": "仿佛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的脸色仿佛不太好。", "target_word": "仿佛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家仿佛都忘了今天是他的生日。", "target_word": "仿佛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗外仿佛传来了一阵音乐声。", "target_word": "仿佛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈仿佛知道我在想什么。", "target_word": "仿佛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他仿佛很累，一进门就睡了。", "target_word": "仿佛", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "彷彿", "label": "繁体"}], "register": "中性", "sense_fingerprint": "表示不太确定的感觉或判断，相当于好像、似乎", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afcd0b75-9fed-4b31-9fb8-4f73e2bd4177') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95950, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "仿佛", "is_correct": true, "explanation": "正确答案：仿佛（fǎng fú），表示“好像、似乎”的不确定判断。"}, {"text": "防腐", "is_correct": false, "explanation": "防腐（fáng fǔ）：fǎng（第三声）与 fáng（第二声）声调不同，fú（第二声）与 fǔ（第三声）声调不同；意思是防止食物腐烂。"}, {"text": "反复", "is_correct": false, "explanation": "反复（fǎn fù）：fǎng 与 fǎn 的韵尾不同（ng 与 n），fú（第二声）与 fù（第四声）声调不同；意思是重复或来回。"}, {"text": "反腐", "is_correct": false, "explanation": "反腐（fǎn fǔ）：fǎng 与 fǎn 的韵尾不同（ng 与 n），fú（第二声）与 fǔ（第三声）声调不同；意思是反对腐败。"}], "explanations": {"仿佛": "正确答案：仿佛（fǎng fú），表示“好像、似乎”的不确定判断。", "防腐": "防腐（fáng fǔ）：fǎng（第三声）与 fáng（第二声）声调不同，fú（第二声）与 fǔ（第三声）声调不同；意思是防止食物腐烂。", "反复": "反复（fǎn fù）：fǎng 与 fǎn 的韵尾不同（ng 与 n），fú（第二声）与 fù（第四声）声调不同；意思是重复或来回。", "反腐": "反腐（fǎn fǔ）：fǎng 与 fǎn 的韵尾不同（ng 与 n），fú（第二声）与 fǔ（第三声）声调不同；意思是反对腐败。"}, "sentence_index": null, "correct_answer": "仿佛"}, "level_3": {"options": [{"text": "仿佛", "is_correct": true, "explanation": "正确答案：“他仿佛没听见我说的话”表示一种推测，与句子的语境相符。"}, {"text": "正在", "is_correct": false, "explanation": "体貌：“正在”表示动作正在进行，与“没听见”这种结果状态冲突，句子不通。"}, {"text": "赶紧", "is_correct": false, "explanation": "语义：“赶紧”表示急忙去做某件事，要求有动作，不能修饰“没听见”这种静态状态。"}, {"text": "连忙", "is_correct": false, "explanation": "语义：“连忙”表示马上行动，与“没听见”这种状态不能搭配，句子不通。"}], "explanations": {"仿佛": "正确答案：“他仿佛没听见我说的话”表示一种推测，与句子的语境相符。", "正在": "体貌：“正在”表示动作正在进行，与“没听见”这种结果状态冲突，句子不通。", "赶紧": "语义：“赶紧”表示急忙去做某件事，要求有动作，不能修饰“没听见”这种静态状态。", "连忙": "语义：“连忙”表示马上行动，与“没听见”这种状态不能搭配，句子不通。"}, "sentence_index": 0, "correct_answer": "仿佛"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我刚才亲眼看见他进了家门，他仿佛已经到家了。", "explanation": "这里应该用〈肯定〉。仿佛表示不确定的推测，而“我刚才亲眼看见他进了家门”是亲身见到的事实，用仿佛会与语境矛盾。"}, {"text": "这份报告仿佛有三处错误，我已经一条一条数过了。", "explanation": "这里应该用〈确实〉。仿佛表示不确定的判断，而“我已经一条一条数过了”说明是确定的事实，用仿佛会与语境矛盾。"}, {"text": "小王这次仿佛考了班里第一，成绩单已经发下来了。", "explanation": "这里应该用〈果然〉。仿佛表示推测，而“成绩单已经发下来了”说明结果已经确定，应表达“如预料那样”的确认，用仿佛会与语境矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda09645-f95d-4b38-abea-00657f3ba78a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95950, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "仿佛", "is_correct": true, "explanation": "正确答案：仿佛（fǎng fú），表示“好像、似乎”的不确定判断。"}, {"text": "丰富", "is_correct": false, "explanation": "丰富（fēng fù）：fǎng（第三声）与 fēng（第一声）的韵腹不同（a 与 e），fú（第二声）与 fù（第四声）声调不同；意思是种类或数量多。"}, {"text": "往复", "is_correct": false, "explanation": "往复（wǎng fù）：声母 f 与 w 不同，fú（第二声）与 fù（第四声）声调不同；意思是来回运动。"}, {"text": "方法", "is_correct": false, "explanation": "方法（fāng fǎ）：fǎng（第三声）与 fāng（第一声）声调不同；fú 与 fǎ 的韵母不同（u 与 a），声调也不同；意思是做事的途径。"}], "explanations": {"仿佛": "正确答案：仿佛（fǎng fú），表示“好像、似乎”的不确定判断。", "丰富": "丰富（fēng fù）：fǎng（第三声）与 fēng（第一声）的韵腹不同（a 与 e），fú（第二声）与 fù（第四声）声调不同；意思是种类或数量多。", "往复": "往复（wǎng fù）：声母 f 与 w 不同，fú（第二声）与 fù（第四声）声调不同；意思是来回运动。", "方法": "方法（fāng fǎ）：fǎng（第三声）与 fāng（第一声）声调不同；fú 与 fǎ 的韵母不同（u 与 a），声调也不同；意思是做事的途径。"}, "sentence_index": null, "correct_answer": "仿佛"}, "level_3": {"options": [{"text": "仿佛", "is_correct": true, "explanation": "正确答案：“大家仿佛都忘了今天是他的生日”表示推测，与“大家都忘了”的语境相符。"}, {"text": "纷纷", "is_correct": false, "explanation": "语义：“纷纷”表示许多人接连做同一动作，不能修饰“忘了”这种一次性的状态。"}, {"text": "即将", "is_correct": false, "explanation": "体貌：“即将”表示即将发生，与“忘了”这种已经完成的情况冲突。"}, {"text": "兀自", "is_correct": false, "explanation": "语域：“兀自”带有书面语色彩，与这句口语化的叙述不协调，句子也不自然。"}], "explanations": {"仿佛": "正确答案：“大家仿佛都忘了今天是他的生日”表示推测，与“大家都忘了”的语境相符。", "纷纷": "语义：“纷纷”表示许多人接连做同一动作，不能修饰“忘了”这种一次性的状态。", "即将": "体貌：“即将”表示即将发生，与“忘了”这种已经完成的情况冲突。", "兀自": "语域：“兀自”带有书面语色彩，与这句口语化的叙述不协调，句子也不自然。"}, "sentence_index": 6, "correct_answer": "仿佛"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "校长仿佛亲自到场了，签到表上还有他的签名。", "explanation": "这里应该用〈显然〉。仿佛表示不确定的推测，而“签到表上还有他的签名”是确定的依据，用仿佛会与语境矛盾。"}, {"text": "工作仿佛完成了，报告我今天上午就交给老板了。", "explanation": "这里应该用〈已经〉。仿佛表示不确定的推测，而“报告今天上午就交给老板了”是具体的已发生事实，用仿佛会让语气显得含糊。"}, {"text": "合同仿佛生效了，所有人都收到了通知。", "explanation": "这里应该用〈真的〉。仿佛表示推测，而“所有人都收到了通知”说明合同已经确定生效，用仿佛会显得不肯定。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda09645-f95d-4b38-abea-00657f3ba78a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95950, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "电话那头仿佛的有人在笑。", "corrected_sentence": "电话那头仿佛有人在笑。", "error_description": "错误：“仿佛”后面多加了“的”。“仿佛”是副词，后面不能直接接“的”，正确形式为“电话那头仿佛有人在笑”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda09645-f95d-4b38-abea-00657f3ba78a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95950, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她仿佛的很有把握。", "corrected_sentence": "她仿佛很有把握。", "error_description": "错误：“仿佛”是副词，后面不能直接接“的”，应删去“的”，正确形式为“她仿佛很有把握”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bda09645-f95d-4b38-abea-00657f3ba78a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
