INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95964, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4126d464-5865-4126-bfc4-864583ec3dfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95964, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "将来的景象或情形。", "primary_collocate": null, "pronunciation": "qián jǐng", "ipa": "tɕʰjɛn˧˥ tɕiŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这个行业的前景很好。", "target_word": "前景", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对公司的前景很有信心。", "target_word": "前景", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学这个专业，前景怎么样？", "target_word": "前景", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新能源的发展前景很广阔。", "target_word": "前景", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的前景不太乐观。", "target_word": "前景", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板看好这个项目的前景。", "target_word": "前景", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个产品的市场前景不错。", "target_word": "前景", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要了解行业的前景，再选工作。", "target_word": "前景", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家说，人工智能的前景很光明。", "target_word": "前景", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他觉得这份工作没有前景，就换了。", "target_word": "前景", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "发展前景", "label": "复合"}, {"form": "市场前景", "label": "复合"}], "register": "中性", "sense_fingerprint": "前景：事物将来的景象或情形", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd34cd94a-28b4-4837-b0b6-593d7d226e00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95964, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "体重", "is_correct": false, "explanation": "语义：“体重”指人或动物的重量，不能用来形容一个行业。"}, {"text": "前景", "is_correct": true, "explanation": "“前景”指将来的景象或情形，“这个行业的前景很好”说的是该行业将来发展很好。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”指大气的冷暖晴雨，用来形容行业没有意义。"}, {"text": "面积", "is_correct": false, "explanation": "搭配：“面积”说大小，不说“很好”。"}], "explanations": {"体重": "语义：“体重”指人或动物的重量，不能用来形容一个行业。", "前景": "“前景”指将来的景象或情形，“这个行业的前景很好”说的是该行业将来发展很好。", "天气": "语义：“天气”指大气的冷暖晴雨，用来形容行业没有意义。", "面积": "搭配：“面积”说大小，不说“很好”。"}, "sentence_index": 0, "correct_answer": "前景"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把前景搬到了新办公室。", "explanation": "这里应该用〈桌椅〉。“桌椅”可以搬；“前景”是抽象的将来情形，不能搬。"}, {"text": "这块蛋糕的前景很甜。", "explanation": "这里应该用〈味道〉。“味道很甜”是常见说法；“前景”指将来的情形，不能用来形容蛋糕。"}, {"text": "这部电影的前景很感人。", "explanation": "这里应该用〈结局〉。“结局”指故事的最后部分，可以说“很感人”；“前景”指将来的情形，不用来形容故事的结尾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4126d464-5865-4126-bfc4-864583ec3dfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95964, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”指人或生物存在的时间，不能用来评价一个产品的市场。"}, {"text": "前景", "is_correct": true, "explanation": "“前景”指将来的景象或情形，“这个产品的市场前景不错”说的是市场上的发展前途不错。"}, {"text": "身高", "is_correct": false, "explanation": "语义：“身高”指人或物的高矮，与市场情况无关。"}, {"text": "体积", "is_correct": false, "explanation": "搭配：“体积”说大小，不跟“不错”搭配。"}], "explanations": {"年龄": "语义：“年龄”指人或生物存在的时间，不能用来评价一个产品的市场。", "前景": "“前景”指将来的景象或情形，“这个产品的市场前景不错”说的是市场上的发展前途不错。", "身高": "语义：“身高”指人或物的高矮，与市场情况无关。", "体积": "搭配：“体积”说大小，不跟“不错”搭配。"}, "sentence_index": 6, "correct_answer": "前景"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "姥姥用前景煮了一锅粥。", "explanation": "这里应该用〈大米〉。“大米”可以用来煮粥；“前景”是抽象的将来情形，不能用来煮。"}, {"text": "他把前景开进了车库。", "explanation": "这里应该用〈汽车〉。“汽车”可以开进车库；“前景”是抽象的将来情形，不能开进车库。"}, {"text": "他用前景写完了一封信。", "explanation": "这里应该用〈钢笔〉。“钢笔”可以用来写字；“前景”是抽象的将来情形，不能用来写信。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4126d464-5865-4126-bfc4-864583ec3dfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95964, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家店地前景很好。", "corrected_sentence": "这家店的前景很好。", "error_description": "结构助词错误：“这家店”修饰“前景”时应用“的”，说“这家店的前景”；“地”用于修饰动词或形容词，不能用在名词前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4126d464-5865-4126-bfc4-864583ec3dfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95964, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个网店的前景们不错。", "corrected_sentence": "这个网店的前景很不错。", "error_description": "复数标记错误：“前景”是抽象名词，不能加“们”表示复数，应说“前景很不错”，用“很”修饰“不错”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4126d464-5865-4126-bfc4-864583ec3dfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
