INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95965, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4126d464-5865-4126-bfc4-864583ec3dfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95965, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "汇报是把做的事情告诉别人。", "primary_collocate": null, "pronunciation": "huì bào", "ipa": "xweɪ˥˩ pɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "孩子放学回家，向妈妈汇报了一天的事。", "target_word": "汇报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做完作业，我要向爸爸汇报一下。", "target_word": "汇报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明放学后总爱向姐姐汇报自己在学校做的事。", "target_word": "汇报", "complexity_tier": "T3", "furigana": "xiǎo míng fàng xué hòu zǒng ài xiàng jiě jie huì bào zì jǐ zài xué xiào zuò de shì.", "sentence_source": "generated"}, {"text": "旅行回来后，他向朋友汇报了路上的见闻。", "target_word": "汇报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你昨天去哪儿了？快向我汇报！", "target_word": "汇报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "女儿把考试成绩向妈妈汇报了。", "target_word": "汇报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟跑过来，向我汇报他的新发现。", "target_word": "汇报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每天晚上，儿子都会汇报学校里的事。", "target_word": "汇报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他刚到家，就向家人汇报了好消息。", "target_word": "汇报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让同学们汇报假期做过的事。", "target_word": "汇报", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "汇报了", "label": "体标"}, {"form": "汇报过", "label": "体标"}, {"form": "汇报汇报", "label": "重叠"}], "register": "中性", "sense_fingerprint": "把自己做过的事、见闻告诉家人朋友", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd34cd94a-28b4-4837-b0b6-593d7d226e00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95965, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "修理", "is_correct": false, "explanation": "语义：“修理”指修补器物，不能用来表示向妈妈讲一天的事。"}, {"text": "汇报", "is_correct": true, "explanation": "“汇报”指把做过的事告诉家人，“向妈妈汇报了一天的事”说的是孩子把一天的事讲给妈妈听。"}, {"text": "参观", "is_correct": false, "explanation": "配价：“参观”要带参观的场所作宾语，“一天的事”不能作它的宾语。"}, {"text": "举办", "is_correct": false, "explanation": "搭配：“举办”多搭配活动或比赛，不说“举办一天的事”。"}], "explanations": {"修理": "语义：“修理”指修补器物，不能用来表示向妈妈讲一天的事。", "汇报": "“汇报”指把做过的事告诉家人，“向妈妈汇报了一天的事”说的是孩子把一天的事讲给妈妈听。", "参观": "配价：“参观”要带参观的场所作宾语，“一天的事”不能作它的宾语。", "举办": "搭配：“举办”多搭配活动或比赛，不说“举办一天的事”。"}, "sentence_index": 0, "correct_answer": "汇报"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在舞台上汇报了一支舞。", "explanation": "这里应该用〈跳〉。“跳舞”是表演动作；“汇报”只用于事情、经过或情况，不能指跳舞。"}, {"text": "他和爷爷汇报了一个下午的天。", "explanation": "这里应该用〈聊〉。“汇报”是把事情讲给人听，不能说“汇报一个下午的天”；闲谈要说“聊天”。"}, {"text": "他给弟弟汇报了一个谜语。", "explanation": "这里应该用〈讲〉。“讲谜语”是常见说法，“汇报”只用于事情、经过或情况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4126d464-5865-4126-bfc4-864583ec3dfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95965, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "训练", "is_correct": false, "explanation": "语义：“训练”指有计划地练习，不能用来表示向我传达发现。"}, {"text": "汇报", "is_correct": true, "explanation": "“汇报”指把做过的事或见闻告诉别人，“向我汇报他的新发现”说的是把发现讲给我听。"}, {"text": "研发", "is_correct": false, "explanation": "语义：“研发”指研究开发产品或技术，不能表示把发现讲给人听。"}, {"text": "收藏", "is_correct": false, "explanation": "配价：“收藏”带收藏的物品作宾语，“向我”引出的人不能作它的宾语。"}], "explanations": {"训练": "语义：“训练”指有计划地练习，不能用来表示向我传达发现。", "汇报": "“汇报”指把做过的事或见闻告诉别人，“向我汇报他的新发现”说的是把发现讲给我听。", "研发": "语义：“研发”指研究开发产品或技术，不能表示把发现讲给人听。", "收藏": "配价：“收藏”带收藏的物品作宾语，“向我”引出的人不能作它的宾语。"}, "sentence_index": 6, "correct_answer": "汇报"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "同学们汇报了各自的理想。", "explanation": "这里应该用〈谈〉。“谈理想”是交流心里的想法；“汇报”用于做过的事或情况，不说“汇报理想”。"}, {"text": "同学们把书包汇报在桌子上。", "explanation": "这里应该用〈放〉。“把书包放在桌子上”是常见说法；“汇报”用于事情或情况，不能用来说放东西。"}, {"text": "同学们汇报了一首歌。", "explanation": "这里应该用〈唱〉。“唱歌”是表演，“汇报”不能指唱歌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4126d464-5865-4126-bfc4-864583ec3dfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95965, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他向爸爸了汇报考试成绩。", "corrected_sentence": "他向爸爸汇报考试成绩。", "error_description": "“了”位置错误：“了”不能放在动词“汇报”前面，说“向爸爸了汇报”不对；去掉“了”应说“他向爸爸汇报考试成绩”，表示已经完成时应说“他向爸爸汇报了考试成绩”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4126d464-5865-4126-bfc4-864583ec3dfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95965, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我要向妈妈汇报今天的事一下。", "corrected_sentence": "我要向妈妈汇报今天的事。", "error_description": "“一下”位置错误：“一下”应紧跟动词，说“汇报一下”，不能放在宾语“今天的事”后面；去掉“一下”应说“我要向妈妈汇报今天的事”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4126d464-5865-4126-bfc4-864583ec3dfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
