INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95966, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把工作或情况向上级或有关人员报告。", "primary_collocate": null, "pronunciation": "huì bào", "ipa": "xweɪ˥˩ pɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "我每周五向经理汇报工作进度。", "target_word": "汇报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王正在给主任汇报这个月的销售情况。", "target_word": "汇报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "项目做完以后，请马上向领导汇报。", "target_word": "汇报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把调查结果向局长汇报了一遍。", "target_word": "汇报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "部门经理明天要向总经理汇报计划。", "target_word": "汇报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出了问题，你应该先向上级汇报。", "target_word": "汇报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "队长向指挥部汇报了前方的情况。", "target_word": "汇报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板让我下午三点汇报一下工作。", "target_word": "汇报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每个月都向公司领导汇报过预算。", "target_word": "汇报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把检查情况向校长汇报清楚。", "target_word": "汇报", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "汇报了", "label": "体标"}, {"form": "汇报过", "label": "体标"}, {"form": "汇报汇报", "label": "重叠"}, {"form": "汇报会", "label": "复合"}], "register": "正式", "sense_fingerprint": "向上级或有关人员报告工作、情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd34cd94a-28b4-4837-b0b6-593d7d226e00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95966, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”指清除脏物，不能用来表示向经理报告进度。"}, {"text": "汇报", "is_correct": true, "explanation": "“汇报”指向上级或有关人员报告工作，“我每周五向经理汇报工作进度”说的是定期报告进度。"}, {"text": "包括", "is_correct": false, "explanation": "语义：“包括”表示含有，不能表示向经理报告工作进度。"}, {"text": "削减", "is_correct": false, "explanation": "搭配：“削减”多用于开支、人员，不说“削减工作进度”。"}], "explanations": {"打扫": "搭配：“打扫”指清除脏物，不能用来表示向经理报告进度。", "汇报": "“汇报”指向上级或有关人员报告工作，“我每周五向经理汇报工作进度”说的是定期报告进度。", "包括": "语义：“包括”表示含有，不能表示向经理报告工作进度。", "削减": "搭配：“削减”多用于开支、人员，不说“削减工作进度”。"}, "sentence_index": 0, "correct_answer": "汇报"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把这个消息汇报了经理。", "explanation": "这里应该用〈告诉〉。“汇报”要说“向上级汇报”，不能直接带人作宾语；这句说的是普通的告知。"}, {"text": "我们向全体员工汇报了一盆花。", "explanation": "这里应该用〈送〉。“送花”是常见说法；“汇报”只用于工作、情况，不能用来说送花。"}, {"text": "他向大家汇报了一个笑话。", "explanation": "这里应该用〈讲〉。“讲笑话”是常见说法；“汇报”只用于工作、情况或经过，不能用来说讲笑话。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4126d464-5865-4126-bfc4-864583ec3dfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95966, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”指觉得好而赞赏，不能表示向指挥部传达情况。"}, {"text": "汇报", "is_correct": true, "explanation": "“汇报”指向上级报告情况，“队长向指挥部汇报了前方的情况”说的是队长向上级传达前线情况。"}, {"text": "逃避", "is_correct": false, "explanation": "语义：“逃避”指躲开，“逃避了前方的情况”与向指挥部报告的意思不符。"}, {"text": "拖延", "is_correct": false, "explanation": "搭配：“拖延”多搭配时间或任务，不说“拖延了情况”。"}], "explanations": {"欣赏": "语义：“欣赏”指觉得好而赞赏，不能表示向指挥部传达情况。", "汇报": "“汇报”指向上级报告情况，“队长向指挥部汇报了前方的情况”说的是队长向上级传达前线情况。", "逃避": "语义：“逃避”指躲开，“逃避了前方的情况”与向指挥部报告的意思不符。", "拖延": "搭配：“拖延”多搭配时间或任务，不说“拖延了情况”。"}, "sentence_index": 6, "correct_answer": "汇报"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每晚在电视上汇报天气。", "explanation": "这里应该用〈播报〉。“播报天气”是节目里的常见说法；“汇报”是向上级或有关人员报告工作或情况，不用于面向观众播报。"}, {"text": "他给孩子们汇报了一个故事。", "explanation": "这里应该用〈讲述〉。“讲述”可以用于故事；“汇报”只用于工作、情况或经过。"}, {"text": "我们一起汇报了午饭。", "explanation": "这里应该用〈吃〉。“吃午饭”是日常说法；“汇报”用于工作或情况，不能用来说吃饭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4126d464-5865-4126-bfc4-864583ec3dfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95966, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他每天主任汇报工作进展。", "corrected_sentence": "他每天向主任汇报工作进展。", "error_description": "缺少介词：“主任”前应有介词“向”，应说“他每天向主任汇报工作进展”，“汇报”不能直接带人作宾语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4126d464-5865-4126-bfc4-864583ec3dfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95966, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把情况经理汇报了。", "corrected_sentence": "他把情况向经理汇报了。", "error_description": "缺少介词：“经理”前应有介词“向”，应说“他把情况向经理汇报了”，“汇报”不能直接带人作宾语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4126d464-5865-4126-bfc4-864583ec3dfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
