INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95973, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "问名是以前结婚前，要问清楚对方的名字。", "primary_collocate": null, "pronunciation": "wèn míng", "ipa": "wən˥˩ miŋ˧˥", "syllable_count": 2, "sentences": [{"text": "古时候结婚前要先问名。", "target_word": "问名", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "以前结婚，男方家要先去问名。", "target_word": "问名", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "问名的时候，要问清楚女孩的名字。", "target_word": "问名", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "媒人去女方家问名，想知道她叫什么。", "target_word": "问名", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在以前，没有问名就不能结婚。", "target_word": "问名", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷说，他们那时候结婚前也要问名。", "target_word": "问名", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "媒人今天去她家问名，家里人很高兴。", "target_word": "问名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "问名以后，两家人才开始看日子。", "target_word": "问名", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们按老规矩，先问名，再谈别的事。", "target_word": "问名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶给我讲过以前怎么问名。", "target_word": "问名", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "問名", "label": "繁体"}], "register": "书面", "sense_fingerprint": "旧时结婚前问清对方姓名", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '985b8fb7-0352-4226-b681-027abeaba146') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95973, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "问名", "is_correct": true, "explanation": "“问名”指旧时结婚前问清对方姓名，符合句意。"}, {"text": "考驾照", "is_correct": false, "explanation": "语义：“考驾照”是现代事，与“古时候”矛盾。"}, {"text": "上网", "is_correct": false, "explanation": "语义：古时候没有网络，“上网”与句中的时代冲突。"}, {"text": "发短信", "is_correct": false, "explanation": "语义：古时候没有短信，与句中时代矛盾。"}], "explanations": {"问名": "“问名”指旧时结婚前问清对方姓名，符合句意。", "考驾照": "语义：“考驾照”是现代事，与“古时候”矛盾。", "上网": "语义：古时候没有网络，“上网”与句中的时代冲突。", "发短信": "语义：古时候没有短信，与句中时代矛盾。"}, "sentence_index": 0, "correct_answer": "问名"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师在课堂上问名同学的成绩。", "explanation": "这里应该用〈询问〉。“问名”只用于婚前问女方姓名，不能用来问学习成绩。"}, {"text": "他在电话里问名老板的工资。", "explanation": "这里应该用〈打听〉。“问名”只用于婚前问女方姓名，不能用来问工资。"}, {"text": "他每天见到老师都问名，很有礼貌。", "explanation": "这里应该用〈问候〉。“问名”是婚前问女方姓名的礼节，不能用来表示见面打招呼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8434301-4280-4f4a-9915-e743c7ff9229') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95973, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "问名", "is_correct": true, "explanation": "“问名”指婚前问清对方姓名，与“媒人去她家”和“家里人很高兴”的婚事语境相合。"}, {"text": "送货", "is_correct": false, "explanation": "语义：媒人去女方家并不是送货，与婚事语境不合。"}, {"text": "报警", "is_correct": false, "explanation": "语义：媒人上门报警与“家里人很高兴”矛盾，句意不通。"}, {"text": "维修", "is_correct": false, "explanation": "语义：媒人上门不是为了维修，句中的婚事语境与之矛盾。"}], "explanations": {"问名": "“问名”指婚前问清对方姓名，与“媒人去她家”和“家里人很高兴”的婚事语境相合。", "送货": "语义：媒人去女方家并不是送货，与婚事语境不合。", "报警": "语义：媒人上门报警与“家里人很高兴”矛盾，句意不通。", "维修": "语义：媒人上门不是为了维修，句中的婚事语境与之矛盾。"}, "sentence_index": 6, "correct_answer": "问名"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在饭馆里问名菜单上的价格。", "explanation": "这里应该用〈问价〉。“问名”只用于婚前问女方姓名，不能用来问菜单上的价格。"}, {"text": "我们在公园里问名这棵树的年龄。", "explanation": "这里应该用〈估算〉。“问名”只用于婚前问女方姓名，不能用来问树的年龄。"}, {"text": "他在考试前问名老师的生日。", "explanation": "这里应该用〈请问〉。“问名”只用于婚前问女方姓名，不能用来问老师的生日。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8434301-4280-4f4a-9915-e743c7ff9229') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95973, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "媒人昨天去女方家问名了。", "corrected_sentence": "媒人昨天去女方家问了名。", "error_description": "语序错误：“问名”作动宾用时，“了”要放在“问”和“名”之间，应为“问了名”，不能说“问名了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8434301-4280-4f4a-9915-e743c7ff9229') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95973, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们那时候也问名过。", "corrected_sentence": "他们那时候也问过名。", "error_description": "体标位置错误：动词后的“过”应紧跟在“问”后，说“问过名”，不能说“问名过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8434301-4280-4f4a-9915-e743c7ff9229') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
