INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95981, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "四处是东边、西边、前面、后面，到处。", "primary_collocate": null, "pronunciation": "sì chù", "ipa": "sɨ˥˩ ʈʂʰu˥˩", "syllable_count": 2, "sentences": [{"text": "他四处找手机，可是没找到。", "target_word": "四处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在公园里四处跑。", "target_word": "四处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我四处问路，才找到那家店。", "target_word": "四处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗在家里四处闻来闻去。", "target_word": "四处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他四处看了看，没有人。", "target_word": "四处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风一吹，纸四处飞。", "target_word": "四处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她四处寻找丢了的猫。", "target_word": "四处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他四处打听那个地方在哪儿。", "target_word": "四处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家四处走走，看看风景。", "target_word": "四处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天，蚊子在屋里四处飞。", "target_word": "四处", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副词：在各个方向、各个地方（做动作），如四处找、四处跑", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bea46ef-39b9-4ce5-886b-856ed2cce768') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95981, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "四处", "is_correct": true, "explanation": "“四处”表示在各个地方进行动作，与“找手机，可是没找到”相符。"}, {"text": "竟然", "is_correct": false, "explanation": "语义：“竟然”表示出乎意料，与“找手机没找到”的平常语境不协调。"}, {"text": "非常", "is_correct": false, "explanation": "语法：“非常”是程度副词，不能直接修饰“找”这样的动作动词。"}, {"text": "一齐", "is_correct": false, "explanation": "配价：“一齐”要求多个施事，“他一齐找手机”只有一个施事，不通顺。"}], "explanations": {"四处": "“四处”表示在各个地方进行动作，与“找手机，可是没找到”相符。", "竟然": "语义：“竟然”表示出乎意料，与“找手机没找到”的平常语境不协调。", "非常": "语法：“非常”是程度副词，不能直接修饰“找”这样的动作动词。", "一齐": "配价：“一齐”要求多个施事，“他一齐找手机”只有一个施事，不通顺。"}, "sentence_index": 0, "correct_answer": "四处"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他四处去了北京。", "explanation": "这里应该用〈前往〉。四处表示分散在各处，不能指向某一个确定的地方；去某地要说前往。"}, {"text": "他四处在家里睡觉。", "explanation": "这里应该用〈一直〉。四处表示分散在各处，不能修饰固定在一处的行为；固定在一处要说一直在某处。"}, {"text": "他一直四处站在门口。", "explanation": "这里应该用〈守在〉。四处表示分散在各处，不能修饰固定站在一处的动作；站岗式地待在一处要说守在。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b555da5e-4b5e-4652-842c-ecafaf616c3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95981, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "四处", "is_correct": true, "explanation": "“四处”表示在各个地方寻找，与“寻找丢了的猫”的语境相符。"}, {"text": "幸亏", "is_correct": false, "explanation": "搭配：“幸亏”表示庆幸，需要后接结果分句，不能直接修饰“寻找”。"}, {"text": "非常", "is_correct": false, "explanation": "语法：“非常”是程度副词，不能直接修饰“寻找”这样的动作。"}, {"text": "太", "is_correct": false, "explanation": "语法：“太”是程度副词，修饰形容词，不能直接修饰“寻找”。"}], "explanations": {"四处": "“四处”表示在各个地方寻找，与“寻找丢了的猫”的语境相符。", "幸亏": "搭配：“幸亏”表示庆幸，需要后接结果分句，不能直接修饰“寻找”。", "非常": "语法：“非常”是程度副词，不能直接修饰“寻找”这样的动作。", "太": "语法：“太”是程度副词，修饰形容词，不能直接修饰“寻找”。"}, "sentence_index": 6, "correct_answer": "四处"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "电影院里四处有一个座位。", "explanation": "这里应该用〈只有〉。四处表示分散在各处，不能用来描述只有一个座位的情况。"}, {"text": "我一下子四处把门关上了。", "explanation": "这里应该用〈随手〉。四处表示分散在各处、到处进行，不能修饰一次性、定点的关门动作；这里要说随手。"}, {"text": "这次比赛我四处拿了冠军。", "explanation": "这里应该用〈夺得〉。四处表示分散在各处进行的动作，不能修饰一次性获得的结果；获得冠军要说夺得。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b555da5e-4b5e-4652-842c-ecafaf616c3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95981, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈在厨房里四处的找钥匙。", "corrected_sentence": "妈妈在厨房里四处找钥匙。", "error_description": "错误：“四处”后多了“的”；正确：“四处找”。“四处”是副词，直接修饰动词，不能加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b555da5e-4b5e-4652-842c-ecafaf616c3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95981, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在屋里四处了找一遍。", "corrected_sentence": "他在屋里四处找了一遍。", "error_description": "错误：“四处了找”；正确：“四处找了”。“了”应紧跟动词“找”，不能放在副词“四处”之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b555da5e-4b5e-4652-842c-ecafaf616c3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
