INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95987, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "墓是人去世后，埋在地下的地方。", "primary_collocate": null, "pronunciation": "mù", "ipa": "mu˥˩", "syllable_count": 1, "sentences": [{"text": "爷爷的墓在山上。", "target_word": "墓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上有一座很老的墓。", "target_word": "墓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "清明节，我们去看奶奶的墓。", "target_word": "墓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座墓前放着一束白花。", "target_word": "墓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在墓前站了很久。", "target_word": "墓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墓里埋着一位老人。", "target_word": "墓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人去世后，家人给他修了一座墓。", "target_word": "墓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座墓很安静，旁边有很多树。", "target_word": "墓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村子后面的山上有三座墓。", "target_word": "墓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把花放在爸爸的墓前。", "target_word": "墓", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一座墓", "label": "量词"}, {"form": "坟墓", "label": "复合"}, {"form": "墓地", "label": "复合"}], "register": "中性", "sense_fingerprint": "人去世后埋在地下的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb1898af-5781-4ad1-8f77-3a10637e8fd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95987, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "墓", "is_correct": true, "explanation": "正确：“墓”指埋葬死人的地方，“爷爷的墓在山上”符合句意。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业不会埋在山上，句子说的是埋葬的地方。"}, {"text": "时间", "is_correct": false, "explanation": "语义：“时间”不是可以存放在山上的具体事物，与“爷爷的…在山上”不合。"}, {"text": "海水", "is_correct": false, "explanation": "语义：海水不会在山上，“爷爷的海水在山上”也不成立。"}], "explanations": {"墓": "正确：“墓”指埋葬死人的地方，“爷爷的墓在山上”符合句意。", "作业": "语义：作业不会埋在山上，句子说的是埋葬的地方。", "时间": "语义：“时间”不是可以存放在山上的具体事物，与“爷爷的…在山上”不合。", "海水": "语义：海水不会在山上，“爷爷的海水在山上”也不成立。"}, "sentence_index": 0, "correct_answer": "墓"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "山上有一只墓，很老了。", "explanation": "这里应该用〈座〉。墓多是较大的建筑式物体，应用“座”；“只”用于动物。"}, {"text": "爷爷住的墓在山下。", "explanation": "这里应该用〈房子〉。“住”针对房屋，墓是埋葬死人的地方，不能用来居住。"}, {"text": "孩子们在墓里上课。", "explanation": "这里应该用〈学校〉。墓是埋葬死人的地方，不是上课的场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2ee84d4-fb1b-4079-81e2-ab1f9c38f119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95987, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "墓", "is_correct": true, "explanation": "正确：“修一座墓”是常见搭配，“墓”是埋葬死人的地方。"}, {"text": "音乐", "is_correct": false, "explanation": "语义：音乐不是可以修建的建筑，句子说的是修建一个埋葬的地方。"}, {"text": "衣服", "is_correct": false, "explanation": "搭配：“衣服”可以修补，但量词“座”不能用于衣服，“修了一座衣服”不成立。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲不能被修建，也不能被埋葬，与“修了一座…”不合。"}], "explanations": {"墓": "正确：“修一座墓”是常见搭配，“墓”是埋葬死人的地方。", "音乐": "语义：音乐不是可以修建的建筑，句子说的是修建一个埋葬的地方。", "衣服": "搭配：“衣服”可以修补，但量词“座”不能用于衣服，“修了一座衣服”不成立。", "歌曲": "语义：歌曲不能被修建，也不能被埋葬，与“修了一座…”不合。"}, "sentence_index": 6, "correct_answer": "墓"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "奶奶在墓里休息了一周。", "explanation": "这里应该用〈医院〉。墓是埋葬死人的地方，不能用来休息养病。"}, {"text": "妈妈在墓里做晚饭。", "explanation": "这里应该用〈厨房〉。墓不是做饭的地方，做饭应在厨房。"}, {"text": "路边停着一辆墓，很大。", "explanation": "这里应该用〈座〉。墓应用“座”，“辆”用于车辆。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2ee84d4-fb1b-4079-81e2-ab1f9c38f119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95987, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "村口那条墓很老了。", "corrected_sentence": "村口那座墓很老了。", "error_description": "量词错误：墓应用“座”，“条”用于细长的东西，如河、路、绳子。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2ee84d4-fb1b-4079-81e2-ab1f9c38f119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95987, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们每年都在前墓献花。", "corrected_sentence": "我们每年都在墓前献花。", "error_description": "语序错误：方位词“前”应放在名词之后，说“墓前”，不能说“前墓”。正确是“在墓前献花”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2ee84d4-fb1b-4079-81e2-ab1f9c38f119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
