INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95988, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "埋葬死人的地方。", "primary_collocate": null, "pronunciation": "mù", "ipa": "mu˥˩", "syllable_count": 1, "sentences": [{"text": "这座墓是一百年前修的。", "target_word": "墓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的墓在海边。", "target_word": "墓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位老人的墓很简单。", "target_word": "墓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在墓前鞠了三个躬。", "target_word": "墓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墓前有一块大石头。", "target_word": "墓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外婆的墓离我家不远。", "target_word": "墓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们不敢走近那座旧墓。", "target_word": "墓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他死后，大家把他埋在山边的墓里。", "target_word": "墓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园旁边有一座很大的墓。", "target_word": "墓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，他还在墓前站着。", "target_word": "墓", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一座墓", "label": "量词"}, {"form": "坟墓", "label": "复合"}, {"form": "墓碑", "label": "复合"}], "register": "中性", "sense_fingerprint": "埋葬死人的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb1898af-5781-4ad1-8f77-3a10637e8fd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95988, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "墓", "is_correct": true, "explanation": "正确：“墓”是埋葬死人的地方，可以说“这座墓是一百年前修的”。"}, {"text": "歌", "is_correct": false, "explanation": "搭配：“歌”不用量词“座”，也不能说“修”歌，“这座歌是…修的”不成立。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业不是可以修建的建筑，句子说的是修建埋葬的地方。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不能被修建，句子说的是一座墓。"}], "explanations": {"墓": "正确：“墓”是埋葬死人的地方，可以说“这座墓是一百年前修的”。", "歌": "搭配：“歌”不用量词“座”，也不能说“修”歌，“这座歌是…修的”不成立。", "作业": "语义：作业不是可以修建的建筑，句子说的是修建埋葬的地方。", "空气": "语义：空气不能被修建，句子说的是一座墓。"}, "sentence_index": 0, "correct_answer": "墓"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "山脚下有一只墓，很老了。", "explanation": "这里应该用〈座〉。墓多为建筑式的大型物，应用“座”；“只”用于动物。"}, {"text": "奶奶在墓里住了一个月。", "explanation": "这里应该用〈医院〉。墓是埋葬死人的地方，不能用来住人。"}, {"text": "孩子们在墓里踢足球。", "explanation": "这里应该用〈操场〉。墓是埋葬死人的地方，不能用来踢球，踢球应在操场。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2ee84d4-fb1b-4079-81e2-ab1f9c38f119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95988, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "墓", "is_correct": true, "explanation": "正确：“那座旧墓”指旧的墓地，孩子们因此不敢走近，符合句意。"}, {"text": "树", "is_correct": false, "explanation": "搭配：树应用量词“棵”，“那座旧树”的量词搭配不当。"}, {"text": "烦恼", "is_correct": false, "explanation": "语义：“烦恼”是抽象的心理状态，不能被孩子们走近。"}, {"text": "小说", "is_correct": false, "explanation": "语义：小说是书，句子说的是孩子们不敢走近的场所或物体，与小说不合。"}], "explanations": {"墓": "正确：“那座旧墓”指旧的墓地，孩子们因此不敢走近，符合句意。", "树": "搭配：树应用量词“棵”，“那座旧树”的量词搭配不当。", "烦恼": "语义：“烦恼”是抽象的心理状态，不能被孩子们走近。", "小说": "语义：小说是书，句子说的是孩子们不敢走近的场所或物体，与小说不合。"}, "sentence_index": 6, "correct_answer": "墓"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子们在墓里玩水。", "explanation": "这里应该用〈游泳池〉。墓是埋葬死人的地方，不能用来玩水。"}, {"text": "他每天都在墓里工作。", "explanation": "这里应该用〈办公室〉。墓不是工作的场所，工作应在办公室。"}, {"text": "村口有一条墓，很大。", "explanation": "这里应该用〈座〉。墓应用“座”，“条”用于河、路等细长的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2ee84d4-fb1b-4079-81e2-ab1f9c38f119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95988, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条墓很大，很多人来参观。", "corrected_sentence": "这座墓很大，很多人来参观。", "error_description": "量词错误：墓应用“座”，“条”用于细长的东西，不能用来数墓。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2ee84d4-fb1b-4079-81e2-ab1f9c38f119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95988, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每年清明都去墓扫。", "corrected_sentence": "他每年清明都去扫墓。", "error_description": "离合词错误：“扫墓”是离合词，“扫”和“墓”的顺序不能颠倒，应说“去扫墓”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2ee84d4-fb1b-4079-81e2-ab1f9c38f119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
