INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96003, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示从过去到现在一直都不做某事，从没有做过。", "primary_collocate": null, "pronunciation": "cóng lái bù", "ipa": "tsʰʊŋ³⁵ laɪ³⁵ pu⁵¹", "syllable_count": 3, "sentences": [{"text": "我弟弟从来不吃辣的菜。", "target_word": "从来不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从来不迟到。", "target_word": "从来不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从来不喝咖啡，晚上会睡不着。", "target_word": "从来不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈从来不看电视。", "target_word": "从来不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李从来不跟别人吵架。", "target_word": "从来不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从来不坐地铁，因为我家离公司很近。", "target_word": "从来不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很健康，从来不生病。", "target_word": "从来不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷从来不用手机，只看报纸。", "target_word": "从来不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从来不说别人的坏话。", "target_word": "从来不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥从来不做饭，都在外面吃。", "target_word": "从来不", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "一直都不做某事，习惯性否定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12e20994-e992-4078-8ede-1891344b5f09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96003, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "从来不", "is_correct": true, "explanation": "正确：「从来不」表示从过去到现在一直不做，与「我弟弟……吃辣的菜」这种习惯相符。"}, {"text": "刚刚", "is_correct": false, "explanation": "语义：「刚刚」指不久前发生的一次性动作，与「吃辣的菜」这种长期习惯冲突。"}, {"text": "马上", "is_correct": false, "explanation": "语义：「马上」表示即将发生，句子里没有将来的语境。"}, {"text": "正在", "is_correct": false, "explanation": "语法：「正在」表示动作进行中，不能直接与否定副词「不」组合，句子不成立。"}], "explanations": {"从来不": "正确：「从来不」表示从过去到现在一直不做，与「我弟弟……吃辣的菜」这种习惯相符。", "刚刚": "语义：「刚刚」指不久前发生的一次性动作，与「吃辣的菜」这种长期习惯冲突。", "马上": "语义：「马上」表示即将发生，句子里没有将来的语境。", "正在": "语法：「正在」表示动作进行中，不能直接与否定副词「不」组合，句子不成立。"}, "sentence_index": 0, "correct_answer": "从来不"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我明天从来不迟到。", "explanation": "这里不能用〈从来不〉。「从来不」指从过去到现在一贯如此，不能用于明天这样的将来时间；表示将来应说「不会」。"}, {"text": "这次考试他从来不及格。", "explanation": "这里不能用〈从来不〉。「这次考试」是一次性事件，「从来不」描述的是一贯习惯，应改用「没」。"}, {"text": "这件衣服我从来不穿，每个星期都穿两次。", "explanation": "这里不能用〈从来不〉。「从来不」表示一贯不做，与「每个星期都穿两次」的经常性行为矛盾；表示很少穿应说「很少穿」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a59c85b2-e44c-4a84-af05-b463277db9d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96003, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "从来不", "is_correct": true, "explanation": "正确：「从来不」表示一贯不生病，与「他很健康」的语境相符。"}, {"text": "立即", "is_correct": false, "explanation": "语义：「立即」强调即刻发生，与「很健康」描述的长期状态不合。"}, {"text": "刚才", "is_correct": false, "explanation": "语义：「刚才」指不久前的情况，不能说明长期不生病。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：「忽然」表示突然出现的变化，与「很健康」的稳定状态冲突。"}], "explanations": {"从来不": "正确：「从来不」表示一贯不生病，与「他很健康」的语境相符。", "立即": "语义：「立即」强调即刻发生，与「很健康」描述的长期状态不合。", "刚才": "语义：「刚才」指不久前的情况，不能说明长期不生病。", "忽然": "语义：「忽然」表示突然出现的变化，与「很健康」的稳定状态冲突。"}, "sentence_index": 6, "correct_answer": "从来不"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "请你从来不要再说这种话！", "explanation": "这里不能用〈从来不〉。「从来不」只陈述一贯的事实，不能用于命令或劝阻；劝阻应说「千万别」。"}, {"text": "我已经吃饱了，从来不吃了。", "explanation": "这里应该用〈不再〉。「从来不」指过去到现在一贯如此，不能表示从此停止。"}, {"text": "这个周末我妹妹从来不去商场。", "explanation": "这里不能用〈从来不〉。「这个周末」是具体的时间段，「从来不」说的是长期习惯，两者不配合。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a59c85b2-e44c-4a84-af05-b463277db9d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96003, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我奶奶很从来不喝酒。", "corrected_sentence": "我奶奶从来不喝酒。", "error_description": "错误：「从来不」是副词，前面不能加程度副词「很」，应去掉「很」，说「从来不喝酒」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a59c85b2-e44c-4a84-af05-b463277db9d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96003, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我姐姐从来不了喝咖啡。", "corrected_sentence": "我姐姐从来不喝咖啡。", "error_description": "错误：「从来不」后面多加了「了」。「不」后面不能直接加「了」，应去掉「了」，说「从来不喝咖啡」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a59c85b2-e44c-4a84-af05-b463277db9d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
