INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96004, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示从过去到现在一直不做某事。", "primary_collocate": null, "pronunciation": "cóng lái bù", "ipa": "tsʰʊŋ³⁵ laɪ³⁵ pu⁵¹", "syllable_count": 3, "sentences": [{"text": "他从来不抽烟，也不喝酒。", "target_word": "从来不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从来不在晚上吃甜的东西。", "target_word": "从来不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师从来不大声说话。", "target_word": "从来不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们家从来不放鞭炮。", "target_word": "从来不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从来不骗人，大家都相信他。", "target_word": "从来不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从来不化妆，但是很漂亮。", "target_word": "从来不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从来不玩儿游戏，觉得很浪费时间。", "target_word": "从来不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王先生从来不开车上班，每天骑自行车。", "target_word": "从来不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子从来不吃青菜，妈妈很着急。", "target_word": "从来不", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶从来不浪费粮食。", "target_word": "从来不", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "从过去到现在一直不做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12e20994-e992-4078-8ede-1891344b5f09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96004, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "从来不", "is_correct": true, "explanation": "正确：「从来不」表示从过去到现在一直不做某事，与「他……不抽烟，也不喝酒」相符。"}, {"text": "刚刚", "is_correct": false, "explanation": "语义：「刚刚」指不久前的一次性动作，不能说明长期戒烟戒酒的习惯。"}, {"text": "正在", "is_correct": false, "explanation": "语法：「正在」表示动作进行中，不能直接与否定副词「不」组合，句子不成立。"}, {"text": "当场", "is_correct": false, "explanation": "语义：「当场」指当时当地发生的动作，与「抽烟、喝酒」这种一贯习惯不合。"}], "explanations": {"从来不": "正确：「从来不」表示从过去到现在一直不做某事，与「他……不抽烟，也不喝酒」相符。", "刚刚": "语义：「刚刚」指不久前的一次性动作，不能说明长期戒烟戒酒的习惯。", "正在": "语法：「正在」表示动作进行中，不能直接与否定副词「不」组合，句子不成立。", "当场": "语义：「当场」指当时当地发生的动作，与「抽烟、喝酒」这种一贯习惯不合。"}, "sentence_index": 0, "correct_answer": "从来不"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们家昨天从来不放鞭炮，大家都很惊讶。", "explanation": "这里不能用〈从来不〉。「昨天」是一次性时间，「从来不」描述的是一贯习惯，应改说「昨天没放」。"}, {"text": "明年我们家从来不放鞭炮。", "explanation": "这里不能用〈从来不〉。「从来不」指从过去到现在的一贯情况，不能用于明年这样的将来时间。"}, {"text": "我们家从来不放鞭炮，每年春节都放。", "explanation": "这里不能用〈从来不〉。「从来不」表示一贯不做，与「每年春节都放」的习惯矛盾；表示只在特定节日放，应说「只在春节放」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a59c85b2-e44c-4a84-af05-b463277db9d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96004, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "从来不", "is_correct": true, "explanation": "正确：「从来不」表示一贯不玩儿游戏，与「觉得很浪费时间」的态度相符。"}, {"text": "马上", "is_correct": false, "explanation": "语义：「马上」表示即将发生，句子里没有将来的语境，与一贯的态度不合。"}, {"text": "刚才", "is_correct": false, "explanation": "语义：「刚才」指不久前的一次性情况，不能说明长期的习惯。"}, {"text": "竟然", "is_correct": false, "explanation": "语义：「竟然」表示出乎意料，与「我」一贯不玩游戏的平常习惯不符。"}], "explanations": {"从来不": "正确：「从来不」表示一贯不玩儿游戏，与「觉得很浪费时间」的态度相符。", "马上": "语义：「马上」表示即将发生，句子里没有将来的语境，与一贯的态度不合。", "刚才": "语义：「刚才」指不久前的一次性情况，不能说明长期的习惯。", "竟然": "语义：「竟然」表示出乎意料，与「我」一贯不玩游戏的平常习惯不符。"}, "sentence_index": 6, "correct_answer": "从来不"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "请你们从来不要浪费粮食！", "explanation": "这里不能用〈从来不〉。「从来不」只陈述一贯的事实，不能用于命令或劝阻；劝阻应说「千万别」。"}, {"text": "我已经吃饱了，从来不吃了。", "explanation": "这里应该用〈不再〉。「从来不」指过去到现在一贯如此，不能表示从此停止。"}, {"text": "这个周末奶奶从来不浪费粮食。", "explanation": "这里不能用〈从来不〉。「这个周末」是具体的时间段，「从来不」说的是长期习惯，两者不配合。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a59c85b2-e44c-4a84-af05-b463277db9d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96004, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "姥姥从来不了喝牛奶。", "corrected_sentence": "姥姥从来不喝牛奶。", "error_description": "错误：「从来不」后面多加了「了」。「不」后面不能直接加「了」，应去掉「了」，说「从来不喝牛奶」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a59c85b2-e44c-4a84-af05-b463277db9d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96004, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "外婆很从来不熬夜。", "corrected_sentence": "外婆从来不熬夜。", "error_description": "错误：「从来不」是副词，前面不能加程度副词「很」，应去掉「很」，说「从来不熬夜」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a59c85b2-e44c-4a84-af05-b463277db9d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
