INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96008, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "开始喜爱上某人或某事物。", "primary_collocate": null, "pronunciation": "ài shàng", "ipa": "aɪ˥˩ ʂɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "听了一次音乐会，他爱上了小提琴。", "target_word": "爱上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟爱上了画画，每天都画。", "target_word": "爱上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我爱上了这座小山村。", "target_word": "爱上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她爱上了同班的男同学。", "target_word": "爱上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "来北京以后，我爱上了冬天。", "target_word": "爱上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就爱上了唱歌。", "target_word": "爱上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多外国人爱上了中国的茶。", "target_word": "爱上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她怎么会爱上这么冷的地方？", "target_word": "爱上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸爱上了钓鱼，周末总不在家。", "target_word": "爱上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没想到会爱上这份工作。", "target_word": "爱上", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "爱上了", "label": "体标"}, {"form": "爱上过", "label": "体标"}], "register": "中性", "sense_fingerprint": "开始喜爱某人或某事物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb1898af-5781-4ad1-8f77-3a10637e8fd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96008, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "爱上", "is_correct": true, "explanation": "爱上（ài shàng）：开始喜爱，正确答案。"}, {"text": "哀伤", "is_correct": false, "explanation": "āi shāng 与 ài shàng 两个音节的声调都不同，意思是悲伤。"}, {"text": "挨上", "is_correct": false, "explanation": "āi shàng（第一声）与 ài shàng（第四声）声调不同，意思是碰上、挨到。"}, {"text": "挨伤", "is_correct": false, "explanation": "āi shāng 与 ài shàng 两个音节的声调都不同，意思是被打伤。"}, {"text": "拜上", "is_correct": false, "explanation": "bài 与 ài 声母不同（b 与零声母），意思是书信用语「拜上」，即恭敬地致意。"}], "explanations": {"爱上": "爱上（ài shàng）：开始喜爱，正确答案。", "哀伤": "āi shāng 与 ài shàng 两个音节的声调都不同，意思是悲伤。", "挨上": "āi shàng（第一声）与 ài shàng（第四声）声调不同，意思是碰上、挨到。", "挨伤": "āi shāng 与 ài shàng 两个音节的声调都不同，意思是被打伤。", "拜上": "bài 与 ài 声母不同（b 与零声母），意思是书信用语「拜上」，即恭敬地致意。"}, "sentence_index": null, "correct_answer": "爱上"}, "level_3": {"options": [{"text": "爱上", "is_correct": true, "explanation": "爱上：听了音乐会后开始喜欢，与句意相符。"}, {"text": "养成", "is_correct": false, "explanation": "搭配：「养成」后接习惯，不能用于乐器。"}, {"text": "吞下", "is_correct": false, "explanation": "语义：「吞下」指咽下去，与「听了一次音乐会」的语境不符。"}, {"text": "辞退", "is_correct": false, "explanation": "搭配：「辞退」用于人员，不能用于小提琴。"}], "explanations": {"爱上": "爱上：听了音乐会后开始喜欢，与句意相符。", "养成": "搭配：「养成」后接习惯，不能用于乐器。", "吞下": "语义：「吞下」指咽下去，与「听了一次音乐会」的语境不符。", "辞退": "搭配：「辞退」用于人员，不能用于小提琴。"}, "sentence_index": 0, "correct_answer": "爱上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天都爱上这首歌。", "explanation": "这里应该用〈喜欢〉。“爱上”强调开始喜欢的那一刻，与“每天都”搭配别扭；经常性的喜欢应说“每天都喜欢”。"}, {"text": "他爱上了下午三点。", "explanation": "这里应该用〈盼望〉。爱上的对象是人、事物或活动，表示开始喜欢；对尚未到来的时刻抱有期盼，应用〈盼望〉。"}, {"text": "她爱上了这场大病。", "explanation": "这里应该用〈患上〉。“爱上”的对象是人或事物，并表示开始喜欢；得病应说“患上”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2ee84d4-fb1b-4079-81e2-ab1f9c38f119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96008, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "爱上", "is_correct": true, "explanation": "爱上（ài shàng）：开始喜爱，正确答案。"}, {"text": "带上", "is_correct": false, "explanation": "dài 与 ài 声母不同（d 与零声母），意思是带着、戴上。"}, {"text": "派上", "is_correct": false, "explanation": "pài 与 ài 声母不同（p 与零声母），意思是派上用场。"}, {"text": "盖上", "is_correct": false, "explanation": "gài 与 ài 声母不同（g 与零声母），意思是盖上、覆盖。"}, {"text": "赖上", "is_correct": false, "explanation": "lài 与 ài 声母不同（l 与零声母），意思是纠缠、赖着。"}], "explanations": {"爱上": "爱上（ài shàng）：开始喜爱，正确答案。", "带上": "dài 与 ài 声母不同（d 与零声母），意思是带着、戴上。", "派上": "pài 与 ài 声母不同（p 与零声母），意思是派上用场。", "盖上": "gài 与 ài 声母不同（g 与零声母），意思是盖上、覆盖。", "赖上": "lài 与 ài 声母不同（l 与零声母），意思是纠缠、赖着。"}, "sentence_index": null, "correct_answer": "爱上"}, "level_3": {"options": [{"text": "爱上", "is_correct": true, "explanation": "爱上：外国人开始喜欢中国的茶，与句意相符。"}, {"text": "辞掉", "is_correct": false, "explanation": "搭配：「辞掉」用于工作、职位，不能用于茶。"}, {"text": "驱逐", "is_correct": false, "explanation": "语义：「驱逐」指赶走人或物，与「喜欢」的句意相反。"}, {"text": "提拔", "is_correct": false, "explanation": "搭配：「提拔」用于人员，不能用于茶。"}], "explanations": {"爱上": "爱上：外国人开始喜欢中国的茶，与句意相符。", "辞掉": "搭配：「辞掉」用于工作、职位，不能用于茶。", "驱逐": "语义：「驱逐」指赶走人或物，与「喜欢」的句意相反。", "提拔": "搭配：「提拔」用于人员，不能用于茶。"}, "sentence_index": 6, "correct_answer": "爱上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我一直爱上这座城市。", "explanation": "这里应该用〈向往〉。爱上表示开始喜欢的变化，不能与「一直」连用表示持续的状态。"}, {"text": "他爱上了这场车祸。", "explanation": "这里应该用〈遭遇〉。“爱上”表示喜欢某人或某事物，不能用于意外事故；遭遇车祸应说“遭遇”。"}, {"text": "我爱上这种虚伪。", "explanation": "这里应该用〈厌恶〉。爱上表示开始喜欢，与「厌恶」感情相反；对虚伪这类让人反感的事物，应用〈厌恶〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2ee84d4-fb1b-4079-81e2-ab1f9c38f119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96008, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈后来爱上着跳舞。", "corrected_sentence": "妈妈后来爱上了跳舞。", "error_description": "错误：「着」接在「爱上」后，表示动作持续进行，而「爱上」是开始喜爱的瞬间变化，不能用「着」。正确：「爱上了跳舞」，用「了」表示变化已经发生。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2ee84d4-fb1b-4079-81e2-ab1f9c38f119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96008, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她第一次去海边，就把爱上了大海。", "corrected_sentence": "她第一次去海边，就爱上了大海。", "error_description": "错误：多加了「把」。「把」字句要求「把＋宾语＋动词」，而这里「爱上」后已带宾语「大海」，不能再用「把」。正确：「就爱上了大海」，去掉「把」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2ee84d4-fb1b-4079-81e2-ab1f9c38f119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
