INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96014, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "客套话，表示恳切地请求别人帮助。", "primary_collocate": null, "pronunciation": "bài tuō", "ipa": "pai̯˥˩ tʰuɔ˥", "syllable_count": 2, "sentences": [{"text": "拜托了，请把门关上。", "target_word": "拜托", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "拜托您给我一点时间。", "target_word": "拜托", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "拜托您，明天一定把这份文件交给经理。", "target_word": "拜托", "complexity_tier": "T3", "furigana": "bài tuō nín míng tiān yí dìng bǎ zhè fèn wén jiàn jiāo gěi jīng lǐ", "sentence_source": "generated"}, {"text": "孩子们就拜托你照顾了。", "target_word": "拜托", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "拜托，请让我先下车。", "target_word": "拜托", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "拜托各位，明天一定要准时到。", "target_word": "拜托", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "拜托啦，我把钥匙放在桌上了，你帮我看着家。", "target_word": "拜托", "complexity_tier": "T3", "furigana": "bài tuō la wǒ bǎ yào shi fàng zài zhuō shàng le nǐ bāng wǒ kān zhe jiā", "sentence_source": "generated"}, {"text": "拜托您再说一遍，我没听清楚。", "target_word": "拜托", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "临走前，他一直说：拜托了，我妈妈就交给你了。", "target_word": "拜托", "complexity_tier": "T3", "furigana": "lín zǒu qián tā yì zhí shuō bài tuō le wǒ mā ma jiù jiāo gěi nǐ le", "sentence_source": "generated"}, {"text": "拜托，你跟他说一声，我今晚不回家吃饭。", "target_word": "拜托", "complexity_tier": "T3", "furigana": "bài tuō nǐ gēn tā shuō yì shēng wǒ jīn wǎn bù huí jiā chī fàn", "sentence_source": "generated"}], "morphological_forms": [{"form": "拜托了", "label": "体标"}, {"form": "拜托过", "label": "体标"}], "register": "口语", "sense_fingerprint": "客套话，恳切地请求", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bea46ef-39b9-4ce5-886b-856ed2cce768') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96014, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拜托", "is_correct": true, "explanation": "动词，客套地请求，与“请把门关上”的请求相符。"}, {"text": "感谢", "is_correct": false, "explanation": "配价：“感谢”需要带受谢的对象，“感谢了”后面没有所谢之人，句子不完整。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝”与“请把门关上”的请求矛盾。"}, {"text": "恭喜", "is_correct": false, "explanation": "语义：“恭喜”表示庆贺，与句中的请求不符。"}], "explanations": {"拜托": "动词，客套地请求，与“请把门关上”的请求相符。", "感谢": "配价：“感谢”需要带受谢的对象，“感谢了”后面没有所谢之人，句子不完整。", "拒绝": "语义：“拒绝”与“请把门关上”的请求矛盾。", "恭喜": "语义：“恭喜”表示庆贺，与句中的请求不符。"}, "sentence_index": 0, "correct_answer": "拜托"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "拜托你新年快乐。", "explanation": "这里应该用〈祝〉。拜托是请人帮忙，祝福别人要用“祝”，不能用“拜托”。"}, {"text": "周末我们拜托朋友去爬山。", "explanation": "这里应该用〈邀请〉。“拜托”表示请人帮忙，约朋友一起活动要说“邀请”。"}, {"text": "见面时我拜托你早上好。", "explanation": "这里应该用〈问候〉。“拜托”是请人帮忙，向人问候要说“问好”，不能用“拜托”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b555da5e-4b5e-4652-842c-ecafaf616c3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96014, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拜托", "is_correct": true, "explanation": "动词，客套地请托，与“你帮我看着家”的请求一致。"}, {"text": "报告", "is_correct": false, "explanation": "语义：“报告”是陈述情况，不是请求，与“你帮我看着家”的托付不合。"}, {"text": "批评", "is_correct": false, "explanation": "语义：“批评”含有指责的意味，与语气亲切的“拜托啦”矛盾。"}, {"text": "通知", "is_correct": false, "explanation": "语义：“通知”只是告知情况，而后句“你帮我看着家”是请人托付的请求，二者不合。"}], "explanations": {"拜托": "动词，客套地请托，与“你帮我看着家”的请求一致。", "报告": "语义：“报告”是陈述情况，不是请求，与“你帮我看着家”的托付不合。", "批评": "语义：“批评”含有指责的意味，与语气亲切的“拜托啦”矛盾。", "通知": "语义：“通知”只是告知情况，而后句“你帮我看着家”是请人托付的请求，二者不合。"}, "sentence_index": 6, "correct_answer": "拜托"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "拜托，让你久等了，我真的很抱歉。", "explanation": "这里应该用〈抱歉〉。“拜托”是请人帮忙，向别人表示歉意要说“抱歉”。"}, {"text": "这天气真好，我拜托它明天晴朗。", "explanation": "这里应该用〈希望〉。拜托只用于能听从请求的人，对天气只能说“希望”。"}, {"text": "拜托你考上了大学，我很高兴。", "explanation": "这里应该用〈祝贺〉。“拜托”是请人帮忙，庆贺别人的成功要用“祝贺”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b555da5e-4b5e-4652-842c-ecafaf616c3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96014, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "拜托地您，请帮我把这封信寄出去。", "corrected_sentence": "拜托您，请帮我把这封信寄出去。", "error_description": "错误：“地”不能放在“拜托”后面。“拜托”是动词，应直接说“拜托您”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b555da5e-4b5e-4652-842c-ecafaf616c3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96014, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "拜托了您再帮我看一看这份资料。", "corrected_sentence": "拜托您再帮我看一看这份资料。", "error_description": "错误：“了”放在了“您”前面。“拜托”后面的“了”应放在句末，应说“拜托您了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b555da5e-4b5e-4652-842c-ecafaf616c3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
