INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96026, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "普遍地调查，对全部对象逐一调查。", "primary_collocate": null, "pronunciation": "pǔ chá", "ipa": "pʰu˨˩˧ ʈʂʰa˧˥", "syllable_count": 2, "sentences": [{"text": "国家每十年普查一次人口。", "target_word": "普查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个县普查了所有的农田。", "target_word": "普查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院普查了全市孩子的牙齿。", "target_word": "普查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了知道有多少人，政府决定普查全市。", "target_word": "普查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市里准备普查全部的老房子。", "target_word": "普查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们正在普查这座山里的鸟。", "target_word": "普查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校普查过一次，全校的学生都量了体重。", "target_word": "普查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要普查全城的树，得花很多时间。", "target_word": "普查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校普查了全校学生的近视情况。", "target_word": "普查", "complexity_tier": "T3", "furigana": "xué xiào pǔ chá le quán xiào xué shēng de jìn shì qíng kuàng.", "sentence_source": "generated"}, {"text": "工人们普查了全市的每一座桥梁。", "target_word": "普查", "complexity_tier": "T3", "furigana": "gōng rén men pǔ chá le quán shì de měi yí zuò qiáo liáng.", "sentence_source": "generated"}], "morphological_forms": [{"form": "普查了", "label": "体标"}, {"form": "普查过", "label": "体标"}, {"form": "人口普查", "label": "复合"}], "register": "书面", "sense_fingerprint": "对全部对象普遍调查", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb1898af-5781-4ad1-8f77-3a10637e8fd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96026, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "普查", "is_correct": true, "explanation": "普查：对全部对象逐一调查，与「国家每十年……一次人口」相符。"}, {"text": "粉刷", "is_correct": false, "explanation": "搭配：「粉刷」用于墙面等，不能用于人口。"}, {"text": "浇灌", "is_correct": false, "explanation": "搭配：「浇灌」用于植物、庄稼，不能用于人口。"}, {"text": "消灭", "is_correct": false, "explanation": "语义：「消灭」指彻底除掉，与「每十年调查一次」的目的相反。"}], "explanations": {"普查": "普查：对全部对象逐一调查，与「国家每十年……一次人口」相符。", "粉刷": "搭配：「粉刷」用于墙面等，不能用于人口。", "浇灌": "搭配：「浇灌」用于植物、庄稼，不能用于人口。", "消灭": "语义：「消灭」指彻底除掉，与「每十年调查一次」的目的相反。"}, "sentence_index": 0, "correct_answer": "普查"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "护士普查了这个病人的心脏。", "explanation": "这里应该用〈检查〉。普查指对大批对象逐一调查，只针对一个病人时应用〈检查〉。"}, {"text": "老师普查了一部分学生的作业。", "explanation": "这里应该用〈抽查〉。普查要求对全部对象逐一调查，只查一部分时应用〈抽查〉。"}, {"text": "我认真普查了我的未来。", "explanation": "这里应该用〈思考〉。普查用于可统计的对象，未来不能普查，应用〈思考〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2ee84d4-fb1b-4079-81e2-ab1f9c38f119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96026, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "普查", "is_correct": true, "explanation": "普查：全校学生逐一参与，与「全校的学生都量了体重」相符。"}, {"text": "抽查", "is_correct": false, "explanation": "语义：「抽查」只检查一部分，与「全校的学生都」相矛盾。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：「洗」用于衣物、身体等，不能用于学校。"}, {"text": "烫", "is_correct": false, "explanation": "搭配：「烫」用于衣物，不能用于学校。"}], "explanations": {"普查": "普查：全校学生逐一参与，与「全校的学生都量了体重」相符。", "抽查": "语义：「抽查」只检查一部分，与「全校的学生都」相矛盾。", "洗": "搭配：「洗」用于衣物、身体等，不能用于学校。", "烫": "搭配：「烫」用于衣物，不能用于学校。"}, "sentence_index": 6, "correct_answer": "普查"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天都普查我的房间。", "explanation": "这里应该用〈打扫〉。普查针对大批对象逐一调查，一间房不适用「普查」；日常清理应用〈打扫〉。"}, {"text": "我们普查了这场音乐会。", "explanation": "这里应该用〈观看〉。普查针对可统计的对象，音乐会不能普查，应用〈观看〉。"}, {"text": "经理普查了一封信。", "explanation": "这里应该用〈阅读〉。普查指对大批对象逐一调查，只读一封信时应用〈阅读〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2ee84d4-fb1b-4079-81e2-ab1f9c38f119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96026, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府很普查了全国的土地。", "corrected_sentence": "政府普查了全国的土地。", "error_description": "错误：程度副词「很」修饰动词「普查」。正确：去掉「很」，「普查」是动作动词，不能被程度副词修饰。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2ee84d4-fb1b-4079-81e2-ab1f9c38f119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96026, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们没普查了全区的每一家药店。", "corrected_sentence": "我们普查了全区的每一家药店。", "error_description": "错误：否定句中加了「没」，又保留了「了」，写成「没普查了」。正确：否定时动词后不带「了」，应说「没普查」；肯定句则说「普查了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2ee84d4-fb1b-4079-81e2-ab1f9c38f119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
