INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96031, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "某人是不说名字，指一个人。", "primary_collocate": null, "pronunciation": "mǒu rén", "ipa": "mou˨˩˦ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "房间里的某人一直在小声唱歌。", "target_word": "某人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "某人今天早上又忘了带钥匙。", "target_word": "某人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想给某人买一份生日礼物，先不告诉你。", "target_word": "某人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事里有某人，你猜是谁？", "target_word": "某人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨晚某人睡着了，没有听到电话。", "target_word": "某人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "某人最喜欢在周末睡到中午。", "target_word": "某人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这封信交给某人，他会明白的。", "target_word": "某人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他笑着说，某人其实很爱吃甜的东西。", "target_word": "某人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们都在等某人来开门。", "target_word": "某人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "某人看过这本书三遍，还是看不懂。", "target_word": "某人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "不点名地指代某一个人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f70932a1-bdd7-4a4c-af20-13ec35292e99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96031, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "某人", "is_correct": true, "explanation": "正确：“某人”指说话人不点名的某一个人，符合“房间里的……一直在唱歌”的语境。"}, {"text": "谁", "is_correct": false, "explanation": "语义：“谁”是疑问代词，“房间里的谁一直在唱歌”读来像提问，不指一个不点名的人。"}, {"text": "它", "is_correct": false, "explanation": "语义：“它”多指事物或动物，不能指在房间里唱歌的人。"}, {"text": "自己", "is_correct": false, "explanation": "搭配：“房间里的自己”不成立，“自己”不能这样受修饰来指称唱歌的人。"}], "explanations": {"某人": "正确：“某人”指说话人不点名的某一个人，符合“房间里的……一直在唱歌”的语境。", "谁": "语义：“谁”是疑问代词，“房间里的谁一直在唱歌”读来像提问，不指一个不点名的人。", "它": "语义：“它”多指事物或动物，不能指在房间里唱歌的人。", "自己": "搭配：“房间里的自己”不成立，“自己”不能这样受修饰来指称唱歌的人。"}, "sentence_index": 0, "correct_answer": "某人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一本某人。", "explanation": "这里应该用〈书〉。“某人”指人，不能用来指书，也不能与“本”组合。"}, {"text": "这间教室是某人。", "explanation": "这里应该用〈教室〉。“某人”指人，不能用来指地方。"}, {"text": "今天的天气很某人。", "explanation": "这里应该用〈晴朗〉。“某人”指人，不能用来形容天气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6857f85e-9171-4d03-8bfd-cc4d9981e1f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96031, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "某人", "is_correct": true, "explanation": "正确：“某人”指一个不确定的人，符合“请把这封信交给……，他会明白的”的语境。"}, {"text": "咱们", "is_correct": false, "explanation": "语义：“咱们”包括说话人自己，“交给咱们”后又说“他会明白”，指代前后矛盾。"}, {"text": "你们", "is_correct": false, "explanation": "语义：“你们”是复数，与后句单数的“他”指代不一致。"}, {"text": "各位", "is_correct": false, "explanation": "搭配：“交给各位”指向全体听众，不用于递送一封私人信件。"}], "explanations": {"某人": "正确：“某人”指一个不确定的人，符合“请把这封信交给……，他会明白的”的语境。", "咱们": "语义：“咱们”包括说话人自己，“交给咱们”后又说“他会明白”，指代前后矛盾。", "你们": "语义：“你们”是复数，与后句单数的“他”指代不一致。", "各位": "搭配：“交给各位”指向全体听众，不用于递送一封私人信件。"}, "sentence_index": 6, "correct_answer": "某人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "某人是北京的一条街。", "explanation": "这里应该用〈王府井大街〉。“某人”指人，不能用作街道名称。"}, {"text": "某人叫王老师。", "explanation": "这里应该用〈那个人〉。“某人”是不说名字的指代，这里却说出了名字，前后矛盾。"}, {"text": "他把某人扔进了垃圾桶。", "explanation": "这里应该用〈那袋垃圾〉。“某人”指人，不能像物品那样被扔掉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6857f85e-9171-4d03-8bfd-cc4d9981e1f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96031, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我猜一个某人已经回家了。", "corrected_sentence": "我猜某人已经回家了。", "error_description": "错误：“某人”是代词，不能与数量词“一个”组合；应直接说“某人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6857f85e-9171-4d03-8bfd-cc4d9981e1f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96031, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他说某人们还在图书馆里看书。", "corrected_sentence": "他说某人还在图书馆里看书。", "error_description": "错误：“某人”只指一个不确定的人，不能加“们”；应改为“某人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6857f85e-9171-4d03-8bfd-cc4d9981e1f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
