INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96032, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "指不确定或不愿说出名字的人。", "primary_collocate": null, "pronunciation": "mǒu rén", "ipa": "mou˨˩˦ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "昨天某人在会上说了一句很奇怪的话。", "target_word": "某人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说某人偷偷拿走了我的笔。", "target_word": "某人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不想说名字，只说某人帮了他很多。", "target_word": "某人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我知道是某人把窗户打开的，但我不说。", "target_word": "某人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上写着，某人昨晚在公园里丢了钱包。", "target_word": "某人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师没有说名字，只说某人今天又迟到了。", "target_word": "某人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "某人吃了我的蛋糕，现在还不承认。", "target_word": "某人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他提到某人的时候，脸一下子红了。", "target_word": "某人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不愿说出名字，只说某人对她很不好。", "target_word": "某人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要在别人面前说某人的坏话。", "target_word": "某人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "指不确定或不愿说出名字的某个人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f70932a1-bdd7-4a4c-af20-13ec35292e99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96032, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "某人", "is_correct": true, "explanation": "正确：“某人”指说话人不确定或不愿说出名字的人，符合“说了一句很奇怪的话”的语境。"}, {"text": "它", "is_correct": false, "explanation": "语义：“它”多指事物或动物，不能指在会上说话的人。"}, {"text": "谁", "is_correct": false, "explanation": "语义：“谁”是疑问代词，放在陈述句里读来像提问，不能直接指代一个未说出名字的人。"}, {"text": "各位", "is_correct": false, "explanation": "搭配：“各位”是对听众的称呼，不能充当叙述句中说话的主语。"}], "explanations": {"某人": "正确：“某人”指说话人不确定或不愿说出名字的人，符合“说了一句很奇怪的话”的语境。", "它": "语义：“它”多指事物或动物，不能指在会上说话的人。", "谁": "语义：“谁”是疑问代词，放在陈述句里读来像提问，不能直接指代一个未说出名字的人。", "各位": "搭配：“各位”是对听众的称呼，不能充当叙述句中说话的主语。"}, "sentence_index": 0, "correct_answer": "某人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们明天去某人旅游。", "explanation": "这里应该用〈某地〉。“某人”指人，不能作为旅游的地点，要说“某地”。"}, {"text": "某人是中国的首都。", "explanation": "这里应该用〈北京〉。“某人”指不确定或不愿说出名字的人，不能用作地名。"}, {"text": "今天的天气很某人。", "explanation": "这里应该用〈晴朗〉。“某人”指人，不能用来形容天气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6857f85e-9171-4d03-8bfd-cc4d9981e1f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96032, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "某人", "is_correct": true, "explanation": "正确：“某人”指说话人不愿说出名字的人，符合“吃了我的蛋糕，还不承认”的语境。"}, {"text": "我", "is_correct": false, "explanation": "语义：句中“我的蛋糕”表明说话人是失主，“我吃了我的蛋糕”却还不承认，与语境矛盾。"}, {"text": "咱们", "is_correct": false, "explanation": "语义：“咱们”包括听话人，说“咱们吃了我的蛋糕”与“我的蛋糕”的所有权不符。"}, {"text": "自己", "is_correct": false, "explanation": "搭配：“自己”作主语需要前文的先行语，此句没有指代对象。"}], "explanations": {"某人": "正确：“某人”指说话人不愿说出名字的人，符合“吃了我的蛋糕，还不承认”的语境。", "我": "语义：句中“我的蛋糕”表明说话人是失主，“我吃了我的蛋糕”却还不承认，与语境矛盾。", "咱们": "语义：“咱们”包括听话人，说“咱们吃了我的蛋糕”与“我的蛋糕”的所有权不符。", "自己": "搭配：“自己”作主语需要前文的先行语，此句没有指代对象。"}, "sentence_index": 6, "correct_answer": "某人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "某人是世界上最高的山。", "explanation": "这里应该用〈珠穆朗玛峰〉。“某人”指不知名的人，不能用来指山。"}, {"text": "某人叫王老师。", "explanation": "这里应该用〈那个人〉。“某人”是不说名字的指代，这里却说出了名字，前后矛盾。"}, {"text": "他把某人放在桌子上。", "explanation": "这里应该用〈这本书〉。“某人”指人，不能像物品那样被放在桌上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6857f85e-9171-4d03-8bfd-cc4d9981e1f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96032, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "据说某人们昨天来过办公室。", "corrected_sentence": "据说某人昨天来过办公室。", "error_description": "错误：“某人”是单数的不定指代，不能加“们”变成复数；应改为“某人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6857f85e-9171-4d03-8bfd-cc4d9981e1f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96032, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一个某人昨天来过办公室，没有留下名字。", "corrected_sentence": "某人昨天来过办公室，没有留下名字。", "error_description": "错误：“某人”是代词，不能与数量词“一个”组合；应直接说“某人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6857f85e-9171-4d03-8bfd-cc4d9981e1f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
