INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96036, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "张贴的名单或文告，如成绩榜。", "primary_collocate": null, "pronunciation": "bǎng", "ipa": "paŋ˨˩˦", "syllable_count": 1, "sentences": [{"text": "考试成绩已经贴在榜上了。", "target_word": "榜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下周一老师会把成绩贴在榜上。", "target_word": "榜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家排着队，一个一个地看榜。", "target_word": "榜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古时候，考中的人名字会写在榜上。", "target_word": "榜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "县城的路口贴着一张榜，写着新规定。", "target_word": "榜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看到榜上有自己的名字，高兴极了。", "target_word": "榜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "榜上的第一名是一个小女孩。", "target_word": "榜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教室后面的榜每个月换一次。", "target_word": "榜", "complexity_tier": "T3", "furigana": "jiào shì hòu miàn de bǎng měi gè yuè huàn yí cì", "sentence_source": "generated"}, {"text": "她不敢去看榜，怕没有考上。", "target_word": "榜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "榜前站满了等消息的家长。", "target_word": "榜", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一张榜", "label": "量词"}], "register": "中性", "sense_fingerprint": "张贴的名单或文告", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bea46ef-39b9-4ce5-886b-856ed2cce768') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96036, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "榜", "is_correct": true, "explanation": "正确。榜（bǎng）指张贴的名单或文告。"}, {"text": "棒", "is_correct": false, "explanation": "榜（第三声）与棒（第四声）声调不同，棒意思是棍子或很好。"}, {"text": "帮", "is_correct": false, "explanation": "榜（第三声）与帮（第一声）声调不同，帮意思是帮助。"}, {"text": "板", "is_correct": false, "explanation": "榜与板的韵母不同（ang 与 an），板意思是木板。"}, {"text": "旁", "is_correct": false, "explanation": "榜（第三声）与旁（第二声）声调不同，旁意思是旁边。"}], "explanations": {"榜": "正确。榜（bǎng）指张贴的名单或文告。", "棒": "榜（第三声）与棒（第四声）声调不同，棒意思是棍子或很好。", "帮": "榜（第三声）与帮（第一声）声调不同，帮意思是帮助。", "板": "榜与板的韵母不同（ang 与 an），板意思是木板。", "旁": "榜（第三声）与旁（第二声）声调不同，旁意思是旁边。"}, "sentence_index": null, "correct_answer": "榜"}, "level_3": {"options": [{"text": "榜", "is_correct": true, "explanation": "正确。“贴在榜上”指把成绩贴在公开张贴的名单上。"}, {"text": "天空", "is_correct": false, "explanation": "语义：考试成绩是公开张贴的名单，不能贴在天空上。"}, {"text": "面包", "is_correct": false, "explanation": "语义：成绩不能贴在面包上，面包不是可以张贴东西的平面。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“贴在…上”需要有平面的载体，不能说贴在空气上。"}], "explanations": {"榜": "正确。“贴在榜上”指把成绩贴在公开张贴的名单上。", "天空": "语义：考试成绩是公开张贴的名单，不能贴在天空上。", "面包": "语义：成绩不能贴在面包上，面包不是可以张贴东西的平面。", "空气": "搭配：“贴在…上”需要有平面的载体，不能说贴在空气上。"}, "sentence_index": 0, "correct_answer": "榜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师说他是我们学习的榜。", "explanation": "这里应该用〈榜样〉。榜指张贴的名单或文告，值得学习的人要说榜样。"}, {"text": "他每天早上用榜刷牙。", "explanation": "这里应该用〈牙刷〉。榜指张贴的名单或文告，刷牙的工具要说牙刷。"}, {"text": "他在墙上贴了一把榜。", "explanation": "这里应该用〈张〉。榜是张贴的纸，量词用“张”；“把”用于有柄的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b555da5e-4b5e-4652-842c-ecafaf616c3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96036, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "榜", "is_correct": true, "explanation": "正确。榜（bǎng）指张贴的名单或文告。"}, {"text": "邦", "is_correct": false, "explanation": "榜（第三声）与邦（第一声）声调不同，邦意思是国家。"}, {"text": "磅", "is_correct": false, "explanation": "榜（第三声）与磅（第四声）声调不同，磅是重量单位。"}, {"text": "傍", "is_correct": false, "explanation": "榜（第三声）与傍（第四声）声调不同，傍意思是靠近。"}], "explanations": {"榜": "正确。榜（bǎng）指张贴的名单或文告。", "邦": "榜（第三声）与邦（第一声）声调不同，邦意思是国家。", "磅": "榜（第三声）与磅（第四声）声调不同，磅是重量单位。", "傍": "榜（第三声）与傍（第四声）声调不同，傍意思是靠近。"}, "sentence_index": null, "correct_answer": "榜"}, "level_3": {"options": [{"text": "榜", "is_correct": true, "explanation": "正确。“榜上”指公开张贴的名单上，“榜上的第一名”即名单上排第一的人。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“第一名”是名次，不会写在桌子上，句子无法成立。"}, {"text": "云朵", "is_correct": false, "explanation": "语义：云朵上不能张贴名次，句子无法成立。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：名次不会出现在窗户上，句子与常理不符。"}], "explanations": {"榜": "正确。“榜上”指公开张贴的名单上，“榜上的第一名”即名单上排第一的人。", "桌子": "语义：“第一名”是名次，不会写在桌子上，句子无法成立。", "云朵": "语义：云朵上不能张贴名次，句子无法成立。", "窗户": "语义：名次不会出现在窗户上，句子与常理不符。"}, "sentence_index": 6, "correct_answer": "榜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用榜擦干净了桌子。", "explanation": "这里应该用〈抹布〉。榜指张贴的名单或文告，擦桌子的布要说抹布。"}, {"text": "服务员递给我一张榜，上面写着今天的菜。", "explanation": "这里应该用〈菜单〉。榜是张贴的名单或文告，写着菜名的纸要说菜单。"}, {"text": "他获得了一张榜，很骄傲。", "explanation": "这里应该用〈奖状〉。榜是公开的名单，获奖证书要说奖状。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b555da5e-4b5e-4652-842c-ecafaf616c3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96036, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "墙上贴着两只榜。", "corrected_sentence": "墙上贴着两张榜。", "error_description": "错误：“两只榜”。正确：“两张榜”。榜是纸质的张贴物，量词用“张”；“只”多用于动物或成对的小东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b555da5e-4b5e-4652-842c-ecafaf616c3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96036, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "校门口贴着一本榜，上面写着名单。", "corrected_sentence": "校门口贴着一张榜，上面写着名单。", "error_description": "错误：“一本榜”。正确：“一张榜”。“本”用于书册，榜是张贴的纸，量词应该用“张”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b555da5e-4b5e-4652-842c-ecafaf616c3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
