INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96038, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "使人愉快的兴味。", "primary_collocate": null, "pronunciation": "lè qù", "ipa": "lɤ˥˩ tɕʰy˥˩", "syllable_count": 2, "sentences": [{"text": "钓鱼的乐趣在于耐心地等待。", "target_word": "乐趣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就爱画画，一直享受着画画的乐趣。", "target_word": "乐趣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作太累，他已经感觉不到生活的乐趣。", "target_word": "乐趣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏有很多乐趣，大人小孩都喜欢。", "target_word": "乐趣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "唱歌给我的生活增添了不少乐趣。", "target_word": "乐趣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大自然里有数不清的乐趣。", "target_word": "乐趣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷说，下棋的乐趣就是和朋友聊天。", "target_word": "乐趣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们体会到了劳动的乐趣。", "target_word": "乐趣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把照顾小狗当成每天的乐趣。", "target_word": "乐趣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只要用心，生活中处处都有乐趣。", "target_word": "乐趣", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种乐趣", "label": "量词"}], "register": "中性", "sense_fingerprint": "使人愉快的兴味", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bea46ef-39b9-4ce5-886b-856ed2cce768') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96038, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "乐趣", "is_correct": true, "explanation": "正确。“钓鱼的乐趣在于耐心地等待”指钓鱼让人愉快的地方。"}, {"text": "鱼竿", "is_correct": false, "explanation": "语义：鱼竿是工具，不能“在于耐心地等待”。"}, {"text": "鱼塘", "is_correct": false, "explanation": "语义：鱼塘是地方，不能说它在于耐心等待。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“钓鱼的价格”不成立，钓鱼的好处要说乐趣，不说价格。"}], "explanations": {"乐趣": "正确。“钓鱼的乐趣在于耐心地等待”指钓鱼让人愉快的地方。", "鱼竿": "语义：鱼竿是工具，不能“在于耐心地等待”。", "鱼塘": "语义：鱼塘是地方，不能说它在于耐心等待。", "价格": "搭配：“钓鱼的价格”不成立，钓鱼的好处要说乐趣，不说价格。"}, "sentence_index": 0, "correct_answer": "乐趣"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "运动对身体有很多乐趣。", "explanation": "这里应该用〈益处〉。乐趣指愉快的兴味，运动对身体的好处要说益处。"}, {"text": "他买了一颗乐趣。", "explanation": "这里应该用〈种〉。乐趣是抽象的感受，量词用“种”，“颗”用于小而圆的东西。"}, {"text": "他把乐趣放进了冰箱。", "explanation": "这里应该用〈食物〉。乐趣是抽象的感受，不能放进冰箱，放进冰箱的要说食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b555da5e-4b5e-4652-842c-ecafaf616c3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96038, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "乐趣", "is_correct": true, "explanation": "正确。“下棋的乐趣就是和朋友聊天”指下棋让人愉快的地方。"}, {"text": "规则", "is_correct": false, "explanation": "语义：规则是下棋必须遵守的条文，不能等于和朋友聊天。"}, {"text": "棋盘", "is_correct": false, "explanation": "语义：棋盘是下棋用的工具，不能说它就是和朋友聊天。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“下棋的价格”不成立，下棋的好处要说乐趣，不说价格。"}], "explanations": {"乐趣": "正确。“下棋的乐趣就是和朋友聊天”指下棋让人愉快的地方。", "规则": "语义：规则是下棋必须遵守的条文，不能等于和朋友聊天。", "棋盘": "语义：棋盘是下棋用的工具，不能说它就是和朋友聊天。", "价格": "搭配：“下棋的价格”不成立，下棋的好处要说乐趣，不说价格。"}, "sentence_index": 6, "correct_answer": "乐趣"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "节日里，孩子们收到了一份乐趣。", "explanation": "这里应该用〈惊喜〉。乐趣是做事时的愉快兴味，不能像礼物一样收到，意外的高兴要说惊喜。"}, {"text": "她买了一片乐趣。", "explanation": "这里应该用〈种〉。乐趣是抽象的感受，量词用“种”，“片”用于薄而平的东西。"}, {"text": "这种食物含有丰富的乐趣。", "explanation": "这里应该用〈营养〉。乐趣指愉快的兴味，食物所含的有益成分要说营养。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b555da5e-4b5e-4652-842c-ecafaf616c3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96038, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把照顾花草当作一只乐趣。", "corrected_sentence": "他把照顾花草当作一种乐趣。", "error_description": "错误：“一只乐趣”。正确：“一种乐趣”。“只”不用于抽象的感受，乐趣的量词应该用“种”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b555da5e-4b5e-4652-842c-ecafaf616c3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96038, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他从这件事里得到了一片乐趣。", "corrected_sentence": "他从这件事里得到了一种乐趣。", "error_description": "错误：“一片乐趣”。正确：“一种乐趣”。“片”用于薄而平的东西，乐趣是抽象的感受，量词应该用“种”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b555da5e-4b5e-4652-842c-ecafaf616c3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
