INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96041, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "此处是这个地方。", "primary_collocate": null, "pronunciation": "cǐ chù", "ipa": "tsʰɯ˨˩˦ ʈʂʰu˥˩", "syllable_count": 2, "sentences": [{"text": "此处是我家，欢迎你来玩。", "target_word": "此处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请在此处写上你的名字。", "target_word": "此处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此处原来是一个小公园。", "target_word": "此处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说：“请大家看此处的图。”", "target_word": "此处", "complexity_tier": "T3", "furigana": "cǐ chù", "sentence_source": "generated"}, {"text": "此处有水，请小心滑倒。", "target_word": "此处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在此处休息一会儿吧。", "target_word": "此处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门口写着：此处不能抽烟。", "target_word": "此处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在此处住了二十年。", "target_word": "此处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们站在此处，可以看见整个城市。", "target_word": "此处", "complexity_tier": "T3", "furigana": "cǐ chù", "sentence_source": "generated"}, {"text": "此处的人都很热情。", "target_word": "此处", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "此處", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "指示代词，指这个地方，常见于告示、说明和叙述", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb1898af-5781-4ad1-8f77-3a10637e8fd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96041, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "此处", "is_correct": true, "explanation": "“此处”指这个地方，作主语，与“是我家”搭配，表示这里就是我家。"}, {"text": "此时", "is_correct": false, "explanation": "语义：“此时”指时间，时间不能是“我家”。"}, {"text": "那样", "is_correct": false, "explanation": "搭配：“那样”指方式或情况，不能与“是我家”这样的判断搭配。"}, {"text": "哪里", "is_correct": false, "explanation": "语义：“哪里”表示疑问，不能用来肯定地说“是我家，欢迎你来玩”。"}], "explanations": {"此处": "“此处”指这个地方，作主语，与“是我家”搭配，表示这里就是我家。", "此时": "语义：“此时”指时间，时间不能是“我家”。", "那样": "搭配：“那样”指方式或情况，不能与“是我家”这样的判断搭配。", "哪里": "语义：“哪里”表示疑问，不能用来肯定地说“是我家，欢迎你来玩”。"}, "sentence_index": 0, "correct_answer": "此处"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把此处带回了家。", "explanation": "此处指地点，不是东西，不能被“带回家”；把地方当物品搬运是用错了这个词。"}, {"text": "此处是我的老师，他教了我三年。", "explanation": "语义：此处只指地点，不能用来指人。这里把老师说成“此处”，应改用“他”或直接说“老师”。"}, {"text": "我最喜欢吃此处。", "explanation": "语义：此处指地点，不是可以吃的东西，不能作“吃”的对象；想说喜欢的食物，要说具体的菜名或食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2ee84d4-fb1b-4079-81e2-ab1f9c38f119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96041, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "此处", "is_correct": true, "explanation": "“此处”指这个地点，在告示中作主语，表示这里不能抽烟。"}, {"text": "彼时", "is_correct": false, "explanation": "语义：“彼时”指时间，不指地点，时间不能作禁烟的对象。"}, {"text": "其中", "is_correct": false, "explanation": "配价：“其中”需要前面有一个整体作范围，门口的告示没有这样的范围，句子不成立。"}, {"text": "何处", "is_correct": false, "explanation": "搭配：“何处”是疑问词，告示用陈述语气，与“不能抽烟”的禁止语气不搭配。"}], "explanations": {"此处": "“此处”指这个地点，在告示中作主语，表示这里不能抽烟。", "彼时": "语义：“彼时”指时间，不指地点，时间不能作禁烟的对象。", "其中": "配价：“其中”需要前面有一个整体作范围，门口的告示没有这样的范围，句子不成立。", "何处": "搭配：“何处”是疑问词，告示用陈述语气，与“不能抽烟”的禁止语气不搭配。"}, "sentence_index": 6, "correct_answer": "此处"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家的狗叫此处，它很聪明。", "explanation": "语义：此处只指地点，不能当名字用。给狗起名要用“小黑”之类的名字，不能说“叫此处”。"}, {"text": "我的书包里有很多此处。", "explanation": "语义：此处是指示地点的词，不是可以计数的具体东西，不能说“很多此处”；表示多个地方要说“很多地方”。"}, {"text": "他的汽车比此处还贵。", "explanation": "此处指地方，不能拿来和汽车比价钱；比较价格要用东西或人作比较对象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2ee84d4-fb1b-4079-81e2-ab1f9c38f119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96041, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们从此处建了一座学校。", "corrected_sentence": "他们在此处建了一座学校。", "error_description": "错误形式“他们从此处建了一座学校”，正确形式“他们在此处建了一座学校”。“从”表示起点，不表示动作发生的地点；建学校的地点要用介词“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2ee84d4-fb1b-4079-81e2-ab1f9c38f119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96041, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们此处待了两天。", "corrected_sentence": "我们在此处待了两天。", "error_description": "错误形式“我们此处待了两天”，正确形式“我们在此处待了两天”。处所词作地点状语前要加介词“在”，漏掉“在”就不成句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2ee84d4-fb1b-4079-81e2-ab1f9c38f119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
