INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96047, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "海关是在国家边上，检查进出的人和东西的地方。", "primary_collocate": null, "pronunciation": "hǎi guān", "ipa": "xaɪ˨˩˦ kwan˥", "syllable_count": 2, "sentences": [{"text": "我们在海关排队等了很久。", "target_word": "海关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海关就在机场的二楼。", "target_word": "海关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过海关的时候，要拿出护照。", "target_word": "海关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海关里人很多，我们等了一个小时。", "target_word": "海关", "complexity_tier": "T3", "furigana": "hǎi guān", "sentence_source": "generated"}, {"text": "行李在海关要全部检查一遍。", "target_word": "海关", "complexity_tier": "T3", "furigana": "hǎi guān", "sentence_source": "generated"}, {"text": "下飞机后，我先去海关。", "target_word": "海关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海关门口有很多人在等朋友。", "target_word": "海关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她第一次出国，在海关有点紧张。", "target_word": "海关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海关旁边有一家小商店。", "target_word": "海关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "通过海关以后，我们坐车去了酒店。", "target_word": "海关", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "海關", "label": "繁体"}, {"form": "海关人员", "label": "复合"}], "register": "中性", "sense_fingerprint": "机场、港口等处检查进出人员和物品的地点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb1898af-5781-4ad1-8f77-3a10637e8fd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96047, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "海关", "is_correct": true, "explanation": "“海关”是检查出入境人员和物品的地点，可以作“在……排队”的场所。"}, {"text": "行李", "is_correct": false, "explanation": "语义：行李是物品，不是可以排队的场所，“在行李排队”说不通。"}, {"text": "护照", "is_correct": false, "explanation": "搭配：“排队”需要地点名词作场所，护照是证件，“在护照排队”不搭配。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不是人排队的地方，句中“排队等了很久”的场所不可能是冰箱。"}], "explanations": {"海关": "“海关”是检查出入境人员和物品的地点，可以作“在……排队”的场所。", "行李": "语义：行李是物品，不是可以排队的场所，“在行李排队”说不通。", "护照": "搭配：“排队”需要地点名词作场所，护照是证件，“在护照排队”不搭配。", "冰箱": "语义：冰箱不是人排队的地方，句中“排队等了很久”的场所不可能是冰箱。"}, "sentence_index": 0, "correct_answer": "海关"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们付了很多海关。", "explanation": "这里应该用〈关税〉。海关是检查机构，交的钱是关税，不能说付了“海关”。"}, {"text": "我们去了一台海关。", "explanation": "量词用错。“台”用于机器，海关是机构，应用“个”。"}, {"text": "我住在海关，每天都很忙。", "explanation": "语义：海关是政府的检查机构，不是人住的地方，“住在海关”用错了这个词的意义。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2ee84d4-fb1b-4079-81e2-ab1f9c38f119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96047, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "海关", "is_correct": true, "explanation": "“海关”是检查场所，有门口，可以说“海关门口”。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙没有门口，“钥匙门口”说不通。"}, {"text": "书包", "is_correct": false, "explanation": "搭配：“门口”需要建筑或场所，书包不说门口，“书包门口”不搭配。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机不是有门口的场所，句子说门口有很多人等朋友，手机无法成立。"}], "explanations": {"海关": "“海关”是检查场所，有门口，可以说“海关门口”。", "钥匙": "语义：钥匙没有门口，“钥匙门口”说不通。", "书包": "搭配：“门口”需要建筑或场所，书包不说门口，“书包门口”不搭配。", "手机": "语义：手机不是有门口的场所，句子说门口有很多人等朋友，手机无法成立。"}, "sentence_index": 6, "correct_answer": "海关"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们把海关寄到了北京。", "explanation": "语义：海关是机构，不是物品，不能被“寄”，这个词不这么用。"}, {"text": "我们吃了一碗海关。", "explanation": "量词和语义都错：“碗”用于盛装食物的器皿，海关是机构，不能吃；这里应说“吃了一碗面”。"}, {"text": "海关喝了一杯水。", "explanation": "语义：海关是场所，不会喝水，主语应是人，这里用错了词的意义。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2ee84d4-fb1b-4079-81e2-ab1f9c38f119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96047, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只海关门口很热闹。", "corrected_sentence": "这个海关门口很热闹。", "error_description": "错误形式“这只海关门口很热闹”，正确形式“这个海关门口很热闹”。“海关”在此指检查场所，量词应用“个”，用“只”是量词用错了。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2ee84d4-fb1b-4079-81e2-ab1f9c38f119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96047, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们在海关把检查了护照。", "corrected_sentence": "我们在海关检查了护照。", "error_description": "错误：「把」字误放在动词「检查」前，「把」字后缺少宾语，句子不成立。正确：「我们在海关检查了护照」，删去多余的「把」即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2ee84d4-fb1b-4079-81e2-ab1f9c38f119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96048, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2ee84d4-fb1b-4079-81e2-ab1f9c38f119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96048, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2ee84d4-fb1b-4079-81e2-ab1f9c38f119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96048, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "设在国境口岸，检查进出境人员、货物的机关。", "primary_collocate": null, "pronunciation": "hǎi guān", "ipa": "xaɪ˨˩˦ kwan˥", "syllable_count": 2, "sentences": [{"text": "海关规定，水果不能带进这个国家。", "target_word": "海关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海关工作人员每天检查很多货物。", "target_word": "海关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的货要先交给海关。", "target_word": "海关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海关发现了一批没有申报的东西。", "target_word": "海关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想在海关工作，保护国家安全。", "target_word": "海关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海关提醒大家，不要带危险品出国。", "target_word": "海关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海关的网站上可以查进口的规定。", "target_word": "海关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海关对进口的东西收税。", "target_word": "海关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国海关欢迎外国朋友来旅游。", "target_word": "海关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海关做了新规定，旅客要填表。", "target_word": "海关", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "海關", "label": "繁体"}, {"form": "海关人员", "label": "复合"}], "register": "中性", "sense_fingerprint": "负责监管进出境人员、货物并征收关税的国家机关", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb1898af-5781-4ad1-8f77-3a10637e8fd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96048, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "海关", "is_correct": true, "explanation": "“海关”是管理进出境货物的机关，可以制定进境规定。"}, {"text": "学校", "is_correct": false, "explanation": "语义：学校不负责国家的进出境物品规定，句中说水果不能带进国家，学校不成立。"}, {"text": "医院", "is_correct": false, "explanation": "语义：医院的规定管不到国家的进境物品，句子的主语说不通。"}, {"text": "飞机", "is_correct": false, "explanation": "搭配：飞机不能“规定”，“规定”的主语要是机关或人，“飞机规定”不搭配。"}], "explanations": {"海关": "“海关”是管理进出境货物的机关，可以制定进境规定。", "学校": "语义：学校不负责国家的进出境物品规定，句中说水果不能带进国家，学校不成立。", "医院": "语义：医院的规定管不到国家的进境物品，句子的主语说不通。", "飞机": "搭配：飞机不能“规定”，“规定”的主语要是机关或人，“飞机规定”不搭配。"}, "sentence_index": 0, "correct_answer": "海关"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的孩子在海关学习汉字。", "explanation": "语义：海关是检查进出境人员和货物的机关，不是学习的场所，“在海关学习”用错了这个词的意义。"}, {"text": "我们在机场看见了一块海关。", "explanation": "量词用错。“块”用于片状的东西，海关是机关，应用“个”。"}, {"text": "他是一位很好的海关。", "explanation": "语义：海关指机关，不指人，说人应用“海关人员”或“海关工作人员”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2ee84d4-fb1b-4079-81e2-ab1f9c38f119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96048, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "海关", "is_correct": true, "explanation": "“海关”的网站可以查询进口规定，与句子的语境相符。"}, {"text": "饭店", "is_correct": false, "explanation": "语义：饭店不发布进口规定，“饭店的网站上查进口规定”说不通。"}, {"text": "书包", "is_correct": false, "explanation": "搭配：书包没有网站，不能说“书包的网站”。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：冰箱没有网站可以查规定，“冰箱的网站”不搭配。"}], "explanations": {"海关": "“海关”的网站可以查询进口规定，与句子的语境相符。", "饭店": "语义：饭店不发布进口规定，“饭店的网站上查进口规定”说不通。", "书包": "搭配：书包没有网站，不能说“书包的网站”。", "冰箱": "搭配：冰箱没有网站可以查规定，“冰箱的网站”不搭配。"}, "sentence_index": 6, "correct_answer": "海关"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "旅客要带着海关出境。", "explanation": "这里应该用〈护照〉。出境时带的是护照，海关是机构，不能被携带。"}, {"text": "我的钥匙是海关。", "explanation": "语义：海关是机关名称，不是钥匙这样的物品，不能作“钥匙”的表语；这里用错了词，应说“钥匙在包里”之类。"}, {"text": "这家海关比我的朋友还高。", "explanation": "语义：海关是机关，不是可以拿来比高矮的人或物，比较对象用错了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2ee84d4-fb1b-4079-81e2-ab1f9c38f119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96048, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在海关把办了手续。", "corrected_sentence": "我们在海关办了手续。", "error_description": "错误：「把」字误放在动词「办」前，「把」字后缺少宾语，句子不成立。正确：「我们在海关办了手续」，删去多余的「把」即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2ee84d4-fb1b-4079-81e2-ab1f9c38f119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96048, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "海关查很仔细。", "corrected_sentence": "海关查得很仔细。", "error_description": "错误形式“海关查很仔细”，正确形式“海关查得很仔细”。动词后带补语说明程度时要用“得”，漏掉“得”就不成句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2ee84d4-fb1b-4079-81e2-ab1f9c38f119') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
