INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96051, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "炮是一种打仗用的大武器，能把炸弹远远地打出去。", "primary_collocate": null, "pronunciation": "pào", "ipa": "pʰɑʊ˥˩", "syllable_count": 1, "sentences": [{"text": "士兵们把炮推到山边，准备打仗。", "target_word": "炮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这门炮很重，十个人才推得动。", "target_word": "炮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打仗时，他们用炮把炸弹打到远处。", "target_word": "炮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "敌人的炮打过来了，大家赶紧躲起来。", "target_word": "炮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上架着一门炮，对着前面的路。", "target_word": "炮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古时候的炮没有现在的炮打得远。", "target_word": "炮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战士们一听命令就开炮。", "target_word": "炮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那门炮能把炸弹打出几公里远。", "target_word": "炮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆里有一门老炮，是打仗时用的。", "target_word": "炮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争时，村子里的人常常听到炮响。", "target_word": "炮", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "门", "label": "量词"}, {"form": "大炮", "label": "复合"}], "register": "中性", "sense_fingerprint": "打仗用的大武器，能把炸弹打到远处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12e20994-e992-4078-8ede-1891344b5f09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96051, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "炮", "is_correct": true, "explanation": "正确：炮（pào）指打仗用的大武器，能把炸弹打到远处。"}, {"text": "跑", "is_correct": false, "explanation": "跑（pǎo）与 pào 声调不同（第三声与第四声），意思是奔跑。"}, {"text": "袍", "is_correct": false, "explanation": "袍（páo）与 pào 声调不同（第二声与第四声），意思是长衣服，如长袍。"}, {"text": "抱", "is_correct": false, "explanation": "抱（bào）与 pào 声母不同：bào 的 b 不送气，pào 的 p 送气，意思是用手臂围住。"}, {"text": "报", "is_correct": false, "explanation": "报（bào）与 pào 声母不同（b 不送气，p 送气），意思是报纸、报告。"}], "explanations": {"炮": "正确：炮（pào）指打仗用的大武器，能把炸弹打到远处。", "跑": "跑（pǎo）与 pào 声调不同（第三声与第四声），意思是奔跑。", "袍": "袍（páo）与 pào 声调不同（第二声与第四声），意思是长衣服，如长袍。", "抱": "抱（bào）与 pào 声母不同：bào 的 b 不送气，pào 的 p 送气，意思是用手臂围住。", "报": "报（bào）与 pào 声母不同（b 不送气，p 送气），意思是报纸、报告。"}, "sentence_index": null, "correct_answer": "炮"}, "level_3": {"options": [{"text": "炮", "is_correct": true, "explanation": "正确：炮是打仗用的大武器，士兵把它推到山边，符合句意。"}, {"text": "书", "is_correct": false, "explanation": "语义：书不是武器，不能用来打仗。"}, {"text": "饭", "is_correct": false, "explanation": "搭配：“推”后面的东西要是能推动的器械，不说“推饭”。"}, {"text": "花", "is_correct": false, "explanation": "语义：花与打仗毫不相干，不能推到山边去准备打仗。"}], "explanations": {"炮": "正确：炮是打仗用的大武器，士兵把它推到山边，符合句意。", "书": "语义：书不是武器，不能用来打仗。", "饭": "搭配：“推”后面的东西要是能推动的器械，不说“推饭”。", "花": "语义：花与打仗毫不相干，不能推到山边去准备打仗。"}, "sentence_index": 0, "correct_answer": "炮"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他举起炮，瞄准了远处的目标。", "explanation": "这里应该用〈枪〉。“举起”和“瞄准”多用于手能握住的武器，炮体积大，一个人举不起来。"}, {"text": "春节晚上，我们放炮庆祝新年。", "explanation": "这里的“炮”指爆竹，不是打仗用的大武器；“放炮”在春节指燃放鞭炮，是另一个义项。"}, {"text": "那只炮很重，士兵们推了很久。", "explanation": "这里应该用〈门〉。炮是武器，量词用“门”；“只”多用于动物或成对的东西，不能用于炮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a59c85b2-e44c-4a84-af05-b463277db9d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96051, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "炮", "is_correct": true, "explanation": "正确：炮（pào）指打仗用的大武器，能把炸弹打到远处。"}, {"text": "刨", "is_correct": false, "explanation": "刨（páo）与 pào 声调不同（第二声与第四声），意思是用刨子削平木头。"}, {"text": "豹", "is_correct": false, "explanation": "豹（bào）与 pào 声母不同：bào 的 b 不送气，pào 的 p 送气，意思是豹子。"}, {"text": "暴", "is_correct": false, "explanation": "暴（bào）与 pào 声母不同（b 不送气，p 送气），意思是猛烈、凶暴。"}, {"text": "爆", "is_correct": false, "explanation": "爆（bào）与 pào 声母不同（b 不送气，p 送气），意思是爆炸、爆开。"}], "explanations": {"炮": "正确：炮（pào）指打仗用的大武器，能把炸弹打到远处。", "刨": "刨（páo）与 pào 声调不同（第二声与第四声），意思是用刨子削平木头。", "豹": "豹（bào）与 pào 声母不同：bào 的 b 不送气，pào 的 p 送气，意思是豹子。", "暴": "暴（bào）与 pào 声母不同（b 不送气，p 送气），意思是猛烈、凶暴。", "爆": "爆（bào）与 pào 声母不同（b 不送气，p 送气），意思是爆炸、爆开。"}, "sentence_index": null, "correct_answer": "炮"}, "level_3": {"options": [{"text": "炮", "is_correct": true, "explanation": "正确：“开炮”指发射炮弹，符合战士听命令作战的语境。"}, {"text": "灯", "is_correct": false, "explanation": "语义：“开灯”与听命令作战不合，灯不能用于作战。"}, {"text": "书", "is_correct": false, "explanation": "搭配：“开”后面不直接接“书”，要说“打开书”。"}, {"text": "票", "is_correct": false, "explanation": "语义：“开票”指开具票据，与战士听命令的语境不合。"}], "explanations": {"炮": "正确：“开炮”指发射炮弹，符合战士听命令作战的语境。", "灯": "语义：“开灯”与听命令作战不合，灯不能用于作战。", "书": "搭配：“开”后面不直接接“书”，要说“打开书”。", "票": "语义：“开票”指开具票据，与战士听命令的语境不合。"}, "sentence_index": 6, "correct_answer": "炮"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一用力，把炮扔进了河里。", "explanation": "这里应该用〈手雷〉。“扔”多用于手能拿起的小东西，炮太大太重，不能用手扔。"}, {"text": "他把炮移到中间，准备吃掉对方的车。", "explanation": "这里的“炮”指象棋中的棋子，不是打仗用的大武器；句子在象棋里成立，但不是本词的武器义。"}, {"text": "那颗炮很重，士兵们抬了很久。", "explanation": "这里应该用〈门〉。炮用量词“门”；“颗”多用于炸弹、子弹等小而圆的东西，不用于炮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a59c85b2-e44c-4a84-af05-b463277db9d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96051, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们去郊外看了一个老炮。", "corrected_sentence": "我们去郊外看了一门老炮。", "error_description": "量词错误：指武器“炮”要用量词“门”，不能用“个”。应说“一门老炮”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a59c85b2-e44c-4a84-af05-b463277db9d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96051, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这门炮打很远。", "corrected_sentence": "这门炮打得很远。", "error_description": "补语错误：表示“打得怎么样”要用“得”连接补语，“打很远”缺少“得”，应说“打得很远”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a59c85b2-e44c-4a84-af05-b463277db9d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
