INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96055, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "病例是一个人生了某种病的记录。", "primary_collocate": null, "pronunciation": "bìng lì", "ipa": "piŋ˥˩ li˥˩", "syllable_count": 2, "sentences": [{"text": "医生正在看你的病例。", "target_word": "病例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把病例带到医院来。", "target_word": "病例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "护士把我的病例放在桌子上。", "target_word": "病例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病例上写着他的名字和年龄。", "target_word": "病例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病例上写着他三年前得过胃病。", "target_word": "病例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想复印一下爸爸的病例。", "target_word": "病例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生看了病例，说他需要休息。", "target_word": "病例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他忘了带病例，只好明天再来。", "target_word": "病例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教学生们怎么写病例。", "target_word": "病例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的病例我已经看过了。", "target_word": "病例", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "确诊病例", "label": "复合"}], "register": "书面", "sense_fingerprint": "病人生病情况的记录", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f70932a1-bdd7-4a4c-af20-13ec35292e99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96055, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "病例", "is_correct": true, "explanation": "正确：bìng lì 指病人病情的记录。"}, {"text": "病理", "is_correct": false, "explanation": "bìng lǐ 与 bìng lì 第二音节声调不同（第三声与第四声），意思是病理。"}, {"text": "兵力", "is_correct": false, "explanation": "bīng lì 与 bìng lì 第一音节声调不同（第一声与第四声），意思是兵力。"}, {"text": "冰梨", "is_correct": false, "explanation": "bīng lí 与 bìng lì 两个音节声调都不同，意思是一种梨。"}], "explanations": {"病例": "正确：bìng lì 指病人病情的记录。", "病理": "bìng lǐ 与 bìng lì 第二音节声调不同（第三声与第四声），意思是病理。", "兵力": "bīng lì 与 bìng lì 第一音节声调不同（第一声与第四声），意思是兵力。", "冰梨": "bīng lí 与 bìng lì 两个音节声调都不同，意思是一种梨。"}, "sentence_index": null, "correct_answer": "病例"}, "level_3": {"options": [{"text": "病例", "is_correct": true, "explanation": "正确：“病例”指病人病情的记录，医生查看的是这份记录，符合语境。"}, {"text": "菜单", "is_correct": false, "explanation": "语义：医生查看的是病人的诊疗记录，“菜单”与此无关，句意不符。"}, {"text": "病毒", "is_correct": false, "explanation": "语义：“病毒”是微生物，不是医生“看”的对象，句意不符。"}, {"text": "病魔", "is_correct": false, "explanation": "语域：“病魔”是文学比喻，不用于指病人的记录。"}], "explanations": {"病例": "正确：“病例”指病人病情的记录，医生查看的是这份记录，符合语境。", "菜单": "语义：医生查看的是病人的诊疗记录，“菜单”与此无关，句意不符。", "病毒": "语义：“病毒”是微生物，不是医生“看”的对象，句意不符。", "病魔": "语域：“病魔”是文学比喻，不用于指病人的记录。"}, "sentence_index": 0, "correct_answer": "病例"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生喝了一份病例。", "explanation": "这里应该用〈药〉。“病例”是记录，不能喝。"}, {"text": "病例很害怕，一直在哭。", "explanation": "这里应该用〈病人〉。“病例”是记录，不是人，不会害怕或哭。"}, {"text": "病例会在下午两点开会。", "explanation": "这里应该用〈医生〉。“病例”是记录，不会开会。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6857f85e-9171-4d03-8bfd-cc4d9981e1f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96055, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "病例", "is_correct": true, "explanation": "正确：“病例”指病人病情的记录，医生看了记录后才能判断，符合语境。"}, {"text": "作业", "is_correct": false, "explanation": "语义：“看作业”与医生判断病人需要休息无关。"}, {"text": "账单", "is_correct": false, "explanation": "语义：医生不会因为看了账单就判断病人需要休息。"}, {"text": "病床", "is_correct": false, "explanation": "搭配：“看病床”不是医生的常用说法，应说“查房”或“看病人”。"}], "explanations": {"病例": "正确：“病例”指病人病情的记录，医生看了记录后才能判断，符合语境。", "作业": "语义：“看作业”与医生判断病人需要休息无关。", "账单": "语义：医生不会因为看了账单就判断病人需要休息。", "病床": "搭配：“看病床”不是医生的常用说法，应说“查房”或“看病人”。"}, "sentence_index": 6, "correct_answer": "病例"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生给他开了一瓶病例。", "explanation": "这里应该用〈药〉。“病例”是记录，不能用“瓶”计量。"}, {"text": "他的病例已经开车回家了。", "explanation": "这里应该用〈他〉。“病例”是记录，不能开车。"}, {"text": "病例们一起聊天。", "explanation": "这里应该用〈病友〉。“病例”是记录，不是人，不能聊天。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6857f85e-9171-4d03-8bfd-cc4d9981e1f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96055, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "护士把一只病例交给了医生。", "corrected_sentence": "护士把一份病例交给了医生。", "error_description": "错误：“病例”作为记录用量词“份”，“只”只用于动物等，应改为“一份病例”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6857f85e-9171-4d03-8bfd-cc4d9981e1f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96055, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两病例需要医生签字后才能归档。", "corrected_sentence": "这两份病例需要医生签字后才能归档。", "error_description": "错误：数词“两”与“病例”之间漏掉量词，应为“这两份病例”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6857f85e-9171-4d03-8bfd-cc4d9981e1f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
